#!/usr/bin/python3

import time
import logging
import signal
import sys
from smbus2 import SMBus, i2c_msg

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ADS1015:
    """Driver for the Texas Instruments ADS1015 12-bit ADC."""

    REG_POINTER_CONVERT = 0x00
    REG_POINTER_CONFIG = 0x01
    REG_POINTER_LOWTHRESH = 0x02
    REG_POINTER_HITHRESH = 0x03
    REG_POINTER_ID = 0x04
    REG_POINTER_COMP_CONFIG = 0x04
    REG_POINTER_COMP_LATETIME = 0x05
    REG_POINTER_COMP_QUE = 0x06
    REG_POINTER_COMP_SAMPLE = 0x07
    REG_POINTER_COMP_RESULT = 0x08

    ADS1015_ID = 0x01
    ADS1015_MODE_SINGLE = 0x00
    ADS1015_MODE_CONTINUOUS = 0x01
    ADS1015_MODE_COMP = 0x02

    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.bus = None
        self._running = True

        try:
            self.bus = SMBus(busnum)
        except Exception as e:
            logger.error(f"Failed to initialize I2C bus {busnum}: {e}")
            raise

        if self.debug:
            logger.info(f"I2C bus {busnum} initialized. Waiting for ADS1015 at 0x{address:02X}...")
            time.sleep(0.1)

        try:
            self.id = self._read_register_u8(self.REG_POINTER_ID)
            if self.id != self.ADS1015_ID:
                raise RuntimeError(f"Invalid ADS1015 ID: 0x{self.id:02X}. Expected 0x{self.ADS1015_ID:02X}.")
        except Exception as e:
            logger.error(f"ADS1015 not found at 0x{address:02X}: {e}")
            self.close()
            raise

        logger.info("ADS1015 initialized successfully.")

    def _write_register(self, reg, value):
        try:
            self.bus.write_word_data(self.address, reg, value)
        except Exception as e:
            logger.error(f"I2C write error to register 0x{reg:02X}: {e}")
            raise

    def _read_register(self, reg):
        try:
            return self.bus.read_word_data(self.address, reg)
        except Exception as e:
            logger.error(f"I2C read error from register 0x{reg:02X}: {e}")
            raise

    def _read_register_u8(self, reg):
        try:
            return self._read_register(reg)
        except Exception:
            return None

    def _read_register_s8(self, reg):
        try:
            data = self._read_register(reg)
            if data is None:
                return None
            return data - 65536 if data > 32767 else data
        except Exception:
            return None

