#!/usr/bin/env python3

import time
import datetime
import csv
import signal
import sys
import os
import spidev
import RPi.GPIO as GPIO
import adafruit_dht
import board

# Configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
DHT_PIN = 4
TEMP_HUM_WINDOW = 5
CALIBRATION_TIME = 60
LOG_INTERVAL = 60

# Global state
spi = None
dht_device = None
running = True

def signal_handler(sig, frame):
    global running
    print(f"Received signal {sig}, shutting down...")
    running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.IN)

def setup_spi():
    global spi
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
    except Exception as e:
        log_error(f"SPI setup failed: {e}")
        sys.exit(1)

def setup_dht22():
    global dht_device
    try:
        dht_device = adafruit_dht.DHT22(board.D4)
    except Exception as e:
        log_error(f"DHT22 setup failed: {e}")
        sys.exit(1)

def read_mcp3008(channel):
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be 0-7")
    try:
        # MCP3008 single-ended read: start bit, config byte, padding
        r = spi.xfer2([1, (8 + channel) << 4, 0])
        return ((r[1] & 3) << 8) + r[2]
    except Exception as e:
        log_error(f"SPI read error on channel {channel}: {e}")
        return None

def read_dht22():
    try:
        temp = dht_device.temperature
        hum = dht_device.humidity
        if temp is None or hum is None:
            raise RuntimeError("DHT22 returned None")
        return temp, hum
    except Exception as e:
        log_error(f"DHT22 read error: {e}")
        return None, None

def moving_average(data, window):
    if len(data) < window:
        return None
    return sum(data[-window:]) / window

def validate_data(temp, hum):
    if temp is None or hum is None:
        return False
    if not (-20 <= temp <= 50):
        return False
    if not (0 <= hum <= 100):
        return False
    return True

def log_data(timestamp, temp, hum, mcp0, mcp1):
    try:
        with open("gas_data.csv", "a", newline="") as f:
            writer = csv.writer(f)
            writer.writerow([timestamp, temp, hum, mcp0, mcp1])
    except Exception as e:
        log_error(f"CSV write error: {e}")

def log_error(message):
    try:
        with open("error.log", "a") as f:
            f.write(f"{datetime.datetime.now()} - {message}\n")
    except Exception as e:
        print(f"CRITICAL: Cannot write to error.log: {e}")

def calibrate_sensors(window):
    print("Calibrating sensors...")
    mcp0_vals = []
    mcp1_vals = []
    start = time.time()
    while time.time() - start < CALIBRATION_TIME:
        t0, h0 = read_dht22()
        if t0 is not None and h0 is not None:
            mcp0_vals.append(t0)
            mcp1_vals.append(h0)
        time.sleep(0.1)
    mcp0_vals = mcp0_vals[-window:]
    mcp1_vals = mcp1_vals[-window:]
    if not mcp0_vals or not mcp1_vals:
        log_error("Calibration failed: no valid readings")
        return None, None
    avg0 = moving_average(mcp0_vals, window)
    avg1 = moving_average(mcp1_vals, window)
    print(f"Calibration: {avg0:.2f}C, {avg1:.2f}%")
    return avg0, avg1

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    setup_gpio()
    setup_spi()
    setup_dht22()
    print("Starting data logging...")
    while running:
        timestamp = datetime.datetime.now().isoformat()
        mcp0 = read_mcp3008(0)
        mcp1 = read_mcp3008(1)
        dht_temp, dht_hum = read_dht22()
        mcp0_val = moving_average(mcp0, TEMP_HUM_WINDOW) if mcp0 is not None else None
        mcp1_val = moving_average(mcp1, TEMP_HUM_WINDOW) if mcp1 is not None else None
        if not validate_data(dht_temp, dht_hum):
            log_error("DHT22 out of range")
            dht_temp, dht_hum = None, None
        if not validate_data(mcp0_val, mcp1_val):
            log_error("MCP3008 out of range")
            mcp0_val, mcp1_val = None, None
        if mcp0_val is not None and mcp1_val is not None:
            avg0 = moving_average(mcp0, TEMP_HUM_WINDOW)
            avg1 = moving_average(mcp1, TEMP_HUM_WINDOW)
            print(f"MCP0: {mcp0_val:.2f}, MCP1: {mcp1_val:.2f}, DHT: {dht_temp:.2f}, {dht_hum:.2f}")
        else:
            print(f"MCP0: {mcp0_val}, MCP1: {mcp1_val}, DHT: {dht_temp:.2f}, {dht_hum:.2f}")
        log_data(timestamp, dht_temp, dht_hum, mcp0_val, mcp1_val)
        if mcp0_val is not None and mcp1_val is not None:
            avg0, avg1 = mcp0_val, mcp1_val
        else:
            avg0, avg1 = None, None
        if avg0 is not None and avg1 is not None:
            print(f"Avg: {avg0:.2f}, {avg1:.2f}")
        else:
            print(f"Avg: {avg0}, {avg1}")
        time.sleep(LOG_INTERVAL)
    cleanup()

def cleanup():
    global spi, dht_device
    if spi:
        try:
            spi.close()
        except Exception:
            pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    GPIO.cleanup()
    print("Cleanup complete.")

if __name__ == "__main__":
    main()

