import time
import logging
import argparse
import queue
import threading
import spidev
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.last_event_time = 0.0
        self.running = True
        self.spi = None
        self.gpio_initialized = False
        self.gpio_pins_used = []
        self.setup_gpio()
        self.setup_spi()

    def setup_gpio(self):
        if self.gpio_pins:
            GPIO.setmode(GPIO.BCM)
            for pin in self.gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
                self.gpio_pins_used.append(pin)
            logging.info(f"GPIO pins {self.gpio_pins_used} configured as inputs.")
        else:
            logging.warning("No GPIO pins specified; using MCP3008 ADC.")

    def setup_spi(self):
        if self.channels:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            self.spi.mode = 0
            logging.info(f"SPI opened: bus 0, device 0, speed {self.spi_speed} Hz.")
        else:
            logging.warning("No channels specified; using digital sound sensor.")

    def read_digital_sensor(self, gpio_pin):
        try:
            return GPIO.input(gpio_pin)
        except Exception as e:
            logging.error(f"Error reading digital sensor on pin {gpio_pin}: {e}")
            return None

    def read_analog_sensor(self, channel):
        if not 0 <= channel <= 7:
            logging.error(f"Invalid channel {channel}; must be 0-7.")
            return None
        try:
            # Start bit, single-ended mode, channel select, dummy byte
            msg = [0x01, (0x08 + channel) << 4, 0x00]
            resp = self.spi.xfer2(msg)
            adc_value = ((resp[1] & 0x03) << 8) | resp[2]
            return adc_value
        except Exception as e:
            logging.error(f"Error reading analog sensor on channel {channel}: {e}")
            return None

    def read_sound_level(self):
        if self.sensor_type == "digital":
            if self.gpio_pins:
                pin = self.gpio_pins[0]
                return self.read_digital_sensor(pin)
            else:
                logging.error("Digital sensor: no GPIO pins configured.")
                return None
        elif self.sensor_type == "analog":
            if self.channels:
                channel = self.channels[0]
                return self.read_analog_sensor(channel)
            else:
                logging.error("Analog sensor: no channels specified.")
                return None
        else:
            logging.error(f"Invalid sensor type: {self.sensor_type}")
            return None

    def detect_sound(self, sound_level):
        if self.sensor_type == "digital":
            return sound_level == 1
        elif self.sensor_type == "analog":
            return sound_level >= self.threshold
        else:
            logging.error(f"Invalid sensor type: {self.sensor_type}")
            return False

    def log_event(self, event_type):
        if self.log_queue:
            self.log_queue.put(event_type)
        logging.info(f"Sound event detected: {event_type}")

    def run(self):
        while self.running:
            sound_level = self.read_sound_level()
            if sound_level is not None:
                if self.detect_sound(sound_level):
                    current_time = time.time()
                    if current_time - self.last_event_time > 0.1:
                        self.log_event("Sound Detected")
                        self.last_event_time = current_time
            time.sleep(1 / self.sample_rate)

    def stop(self):
        self.running = False
        if self.spi:
            self.spi.close()
            self.spi = None
        if self.gpio_initialized:
            GPIO.cleanup()
            self.gpio_initialized = False

def main():
    parser = argparse.ArgumentParser(description="Raspberry Pi Sound Sensor")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"])
    parser.add_argument("--threshold", type=int, required=True)
    parser.add_argument("--sample_rate", type=int, required=True)
    parser.add_argument("--log_file", default="sound_events.log")
    parser.add_argument("--gpio_pins", nargs="+", type=int, help="GPIO pins for digital sensor")
    parser.add_argument("--channels", nargs="+", type=int, help="MCP3008 channels for analog sensor")
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", nargs="+", help="Unique IDs for each sensor instance")
    args = parser.parse_args()

    sensors = []
    if args.gpio_pins:
        for i, pin in enumerate(args.gpio_pins):
            sensor = SoundSensor(args.sensor_ids[i], args.sensor_type, args.threshold, args.sample_rate, [pin], [i], args.spi_speed, None)
            sensor.log_queue = queue.Queue()
            sensor.start()
            sensors.append(sensor)
    elif args.channels:
        for i, channel in enumerate(args.channels):
            sensor = SoundSensor(args.sensor_ids[i], args.sensor_type, args.threshold, args.sample_rate, None, [channel], args.spi_speed, None)
            sensor.log_queue = queue.Queue()
            sensor.start()
            sensors.append(sensor)
    else:
        logging.error("No sensor type or channels specified. Exiting.")
        return

    def signal_handler(sig, frame):
        logging.info("KeyboardInterrupt received.")
        for sensor in sensors:
            sensor.stop()
        logging.shutdown()
        exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    for sensor in sensors:
        sensor.run()

    logging.shutdown()

if __name__ == "__main__":
    main()

