import time
import signal
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_BUS = 1
I2C_ADDRESS = 0x48          # ADS1115 default address (ADDR -> GND)
GAIN = 1                     # +/-4.096V range
SAMPLE_INTERVAL = 0.5       # seconds between readings
NUM_CHANNELS = 4

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_i2c = None
_adc = None


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _cleanup():
    """Release I2C / ADC resources."""
    global _adc, _i2c
    if _adc is not None:
        try:
            _adc.gain = GAIN
        except Exception:
            pass
        try:
            _adc.close()
        except Exception:
            pass
        _adc = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None


def _init_adc():
    """Initialize I2C bus and ADS1115; return (adc, channels) or raise."""
    global _i2c, _adc
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize I2C bus {I2C_BUS}: {exc}") from exc

    try:
        _adc = ADS.ADS1115(
            _i2c, address=I2C_ADDRESS, gain=GAIN
        )
        _adc.gain = GAIN
    except Exception as exc:
        raise RuntimeError(
            f"ADS1115 not found at 0x{I2C_ADDRESS:02X} on bus {I2C_BUS}: {exc}"
        ) from exc

    # Pre-create AnalogIn objects for all four channels
    channels = []
    for ch in range(NUM_CHANNELS):
        try:
            channels.append(AnalogIn(_adc, ch))
        except Exception as exc:
            raise RuntimeError(f"Failed to configure channel {ch}: {exc}") from exc

    return _adc, channels


def _print_header():
    """Print the channel-label header row."""
    print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format(*range(NUM_CHANNELS)))
    print("-" * 43)


def _print_row(channels):
    """Print a row of channel values."""
    for ch, val in enumerate(channels):
        try:
            print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format(
                ch, val.value, val.v_reference, val.code
            ))
        except Exception as exc:
            print(f"  [ERROR] channel {ch}: {exc}")


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        adc, channels = _init_adc()
    except RuntimeError as exc:
        print(f"Initialization error: {exc}")
        _cleanup()
        sys.exit(1)

    print("Reading ADS1115 channels A0-A3 (gain=1, +/-4.096V) "
          f"on I2C bus {I2C_BUS} @ 0x{I2C_ADDRESS:02X} "
          f"— press Ctrl-C to stop.\n")
    _print_header()

    try:
        while _running:
            _print_row(channels)
            time.sleep(SAMPLE_INTERVAL)
    except Exception as exc:
        print(f"\nUnexpected error: {exc}")
    finally:
        _cleanup()
        print("\nShutdown complete.")


if __name__ == "__main__":
    main()

