import cv2
import signal
import sys
import time
from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def cleanup(picam2=None):
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception:
            pass
    cv2.destroyAllWindows()

def main():
    global running
    picam2 = None
    try:
        face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
        if face_cascade.empty():
            raise RuntimeError('Failed to load face cascade classifier.')

        eye_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_eye.xml')
        if eye_cascade.empty():
            raise RuntimeError('Failed to load eye cascade classifier.')

        picam2 = Picamera2()
        picam2.configure(picam2.create_preview_configuration(main={'format': 'BGR888', 'size': (640, 480)}))
        picam2.start()
        time.sleep(1.0)

        while running:
            frame = picam2.capture_array()
            if frame is None:
                print('Warning: captured frame is None, skipping.')
                continue

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))

            for (x, y, w, h) in faces:
                cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
                roi_gray = gray[y:y + h, x:x + w]
                eyes = eye_cascade.detectMultiScale(roi_gray, scaleFactor=1.1, minNeighbors=3, minSize=(20, 20))
                for (ex, ey, ew, eh) in eyes:
                    cv2.rectangle(frame, (x + ex, y + ey), (x + ex + ew, y + ey + eh), (0, 0, 255), 2)

            cv2.imshow('Face and Eye Detection', frame)
            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except RuntimeError as e:
        print(f'Error: {e}', file=sys.stderr)
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
    finally:
        cleanup(picam2)

if __name__ == '__main__':
    main()

