import signal
import sys
import logging
from pathlib import Path

import cv2
import numpy as np
from picamera2 import Picamera2
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

CONFIG_FILE = Path("config.json")

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received.")

def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        return None
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from {config_file}: {e}")
        return None

def initialize_camera(resolution=(224, 224)):
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"size": resolution, "format": "BGR888"})
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None

def capture_image(picam2):
    try:
        return picam2.capture_array()
    except Exception as e:
        logging.error(f"Error capturing image: {e}")
        return None

def indicate_bird(led_pin):
    try:
        logging.info("Bird detected! Indicating with LED.")
        led_device.on()
        time.sleep(1)
        led_device.off()
    except Exception as e:
        logging.error(f"Error controlling LED: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    if not config:
        return

    led_device = None
    picam2 = None

    try:
        led_device = OutputDevice(config['gpio_led_pin'])
        if config['gpio_door_control']:
            door_device = OutputDevice(config['gpio_door_control_pin'])
        else:
            door_device = None

        picam2 = initialize_camera(config['camera_resolution'])
        if not picam2:
            return

        while running:
            image = capture_image(picam2)
            if image is None:
                time.sleep(0.1)
                continue

            # Simple bird detection: check for a specific color (e.g., red)
            # In a real application, this would be replaced with a trained model
            if np.any(image[:, :, 0] == 0):  # Check if any pixel is red
                indicate_bird(led_device)

            time.sleep(0.1)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if picam2:
            try:
                picam2.stop()
            except Exception as e:
                logging.error(f"Error stopping camera: {e}")
        if led_device:
            led_device.close()
        logging.info("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

