import time
import random
import signal
import sys
import board
import busio
import adafruit_amg88xx
from gpiozero import Buzzer

# Constants
BUZZER_PIN = 17
THERMAL_THRESHOLD = 30.0
LOOP_DELAY = 0.1
BUZZER_DURATION = 1.0

# Global resources for cleanup
buzzer = None
i2c_bus = None
thermal_sensor = None
running = True


def cleanup():
    """Release all hardware resources cleanly."""
    global buzzer, i2c_bus, thermal_sensor
    if buzzer is not None:
        try:
            buzzer.close()
        except Exception:
            pass
        buzzer = None
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        i2c_bus = None
    if thermal_sensor is not None:
        try:
            thermal_sensor.deinit()
        except Exception:
            pass
        thermal_sensor = None


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def init_buzzer():
    """Initialize the buzzer on GPIO17."""
    global buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Error initializing buzzer on GPIO{BUZZER_PIN}: {e}")
        raise


def init_thermal_sensor():
    """Initialize the AMG8833 thermal camera sensor on I2C address 0x69."""
    global i2c_bus, thermal_sensor
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        thermal_sensor = adafruit_amg88xx.AMG88XX(i2c_bus, addr=0x69)
        print("AMG8833 thermal camera initialized successfully.")
    except ValueError as e:
        print(f"AMG8833 not found at address 0x69: {e}")
        print("Simulating thermal data (8x8, random 20-45°C).")
        thermal_sensor = None
    except Exception as e:
        print(f"Error initializing AMG8833: {e}")
        thermal_sensor = None


def detect_human(thermal_data):
    """Detect a human presence based on thermal data."""
    if thermal_sensor is None:
        return False
    for row in thermal_data:
        for col in row:
            if col > THERMAL_THRESHOLD:
                return True
    return False


def trigger_alert(buzzer):
    """Sound the buzzer for 1 second."""
    if buzzer is None:
        return
    try:
        buzzer.on()
        time.sleep(BUZZER_DURATION)
        buzzer.off()
    except Exception as e:
        print(f"Error triggering buzzer alert: {e}")


def main():
    """Main loop: poll thermal data and trigger alert if human detected."""
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    init_buzzer()
    init_thermal_sensor()

    print("Thermal security system started. Press Ctrl+C to exit.")

    try:
        while running:
            if thermal_sensor is not None:
                try:
                    thermal_data = thermal_sensor.pixels
                except Exception as e:
                    print(f"Error reading thermal data: {e}")
                    thermal_data = [
                        [random.uniform(20.0, 45.0) for _ in range(8)]
                        for _ in range(8)
                    ]
            else:
                thermal_data = [
                    [random.uniform(20.0, 45.0) for _ in range(8)]
                    for _ in range(8)
                ]

            if detect_human(thermal_data):
                print("Human detected! Triggering alert.")
                trigger_alert(buzzer)
            else:
                print("No human detected.")

            time.sleep(LOOP_DELAY)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        print("System shutdown complete.")


if __name__ == "__main__":
    main()

