PCF8574_ADDR = 0x20
SENSOR_PINS = 8          # P0..P7 on the PCF8574
PROXIMITY_PIN = 17       # BCM 17 (active-low interrupt)
DEBOUNCE_MS = 50
LOOP_DELAY_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
_running = True
_bus = None
_sensor_button = None


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _read_pcf8574_raw(bus):
    """Read all 8 bits from the PCF8574; return list of 0/1 values."""
    return [bus.read_byte_data(PCF8574_ADDR, i) for i in range(SENSOR_PINS)]


def _on_interrupt():
    """Falling-edge callback: read sensors and report obstacles."""
    raw = _read_pcf8574_raw(_bus)
    for idx, val in enumerate(raw):
        if not val:
            print(f"Obstacle detected by sensor {idx}")


def main():
    global _bus, _sensor_button

    # --- I2C bus -------------------------------------------------------------
    try:
        _bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    # --- Proximity sensor (active-low) --------------------------------------
    try:
        _sensor_button = Button(PROXIMITY_PIN, pull_up=True, bounce_time=DEBOUNCE_MS / 1000.0)
        _sensor_button.when_pressed = _on_interrupt
    except Exception as exc:
        print(f"Error: cannot initialise GPIO{PROXIMITY_PIN}: {exc}", file=sys.stderr)
        _bus.close()
        sys.exit(1)

    # --- Register interrupt callback -----------------------------------------
    try:
        _sensor_button.when_pressed = _on_interrupt
    except Exception as exc:
        print(f"Warning: could not register interrupt: {exc}", file=sys.stderr)

    # --- Main loop -----------------------------------------------------------
    try:
        while _running:
            time.sleep(LOOP_DELAY_S)
    except KeyboardInterrupt:
        pass
    finally:
        # --- Clean resource release on every exit path -----------------------
        if _sensor_button is not None:
            try:
                _sensor_button.close()
            except Exception:
                pass
        if _bus is not None:
            try:
                _bus.close()
            except Exception:
                pass
        print("Resources cleaned up. Exiting.")


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

