import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys
import time

SERIAL_PORT = "/dev/ttyACM0"
SERIAL_BAUDRATE = 9600
ROI_SIZE = 100
HALF_EXTENT = 50
MIN_CONTOUR_AREA = 500

running = True
cap = None
ser = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global cap, ser
    if cap is not None and cap.isOpened():
        cap.release()
    if ser is not None and ser.is_open:
        ser.close()
    cv2.destroyAllWindows()


def find_color_range(roi):
    h_min = np.min(roi[:, :, 0])
    h_max = np.max(roi[:, :, 0])
    s_min = np.min(roi[:, :, 1])
    s_max = np.max(roi[:, :, 1])
    v_min = np.min(roi[:, :, 2])
    v_max = np.max(roi[:, :, 2])
    return (h_min, h_max, s_min, s_max, v_min, v_max)


def send_serial_command(command):
    if ser is None:
        return
    try:
        ser.write(command)
        ser.flush()
    except serial.SerialException as e:
        print(f"Serial write error: {e}")


def send_position_command(position):
    if ser is None:
        return
    try:
        send_serial_command(f"A{position}\n".encode())
    except serial.SerialException as e:
        print(f"Serial command error: {e}")


def main():
    global cap, ser

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open camera.")
        sys.exit(1)

    try:
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
    except Exception as e:
        print(f"Warning: Could not set frame size: {e}")

    try:
        ser = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
    except serial.SerialException as e:
        print(f"Warning: Could not open serial port {SERIAL_PORT}: {e}")
        print("Falling back to first available serial port.")
        available = [p.device for p in serial.tools.list_ports.comports()]
        if available:
            SERIAL_PORT = available[0]
            ser = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
        else:
            print("Warning: No serial ports found. Continuing in serial-disabled mode.")
            ser = None
    except Exception as e:
        print(f"Warning: Could not open serial port {SERIAL_PORT}: {e}")
        ser = None

    roi = np.zeros((ROI_SIZE, ROI_SIZE, 3), dtype=np.uint8)
    roi_h, roi_w = ROI_SIZE // 2, ROI_SIZE // 2
    color_range = None

    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break

            h_frame, w_frame, _ = frame.shape
            cx_frame = w_frame // 2
            cy_frame = h_frame // 2

            hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)

            if color_range is None:
                color_range = find_color_range(frame)

            if color_range is not None:
                mask = cv2.inRange(hsv_frame, color_range[0], color_range[1])
                contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

                for contour in contours:
                    if cv2.contourArea(contour) > MIN_CONTOUR_AREA:
                        x, y, bw, bh = cv2.boundingRect(contour)
                        cv2.rectangle(frame, (x, y), (x + bw, y + bh), (255, 0, 0), 2)

                        ball_x = x + bw // 2
                        ball_y = y + bh // 2

                        if ball_x > cx_frame + HALF_EXTENT and ball_y > cy_frame + HALF_EXTENT:
                            send_position_command("1")
                        elif ball_x > cx_frame + HALF_EXTENT and ball_y < cy_frame - HALF_EXTENT:
                            send_position_command("2")
                        elif ball_x < cx_frame - HALF_EXTENT and ball_y > cy_frame + HALF_EXTENT:
                            send_position_command("3")
                        elif ball_x < cx_frame - HALF_EXTENT and ball_y < cy_frame - HALF_EXTENT:
                            send_position_command("4")
                        else:
                            send_position_command("5")

            cv2.imshow("Frame", frame)
            if cv2.waitKey(1) & 0xFF == 27:
                break

            time.sleep(0.05)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

