import json
import logging
import signal
import sys
import time
from collections import deque
from statistics import median

try:
    from gpiozero import Device, DigitalOutputDevice, DigitalInputDevice
    from gpiozero.pins.native import NativeFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(0)

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensor_config": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_config": {
        "alert_threshold_low": 10.0,
        "alert_threshold_high": 180.0,
        "alert_repeat_delay": 60,
        "log_file": "water_level.log",
    },
}

running = True

def signal_handler(signum, frame):
    global running
    running = False

def load_config():
    try:
        with open(CONFIG_FILE, "r") as f:
            config = json.load(f)
        if not isinstance(config, dict):
            raise ValueError("Config must be a JSON object")
        return config
    except FileNotFoundError:
        logging.warning("config.json not found; creating default configuration.")
        return DEFAULT_CONFIG
    except (json.JSONDecodeError, ValueError) as e:
        logging.error(f"Invalid config.json ({e}); using default configuration.")
        return DEFAULT_CONFIG

def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

def setup_gpio(sensor_config):
    try:
        Device.pin_factory = NativeFactory()
        trigger_pins = [d.pin for d in sensor_config if d.get("trigger_pin") is not None]
        echo_pins = [d.pin for d in sensor_config if d.get("echo_pin") is not None]
        trigger_devices = [DigitalOutputDevice(pin, initial_value=False) for pin in trigger_pins]
        echo_devices = [DigitalInputDevice(pin, pull_up=False) for pin in echo_pins]
        for d in trigger_devices + echo_devices:
            d.close()
        logging.info("GPIO setup complete.")
        return trigger_devices, echo_devices
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        return None, None

def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    try:
        trigger_devices[0].off()
        time.sleep(0.00001)
        trigger_devices[0].on()
        time.sleep(0.00001)
        trigger_devices[0].off()

        start_time = time.time()
        timeout = time.time() + 0.05
        while echo_devices[0].value == 0:
            if time.time() > timeout:
                raise TimeoutError("Echo pin stuck LOW")
            start_time = time.time()

        timeout = time.time() + 0.05
        while echo_devices[0].value == 1:
            if time.time() > timeout:
                raise TimeoutError("Echo pin stuck HIGH")
            end_time = time.time()

        pulse_duration = end_time - start_time
        distance = (pulse_duration * 34300) / 2
        water_level = max_distance - distance
        water_level = max(0.0, water_level)
        water_level += offset
        return water_level
    except Exception as e:
        logging.error(f"Error measuring distance: {e}")
        return None

def check_alerts(water_levels, alert_threshold_low, alert_threshold_high, repeat_delay):
    alerts = []
    for i, water_level in enumerate(water_levels):
        if water_level is None:
            continue
        if water_level < alert_threshold_low:
            alerts.append(f"Sensor {i+1}: Water level too low ({water_level:.2f} cm)")
        elif water_level > alert_threshold_high:
            alerts.append(f"Sensor {i+1}: Water level too high ({water_level:.2f} cm)")
    if alerts:
        logging.warning("Alerts triggered:")
        for alert in alerts:
            logging.warning(alert)
        if alert_threshold_low < alert_threshold_high:
            time.sleep(repeat_delay)
            logging.info("Alert suppressed.")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config()
    setup_logging(config["alert_config"]["log_file"])

    sensor_config = config["sensor_config"]
    alert_config = config["alert_config"]

    trigger_devices, echo_devices = setup_gpio(sensor_config)
    if trigger_devices is None or echo_devices is None:
        logging.error("GPIO setup failed; exiting.")
        sys.exit(0)

    sensor_readings = deque(maxlen=3)
    sensor_count = len(sensor_config)

    try:
        while running:
            readings = []
            for i, sensor in enumerate(sensor_config):
                if trigger_devices[i].is_active:
                    distance = measure_distance(trigger_devices[i].pin, echo_devices[i].pin, sensor["offset"], sensor["max_distance"])
                    if distance is not None:
