                    else:
                        logging.warning(f"Sensor {i+1}: Measurement failed.")
                else:
                    logging.warning(f"Sensor {i+1}: Trigger pin not active.")

            if readings:
                sensor_readings.append(median(readings))
                logging.info(f"Sensor readings: {readings}")
            else:
                logging.warning("No valid sensor readings.")

            check_alerts(list(sensor_readings), alert_config["alert_threshold_low"], alert_config["alert_threshold_high"], alert_config["alert_repeat_delay"])

            for _ in range(5):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        for d in trigger_devices + echo_devices:
