import time
import datetime
import signal
import sys
import speech_recognition as sr
import board
import adafruit_dht
from picamera2 import Picamera2

# Configuration
GPIO_PIN_LIGHTS = 17
GPIO_PIN_DHT11 = 4
CAMERA_RESOLUTION = (640, 480)

# Global state
lights_state = False
camera_available = False
picam2 = None

# Initialize GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(GPIO_PIN_LIGHTS, GPIO.OUT, initial=GPIO.LOW)
except Exception as e:
    print(f"GPIO initialization failed: {e}. Using simulated GPIO.")
    GPIO_PIN_LIGHTS = 0
    GPIO.cleanup()

# Initialize DHT11 sensor
dht_device = None
try:
    dht_device = adafruit_dht.DHT11(board.D4)
except Exception as e:
    print(f"DHT11 sensor initialization failed: {e}. Using simulated temperature.")
    dht_device = None

# Initialize camera
try:
    picam2 = Picamera2()
    picam2.configure(picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": CAMERA_RESOLUTION}))
    picam2.start()
    camera_available = True
except Exception as e:
    print(f"Camera initialization failed: {e}. Camera functionality disabled.")
    camera_available = False

def turn_lights_on():
    global lights_state
    if GPIO_PIN_LIGHTS > 0:
        GPIO.output(GPIO_PIN_LIGHTS, GPIO.HIGH)
        lights_state = True
        print("Lights turned ON")
    else:
        print("Simulating lights on")

def turn_lights_off():
    global lights_state
    if GPIO_PIN_LIGHTS > 0:
        GPIO.output(GPIO_PIN_LIGHTS, GPIO.LOW)
        lights_state = False
        print("Lights turned OFF")
    else:
        print("Simulating lights off")

def read_temperature():
    if dht_device is not None:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                print("DHT11 returned None temperature")
                return 20.0
        except RuntimeError as e:
            print(f"DHT11 read error: {e}")
            return 20.0
        except Exception as e:
            print(f"DHT11 unexpected error: {e}")
            return 20.0
    else:
        return 20.0

def capture_image():
    global picam2
    if picam2 is None:
        print("Camera not available. Skipping image capture.")
        return
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        picam2.capture_file(filename)
        print(f"Image captured: {filename}")
    except Exception as e:
        print(f"Camera capture error: {e}")

def listen_for_commands():
    recognizer = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            print("Say 'Greenhouse' followed by a command (turn on/off lights, temperature, picture).")
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            print("Listening...")
            audio = recognizer.listen(source, timeout=5, phrase_time_limit=5)
    except sr.WaitTimeoutError:
        print("No speech detected within timeout.")
        return
    except Exception as e:
        print(f"Microphone error: {e}")
        return

    try:
        command = recognizer.recognize_google(audio).lower()
        print(f"Recognized command: {command}")
        words = command.split()
        if "greenhouse" in words:
            if "turn on the lights" in words:
                turn_lights_on()
            elif "turn off the lights" in words:
                turn_lights_off()
            elif "what is the temperature" in words:
                temperature = read_temperature()
                print(f"Temperature: {temperature:.1f} C")
            elif "take a picture" in words:
                capture_image()
        else:
            print("Unknown command.")
    except sr.UnknownValueError:
        print("Could not understand audio")
    except sr.RequestError as e:
        print(f"Could not request results from Google Speech Recognition service: {e}")

def cleanup(signum=None, frame=None):
    global camera_available
    print("\nCleaning up...")
    if camera_available:
        try:
            picam2.stop()
        except Exception:
            pass
    GPIO.cleanup()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        while True:
            listen_for_commands()
    except KeyboardInterrupt:
        cleanup()

