import logging
import signal
import sys
import time

import cv2
import numpy as np
from gpiozero import OutputDevice
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

GPIO_PIN = 17
ROI_START_ROW = 10
ROI_END_ROW = 150
ROI_START_COL = 40
ROI_END_COL = 280
RESOLUTION_WIDTH = 320
RESOLUTION_HEIGHT = 240
FRAMERATE = 10

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": (RESOLUTION_WIDTH, RESOLUTION_HEIGHT), "format": "BGR888"},
            controls={"FrameRate": FRAMERATE}
        )
        picam2.configure(config)
        picam2.start()
        logging.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None

def initialize_gpio(pin):
    try:
        gpio = OutputDevice(pin, active_high=True, initial_value=True)
        logging.info(f"GPIO pin {pin} initialized as output (HIGH).")
        return gpio
    except Exception as e:
        logging.error(f"Error initializing GPIO pin {pin}: {e}")
        return None

def extract_roi(frame):
    if frame is None or frame.size == 0:
        return None
    return frame[ROI_START_ROW:ROI_END_ROW, ROI_START_COL:ROI_END_COL]

def display_image(window_name, image):
    if image is None:
        return
    cv2.imshow(window_name, image)

def cleanup(picam2, gpio, window_name=""):
    logging.info("Cleaning up resources...")
    if picam2 is not None:
        try:
            picam2.stop()
            logging.info("Camera stopped.")
        except Exception as e:
            logging.error(f"Error stopping camera: {e}")
    cv2.destroyAllWindows()
    if window_name:
        try:
            cv2.destroyWindow(window_name)
            logging.info(f"Window '{window_name}' closed.")
        except Exception as e:
            logging.error(f"Error closing window '{window_name}': {e}")
    if gpio is not None:
        try:
            gpio.off()
            gpio.close()
            logging.info("GPIO pin released.")
        except Exception as e:
            logging.error(f"Error releasing GPIO pin: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    gpio = initialize_gpio(GPIO_PIN)
    if gpio is None:
        return

    picam2 = initialize_camera()
    if picam2 is None:
        cleanup(picam2, gpio)
        return

    try:
        while _running:
            frame = picam2.capture_array()
            if frame is None or frame.size == 0:
                logging.warning("Empty frame captured, skipping.")
                continue

            roi = extract_roi(frame)
            if roi is not None:
                display_image("Output Image", roi)

            key = cv2.waitKey(1) & 0xFF
            if key == 10:  # Enter key
                logging.info("Exiting program.")
                break
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup(picam2, gpio)

if __name__ == "__main__":
    main()

