import cv2
import pyzbar.pyzbar as pyzbar
import time
import datetime
import logging
import configparser
import os
import threading
import queue
import sys
import signal

# Configuration file path
CONFIG_FILE = 'config.ini'

# Default configuration values
DEFAULT_CONFIG = {
    'DEFAULT': {
        'camera_index_1': '0',
        'camera_index_2': '2',
        'motion_threshold': '25',
        'frame_buffer_size': '10',
        'redundancy_time_window': '30',
        'cloud_upload_interval': '60',
        'reinit_delay': '30',
        'log_file': 'inventory.log'
    },
    'CAMERA_1': {
        'log_file': 'backup_inventory.log'
    },
    'CAMERA_2': {
        'log_file': 'backup_inventory.log'
    }
}

# Global variables
config = DEFAULT_CONFIG.copy()
inventory_queue = queue.Queue()
inventory_lock = threading.Lock()
camera_lock = threading.Lock()
running = True
camera_threads = []
last_scan_time = {0: 0.0, 2: 0.0}
last_motion_time = {0: 0.0, 2: 0.0}
last_upload_time = 0.0

# --- Configuration Management ---
def load_config():
    global config
    config = DEFAULT_CONFIG.copy()
    try:
        with open(CONFIG_FILE, 'r') as configfile:
            read_config = configparser.ConfigParser()
            read_config.read_file(configfile)
            for section, keys in read_config.items():
                for key, value in keys.items():
                    config[section][key] = value
    except FileNotFoundError:
        logging.warning(f"Configuration file not found: {CONFIG_FILE}. Using default values.")
    except Exception as e:
        logging.error(f"Error loading configuration: {e}. Using default values.")

# --- Camera Initialization ---
def initialize_camera(camera_index):
    try:
        camera = cv2.VideoCapture(camera_index)
        if not camera.isOpened():
            logging.error(f"Could not open camera at index {camera_index}.")
            return None
        return camera
    except Exception as e:
        logging.error(f"Error initializing camera at index {camera_index}: {e}")
        return None

# --- Motion Detection ---
def detect_motion(frame1, frame2, threshold):
    diff = cv2.absdiff(frame1, frame2)
    gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
    blur = cv2.GaussianBlur(gray, (5, 5), 0)
    _, thresh = cv2.threshold(blur, threshold, 255, cv2.THRESH_BINARY)
    contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    return len(contours) > 0

# --- QR Code Decoding ---
def decode_qr_code(frame):
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = pyzbar.decode(gray)
        for obj in decoded_objects:
            return obj.data.decode('utf-8')
    except Exception as e:
        logging.error(f"Error decoding QR code: {e}")
        return None

# --- Inventory Management ---
def manage_inventory(data, camera_id):
    global last_scan_time, last_motion_time, last_upload_time
    current_time = time.time()
    if data in inventory_queue.queue:
        last_scan_time[camera_id] = current_time
        return
    if current_time - last_scan_time[camera_id] < config['DEFAULT']['redundancy_time_window']:
        return
    inventory_queue.put((data, camera_id))
    last_scan_time[camera_id] = current_time
    last_motion_time[camera_id] = current_time

def upload_inventory(log_file):
    global last_upload_time
    try:
        with open(log_file, 'r') as f:
            inventory_data = f.read()
        last_upload_time = time.time()
        print(inventory_data)
        with open(log_file, 'w') as f:
            f.truncate(0)
    except Exception as e:
        logging.error(f"Error uploading inventory: {e}")

# --- Watchdog ---
def watchdog():
    global running
    while running:
        time.sleep(1)
        if not inventory_queue.empty():
            last_scan_time = {0: 0.0, 2: 0.0}
            last_motion_time = {0: 0.0, 2: 0.0}
        else:
            logging.warning("Watchdog: No QR code detected for 30 seconds. Restarting program.")
            os.execv(sys.executable, [sys.executable] + sys.argv)

# --- Camera Thread ---
def camera_thread(camera_index, camera_id):
    global running
    while running:
        try:
            if camera_id == 0:
                camera = initialize_camera(camera_index)
            elif camera_id == 2:
                camera = initialize_camera(camera_index)
            else:
                logging.error(f"Invalid camera ID: {camera_id}")
                continue

            if camera is None:
                logging.error(f"Failed to initialize camera at index {camera_index}.")
                continue

            ret, frame = camera.read()
            if not ret:
                logging.error(f"Failed to grab frame from camera at index {camera_index}.")
                continue

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            frame_buffer = gray.copy()

            if detect_motion(frame_buffer, gray, config['DEFAULT']['motion_threshold']):
                data = decode_qr_code(frame_buffer)
                if data:
                    manage_inventory(data, camera_id)
                    logging.info(f"QR code detected: {data} from camera {camera_id}")
                else:
                    logging.debug(f"No QR code detected from camera {camera_id}.")
            else:
                logging.debug(f"No motion detected from camera {camera_id}.")

            time.sleep(config['DEFAULT']['cloud_upload_interval'])

        except Exception as e:
            logging.error(f"Error in camera thread: {e}")
            time.sleep(config['DEFAULT']['reinit_delay'])

# --- Main ---
def main():
    global running, camera_threads
    load_config()

    log_file = config['DEFAULT']['log_file']
    try:
        with open(log_file, 'a') as f:
            f.truncate(0)
    except Exception as e:
        logging.error(f"Error opening log file: {e}")

    signal.signal(signal.SIGINT, lambda s, f: (running = False, 0))
    signal.signal(signal.SIGTERM, lambda s, f: (running = False, 0))

    watchdog_thread = threading.Thread(target=watchdog)
    watchdog_thread.daemon = True
    watchdog_thread.start()

    try:
        for i in range(3):
            t = threading.Thread(target=camera_thread, args=(i, i))
            t.daemon = True
            t.start()
            camera_threads.append(t)
    except Exception as e:
        logging.error(f"Error starting camera threads: {e}")

    while running:
        time.sleep(1)

    for t in camera_threads:
        t.join(timeout=2)

    logging.info("Program finished.")

if __name__ == "__main__":
    main()

