import time
import datetime
import os
import signal
import sys
import configparser
from picamera2 import Picamera2
from gpiozero import CPUTemperature

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False
    print("\nShutdown signal received. Exiting gracefully...")

def load_config(config_file):
    config = configparser.ConfigParser()
    if not os.path.exists(config_file):
        print(f"Error: Configuration file '{config_file}' not found.")
        sys.exit(1)
    try:
        config.read(config_file)
        return config
    except configparser.Error as e:
        print(f"Error reading configuration file: {e}")
        sys.exit(1)

def init_camera(config):
    try:
        camera = Picamera2()
        config_camera = camera.create_preview_configuration(
            main={"format": "RGB888", "size": (640, 480)}
        )
        camera.configure(config_camera)
        camera.start()
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def detect_motion(camera, config, last_frame, roi_x1, roi_y1, roi_x2, roi_y2, motion_threshold):
    try:
        frame = camera.capture_array()
        if frame is None:
            print("Error: Captured frame is None.")
            return False, last_frame

        # Convert to grayscale for comparison
        gray_frame = frame[:, :, 0]
        gray_last_frame = last_frame[:, :, 0]

        # Calculate pixel difference
        diff = abs(gray_frame.astype(int) - gray_last_frame.astype(int))
        motion_percentage = (diff > 20).sum() / diff.size * 100

        if motion_percentage > motion_threshold:
            return True, frame
        return False, frame
    except Exception as e:
        print(f"Error in motion detection: {e}")
        return False, last_frame

def save_snapshot(camera, config, frame, timestamp):
    try:
        filename = os.path.join(config.get("Snapshot", "directory"), f"motion_{timestamp}.jpg")
        camera.capture_file(filename)
        print(f"Snapshot saved: {filename}")
    except Exception as e:
        print(f"Error saving snapshot: {e}")

def get_temperature(config):
    if config.getboolean("Temperature", "simulated"):
        try:
            temp = CPUTemperature().temperature
            return temp
        except Exception as e:
            print(f"Error reading temperature: {e}")
            return None
    else:
        try:
            temp = CPUTemperature().temperature
            return temp
        except Exception as e:
            print(f"Error reading temperature: {e}")
            return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)

    config = load_config("config.txt")

    camera = init_camera(config)
    if camera is None:
        sys.exit(1)

    last_frame = None
    motion_detected = False
    last_motion_time = None

    try:
        while running:
            current_time = datetime.datetime.now()
            timestamp = current_time.strftime("%Y%m%d_%H%M%S")

            # Capture first frame
            if last_frame is None:
                success, frame = camera.capture_array()
                if not success:
                    print("Error: Failed to capture initial frame.")
                    time.sleep(1)
                    continue
                last_frame = frame
                continue

            # Detect motion
            motion_detected, last_frame = detect_motion(camera, config, last_frame,
                                                    config.getint("ROI", "x1"),
                                                    config.getint("ROI", "y1"),
                                                    config.getint("ROI", "x2"),
                                                    config.getint("ROI", "y2"),
                                                    config.getint("Motion", "threshold"))

            if motion_detected:
                if last_motion_time is None:
                    last_motion_time = current_time
                    print("Motion detected!")
                else:
                    time_diff = current_time - last_motion_time
                    if time_diff.total_seconds() > config.getint("Motion", "confirmation_delay"):
                        print("Motion confirmed!")
                        last_motion_time = current_time

            # Save snapshot if motion detected
            if motion_detected:
                save_snapshot(camera, config, last_frame, timestamp)

            # Get and print temperature
            temp = get_temperature(config)
            if temp is not None:
                print(f"Temperature: {temp}°C")

            time.sleep(1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if camera:
            camera.stop()
            camera.close()
        print("Program terminated.")

if __name__ == "__main__":
    main()

