import serial
import sys
import signal

BLUETOOTH_PORT = "/dev/rfcomm4"
BAUD_RATE = 38400

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def open_bluetooth_serial(port: str, baudrate: int) -> serial.Serial:
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False,
            timeout=1.0,
        )
        if not ser.is_open:
            raise serial.SerialException(f"Port {port} did not open")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        sys.exit(1)


def transmit_data(serial_port: serial.Serial, data: str) -> int:
    try:
        payload = f"X{data}".encode("utf-8")
        bytes_written = serial_port.write(payload)
        serial_port.flush()
        print(f"Transmitted: {data} ({bytes_written} bytes)")
        return bytes_written
    except serial.SerialException as e:
        print(f"Error transmitting data: {e}", file=sys.stderr)
        return 0


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = None
    try:
        serial_connection = open_bluetooth_serial(BLUETOOTH_PORT, BAUD_RATE)
        print(f"Connected to {BLUETOOTH_PORT} at {BAUD_RATE} baud. Type 'q' to quit.")

        while _running:
            try:
                user_input = input("Enter data to send (or 'q' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.lower() == "q":
                break

            if not _running:
                break

            if user_input:
                bytes_written = transmit_data(serial_connection, user_input)
                if not _running:
                    break

    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

