import io
import signal
import logging
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """WebSocket handler for broadcasting JPEG frames from a picamera2 stream."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self.frame_buffer: list[bytes] = []
        self.frame_lock = threading.Lock()
        self.connected_clients: int = 0
        self.broadcast_lock = threading.Lock()
        self.broadcast_event = threading.Event()
        self._closed = False

    def has_connections(self) -> bool:
        with self.broadcast_lock:
            return self.connected_clients > 0

    def broadcast(self, data: bytes) -> None:
        if self._closed:
            return
        with self.broadcast_lock:
            if not self.has_connections():
                return
            self.connected_clients += 1

    def _broadcast_threadsafe(self, data: bytes) -> None:
        if self._closed:
            return
        with self.broadcast_lock:
            if not self.has_connections():
                return
            self.connected_clients += 1
            self.broadcast_event.set()
            try:
                self.broadcast(data)
            finally:
                with self.broadcast_lock:
                    self.connected_client_count -= 1

    def _receive_threadsafe(self, data: bytes) -> None:
        if self._closed:
            return
        with self.broadcast_lock:
            if not self.has_connections():
                return
            self.connected_clients += 1
            self.broadcast_event.set()
            try:
                self.broadcast(data)
            finally:
                with self.broadcast_lock:
                    self.connected_clients -= 1

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        self.broadcast_event.set()
        self.broadcast_event.wait()
        logger.info("WebSocketHandler closed.")


class CameraStream:
    """Streams video from picamera2 to WebSocket clients with motion detection."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self.picam2: Optional[Picamera2] = None
        self.encoder: Optional[MJPEGEncoder] = None
        self.output: Optional[FileOutput] = None
        self.frame_buffer: list[bytes] = []
        self.frame_lock = threading.Lock()
        self.broadcast_event = threading.Event()
        self._closed = False

    def start(self) -> None:
        if self._closed:
            return
        try:
            self.picam2 = Picamera2()
            config = self.picam2.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                lores={"size": (640, 480), "format": "YUV420"},
            )
            self.picam2.configure(config)
            self.picam2.start()
            self.encoder = MJPEGEncoder()
            self.output = FileOutput("stream.mjpg")
            self.picam2.start_recording(self.encoder, self.output)
            logger.info("Camera recording started.")
        except Exception as exc:
            logger.error("Failed to start camera: %s", exc)
            self.stop()
            raise

    def stop(self) -> None:
        if self._closed:
            return
        self._closed = True
        if self.picam2 is not None:
            try:
                self.picam2.stop_recording()
            except Exception as exc:
                logger.warning("Error stopping recording: %s", exc)
            try:
                self.picam2.stop()
            except Exception as exc:
                logger.warning("Error stopping camera: %s", exc)
        logger.info("Camera recording stopped.")

    def _broadcast_threadsafe(self, data: bytes) -> None:
        if self._closed:
            return
        with self.broadcast_event:
            self.broadcast_event.set()
            try:
                self.broadcast(data)
            finally:
                self.broadcast_event.clear()

    def _receive_threadsafe(self, data: bytes) -> None:
        if self._closed:
            return
        with self.broadcast_event:
            self.broadcast_event.set()
            try:
                self.broadcast(data)
            finally:
                self.broadcast_event.clear()

    def _process_frame(self, frame: np.ndarray) -> None:
        if frame is None or frame.size == 0:
            return
        with self.frame_lock:
            self.frame_buffer.append(frame.tobytes())
        if len(self.frame_buffer) > 1:
            prev = self.frame_buffer[-2]
            curr = self.frame_buffer[-1]
            if prev is not None and curr is not None:
                try:
                    self.detect_motion_function(prev, curr)
                except Exception as exc:
                    logger.error("Error in motion detection: %s", exc)

    def _read_frame(self) -> Optional[bytes]:
        if self.picam2 is None:
            return None
        try:
            frame = self.picam2.capture_array("lores")
            if frame is None:
                return None
            return frame.tobytes()
        except Exception as exc:
            logger.error("Error reading frame: %s", exc)
            return None

    def run(self) -> None:
        if self._closed:
            return
        try:
            self.picam2.start()
            logger.info("Camera recording started.")
            while not self._closed:
                frame = self._read_frame()
                if frame is not None:
                    with self.frame_lock:
                        self.frame_buffer.append(frame)
                    if len(self.frame_buffer) > 1:
                        prev = self.frame_buffer[-2]
                        curr = self.frame_buffer[-1]
                        if prev is not None and curr is not None:
                            try:
                                self.detect_motion_function(prev, curr)
                            except Exception as exc:
                                logger.error("Error in motion detection: %s", exc)
                time.sleep(0.033)
        except Exception as exc:
            logger.error("Camera error: %s", exc)
        finally:
            self.stop()


def main() -> None:
    def detect_motion(prev: np.ndarray, curr: np.ndarray) -> None:
        if prev is None or curr is None:
            return
        diff = cv2.absdiff(prev, curr)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
        contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        for c in contours:
            if cv2.contourArea(c) < 500:
                return
        logger.info("No significant motion detected.")

    handler = WebSocketHandler(detect_motion_function=detect_motion)
    stream = CameraStream(detect_motion_function=detect_motion)
    stream.start()
    stream.output.stream.set_callback(handler._receive_threadsafe)
    stream.output.stream.set_broadcast_handler(handler._broadcast_threadsafe)
    stream.output.stream.start()
    logger.info("WebSocket server started. Waiting for connections...")
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logger.info("Exiting...")
    finally:
        stream.stop()
        handler.close()


if __name__ == "__main__":
    main()

