        if self._closed:
            return
        with self.broadcast_lock:
            if not self.has_connections():
                return
            self.connected_clients += 1
            self.broadcast_event.set()
            try:
                self.broadcast(data)
            finally:
                with self.broadcast_lock:
                    self.connected_clients -= 1

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        self.broadcast_event.set()
        self.broadcast_event.wait()
