    """Streams video from picamera2 to WebSocket clients with motion detection."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self.picam2: Optional[Picamera2] = None
        self.encoder: Optional[MJPEGEncoder] = None
        self.output: Optional[FileOutput] = None
        self.frame_buffer: list[bytes] = []
        self.frame_lock = threading.Lock()
        self.broadcast_event = threading.Event()
        self._closed = False

    def start(self) -> None:
        if self._closed:
            return
        try:
            self.picam2 = Picamera2()
