logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """
    Receives JPEG frames from picamera2 and broadcasts them over a WebSocket.
    """

    def __init__(self, websocket_handler: "WebSocketHandler"):
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be a WebSocketHandler")
        self.websocket_handler = websocket_handler
        self.frame_buffer: Optional[io.BytesIO] = None
        self.lock = threading.Lock()
        self.previous_frame: Optional[np.ndarray] = None
        self.current_frame: Optional[np.ndarray] = None
        self._closed = False

    def write(self, data: bytes) -> int:
        """
        Called by picamera2's capture_buffer or a custom output.
        Accumulates bytes until a complete JPEG is detected, then finalizes
        the previous frame and broadcasts it.
        """
        if self._closed:
            return 0

        try:
            if data.startswith(b'\xff\xd8'):
                with self.lock:
                    if self.frame_buffer is not None:
                        self.previous_frame = self.current_frame
                        self.current_frame = self.frame_buffer.getvalue()
                        self.frame_buffer.seek(0)
                        self.frame_buffer.truncate(0)
                        self._broadcast_frame()
            self.frame_buffer.write(data)
            return len(data)
        except Exception as e:
            logger.error(f"Error processing camera data: {e}", exc_info=True)
            return 0

    def _broadcast_frame(self):
        """Broadcasts the current frame to connected WebSocket clients."""
        if not self.websocket_handler.has_connections():
            return
        try:
            self.websocket_handler.broadcast(self.current_frame)
        except Exception as e:
            logger.error(f"Error broadcasting frame: {e}", exc_info=True)

    def flush(self):
        """Finalizes any remaining frame and broadcasts it."""
        if self._closed:
            return
        with self.lock:
            if self.frame_buffer is not None:
                self.previous_frame = self.current_frame
                self.current_frame = self.frame_buffer.getvalue()
                self.frame_buffer.seek(0)
                self.frame_buffer.truncate(0)
                self._broadcast_frame()
        self.frame_buffer = None
        self.previous_frame = None
        self.current_frame = None

    def close(self):
        """Closes the buffer and stops the camera if necessary."""
        if self._closed:
            return
        self._closed = True
        if self.frame_buffer is not None:
            try:
                self.frame_buffer.close()
            except Exception as e:
                logger.error(f"Error closing frame buffer: {e}", exc_info=True)
            self.frame_buffer = None


class MotionDetectionBuffer:
