import cv2
import numpy as np
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """
    Accumulates MJPEG frames from a picamera2 stream and flushes complete
    H.264 frames (non-I-frame) to an output sink.
    """

    def __init__(self, c: Picamera2):
        self.c = c
        self.buf = io.BytesIO()
        self.prev_frame: Optional[np.ndarray] = None
        self.is_first_frame = True

    def write(self, d: bytes) -> int:
        """
        Accumulates bytes d into the buffer. When a complete H.264 frame
        (non-I-frame) is detected, flush and reset the buffer.
        """
        try:
            self.buf.write(d)
        except OSError as exc:
            logger.error("I/O error writing to stream buffer: %s", exc)
            return 0

        if not d:
            return 0

        # picamera2 MJPEG stream: each frame starts with the SOI marker
        # \xff\xd8.
        if d.startswith(b"\xff\xd8"):
            if self.is_first_frame:
                self.is_first_frame = False
                logger.debug("First frame of MJPEG stream received.")
            else:
                self.prev_frame = self.buf.getvalue()
                self.buf.seek(0)
                self.buf.truncate()
                if self.prev_frame is not None:
                    try:
                        decoded = cv2.imdecode(np.frombuffer(self.prev_frame, dtype=np.uint8), cv2.IMREAD_COLOR)
                        if decoded is not None:
                            f = self.c.current_configuration()["encode"]
                            if f.bitrate > 0 and decoded.size > 0:
                                logger.debug("Processing frame: %d bytes, %d x %d", decoded.shape[1], decoded.shape[0], f.bitrate)
                            else:
                                logger.debug("Frame %d bytes, %d x %d (skipped due to zero size).", decoded.shape[1], decoded.shape[0], f.bitrate)
                    except Exception as exc:
                        logger.error("Error decoding frame: %s", exc)
                else:
                    logger.debug("Frame %d bytes, %d x %d (no previous frame available).", decoded.shape[1], decoded.shape[0], f.bitrate)
            return 0

        return self.buf.tell()


class MotionDetectionBuffer:
    """
    Accumulates MJPEG frames and decodes JPEG frames when a new SOI marker
    is encountered.  The callback f receives the previous and current decoded
    frames (skipping the very first frame).
    """

    def __init__(self, c: Picamera2, f: Callable[[np.ndarray, np.ndarray], None]):
        self.c = c
        self.prev_frame: Optional[np.ndarray] = None
        self.f = f
        self.buf = io.BytesIO()
        self.is_first_frame = True

    def write(self, d: bytes) -> int:
        """
        Accumulates bytes d into the buffer. When a new JPEG frame (SOI)
        is detected, decode the previous frame, invoke f, and start
        accumulating the new frame.
        """
        try:
            self.buf.write(d)
        except OSError as exc:
            logger.error("I/O error writing to stream buffer: %s", exc)
            return 0

        if not d:
            return 0

        if d.startswith(b"\xff\xd8"):
            if self.is_first_frame:
                self.is_first_frame = False
                logger.debug("First frame of MJPEG stream received.")
            else:
                try:
                    self.prev_frame = np.frombuffer(self.buf.getvalue(), dtype=np.uint8)
                    if self.prev_frame is not None:
                        self.prev_frame = cv2.imdecode(self.prev_frame, cv2.IMREAD_COLOR)
                        if self.prev_frame is not None:
                            self.f(self.prev_frame, self.prev_frame)
                        self.prev_frame = None
                        self.buf.seek(0)
                        self.buf.truncate()
                except Exception as exc:
                    logger.error("Error decoding frame: %s", exc)
                return 0

        return self.buf.tell()


def _signal_handler(signum, frame):
    logger.info("Signal %d received, shutting down.", signum)
    sys.exit(0)


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

