import spidev
import time

# SPI configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED = 1000000  # 1 MHz

# MAX7219 register addresses
MAX7219_REG_INTENSITY = 0x0A
MAX7219_REG_SHUTDOWN = 0x0C
MAX7219_REG_SCAN_LIMIT = 0x0B
MAX7219_REG_DIGIT0 = 0x01

# Character map: each entry is an 8-byte list representing one row of the 8x8 matrix
char_map = {
    'H': [0x7F, 0x09, 0x09, 0x09, 0x7F, 0x01, 0x01, 0x7F]
}

def init_spi():
    """Initialize SPI bus and return a spidev.SpiDev object."""
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED
        spi.mode = 0  # SPI mode 0 (CPOL=0, CPHA=0)
        spi.bits_per_word = 8
        return spi
    except (IOError, OSError) as e:
        print(f"Error initializing SPI: {e}")
        return None

def set_intensity(spi, intensity):
    """Set the intensity register (0x0A) to the given value (0-255)."""
    try:
        spi.xfer2([MAX7219_REG_INTENSITY, intensity & 0xFF])
    except (IOError, OSError) as e:
        print(f"Error setting intensity: {e}")

def set_scan_limit(spi, limit):
    """Set the scan-limit register (0x0B) to the given value (0-7)."""
    try:
        spi.xfer2([MAX7219_REG_SCAN_LIMIT, limit & 0xFF])
    except (IOError, OSError) as e:
        print(f"Error setting scan limit: {e}")

def set_shutdown(spi, state):
    """Set the shutdown register (0x0C) to enable/disable the display."""
    try:
        spi.xfer2([MAX7219_REG_SHUTDOWN, state & 0xFF])
    except (IOError, OSError) as e:
        print(f"Error setting shutdown: {e}")

def display_char(spi, char):
    """Display a single character from char_map on the MAX7219."""
    if char not in char_map:
        print(f"Character '{char}' not found in char_map")
        return

    # Set intensity to medium (8) and enable all digits (scan limit 7)
    set_intensity(spi, 8)
    set_scan_limit(spi, 7)

    # Send each row of the character to the digit registers
    for row_index, row_bytes in enumerate(char_map[char]):
        digit_register = MAX7219_REG_DIGIT0 + row_index
        try:
            spi.xfer2([digit_register, row_bytes[0], row_bytes[1], row_bytes[2],
                       row_bytes[3], row_bytes[4], row_bytes[5], row_bytes[6]])
        except (IOError, OSError) as e:
            print(f"Error writing digit {row_index}: {e}")
            return

def main():
    spi = init_spi()
    if spi is None:
        return

    try:
        # Display the character 'H'
        display_char(spi, 'H')
        print("Displaying 'H' for 5 seconds...")
        time.sleep(5)
    except (IOError, OSError) as e:
        print(f"SPI communication error: {e}")
    finally:
        spi.close()
        print("SPI connection closed.")

if __name__ == "__main__":
    main()

