import os
import time
import signal
import logging
from typing import List, Optional

from PIL import Image, ImageOps, UnidentifiedImageError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Frame:
    """Represents a single frame of an animated GIF."""

    def __init__(self, image: Image.Image, duration: int, loop: int = 0):
        self.image = image
        self.duration = duration
        self.loop = loop

    def __repr__(self) -> str:
        return f"Frame(duration={self.duration}, loop={self.loop})"


class AnimatedGif:
    """
    Loads and displays animated GIFs on a luma.core-based display.

    Attributes:
        display: The luma.core display object (e.g. SSD1306 OLED).
        folder: The folder containing the GIF files.
        frames: A list of Frame objects.
        current_frame_index: The index of the currently displayed frame.
        is_running: Whether the animation loop should continue.
    """

    def __init__(self, display, folder: Optional[str] = None, width: Optional[int] = None, height: Optional[int] = None):
        self.display = display
        self.folder = folder if folder is not None else '.'
        self.frames: List[Frame] = []
        self.current_frame_index = 0
        self.is_running = True

        if width is not None and height is not None:
            self.display.width = width
            self.display.height = height

        self._load_files()

    def _load_files(self) -> None:
        """Loads all .gif files from the specified folder."""
        if not os.path.isdir(self.folder):
            raise FileNotFoundError(f"Folder '{self.folder}' does not exist or is not a directory.")

        gif_files = [
            f for f in os.listdir(self.folder)
            if f.lower().endswith('.gif')
        ]

        if not gif_files:
            raise FileNotFoundError(f"No .gif files found in '{self.folder}'.")

        for filename in gif_files:
            filepath = os.path.join(self.folder, filename)
            try:
                with Image.open(filepath) as image:
                    if image.is_animated:
                        self._preload(filepath)
                    else:
                        logger.warning(f"Skipping non-animated file: {filepath}")
            except (UnidentifiedImageError, OSError) as e:
                logger.warning(f"Skipping invalid file: {filepath} ({e}).")
            except Exception as e:
                logger.error(f"Unexpected error processing {filepath}: {e}", exc_info=True)

    def _preload(self, filepath: str) -> None:
        """Preloads a single GIF file, converting each frame to a display-ready RGB image."""
        try:
            with Image.open(filepath) as image:
                self.frames.clear()

                for frame_index in range(image.n_frames):
                    image.seek(frame_index)
                    duration_ms = image.info.get('duration')
                    loop_count = image.info.get('loop')

                    if duration_ms is None or loop_count == 0:
                        logger.warning(f"Frame {frame_index}: no duration or loop set.")
                        continue

                    frame_image = image.convert('RGB')
                    padded_image = ImageOps.pad(
                        frame_image,
                        (self.display.width, self.display.height),
                        method=Image.NEAREST,
                        color=(0, 0, 0),
                        centering=(0.5, 0.5),
                    )
                    self.frames.append(Frame(padded_image, duration_ms, loop_count))

            logger.info(f"Loaded {len(self.frames)} frames from {filepath}")

        except (UnidentifiedImageError, OSError) as e:
            logger.error(f"Error preloading {filepath}: {e}", exc_info=True)
        except Exception as e:
            logger.error(f"Unexpected error preloading {filepath}: {e}", exc_info=True)

    def preload(self) -> None:
        """Preloads all frames if they haven't been loaded yet."""
        if not self.frames:
            logger.warning("No frames loaded. Preloading all GIFs.")
            for filepath in self.frames:
                self._preload(filepath)

    def play(self) -> bool:
        """Plays the current frame of the GIF."""
        if not self.frames:
            logger.warning("No frames loaded. Nothing to play.")
            return False

        if not self.is_running:
            logger.info("Animation stopped; skipping play().")
            return False

        try:
            self.preload()

            for frame in self.frames:
                if not self.is_running:
                    break

                elapsed = time.monotonic() - frame.image.info.get('creation_time', time.time())
                sleep_time = max(0, frame.duration - (time.monotonic() - elapsed))

                if sleep_time <= 0:
                    logger.warning(f"Frame {frame.image.name}: duration {frame.duration}ms but only {int(sleep_time)}ms elapsed.")
                    continue

                self.display.display(frame.image)
                time.sleep(sleep_time)

                if frame.loop > 0:
                    self.current_frame_index = (self.current_frame_index + 1) % len(self.frames)

        except Exception as e:
            logger.error(f"Error playing GIF: {e}", exc_info=True)
            return False

        return self.is_running

    def run(self) -> None:
        """Continuously runs the animation loop."""
        while self.is_running:
            if not self.play():
                self.is_running = False
                break

    def advance(self) -> None:
        """Advances to the next file in the folder."""
        self.current_frame_index = (self.current_frame_index + 1) % len(self.frames)

    def stop(self) -> None:
        """Stops the animation loop."""
        self.is_running = False

    def close(self) -> None:
        """Closes the display file handle."""
        try:
            self.display.close()
        except Exception as e:
            logger.error(f"Error closing display: {e}", exc_info=True)


def _signal_handler(signum, frame, gif: AnimatedGif) -> None:
    """Handle SIGINT/SIGTERM by stopping the animation and exiting."""
    logger.info(f"Received signal {signum}; stopping animation.")
    gif.stop()
    gif.close()
    raise SystemExit(0)


def main() -> None:
    """Demonstrate the AnimatedGif class."""
    import displayio
    from luma.core.render import canvas

    # SSD1306 OLED display (64x48) on a Raspberry Pi
    display = canvas(displayio.Oled(0, 0))

    gif = AnimatedGif(display, folder='.', width=display.width, height=display.height)

    signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, gif))
    signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, gif))

    try:
        gif.run()
    finally:
        gif.stop()
        gif.close()


if __name__ == '__main__':
    main()

