#!/usr/bin/env python3
"""
Elder Care Monitor - Reads DHT22 sensor, displays on OLED, buzzes buzzer on thresholds.
Hardware: Raspberry Pi 4 Model B, DHT22 on GPIO4, OLED (SSD1306) on I2C, Buzzer on GPIO17.
"""

import time
import datetime
import logging
import signal
import sys
import board
import adafruit_dht
from adafruit_ssd1306 import SSD1306_I2C
from gpiozero import Buzzer, OutputDevice

# Configuration
DHT_PIN = board.D4
OLED_WIDTH = 128
OLED_HEIGHT = 64
OLED_I2C_ADDR = 0x3C
BUZZER_PIN = 17
TEMP_HIGH = 30.0
TEMP_LOW = 15.0
HUM_HIGH = 80.0
READ_INTERVAL = 5
BUZZER_ON_TIME = 0.2
BUZZER_OFF_TIME = 0.3

# Logging setup
logging.basicConfig(
    filename='elder_care_monitor.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global resources for cleanup
dht_device = None
oled_display = None
buzzer = None
running = True

def signal_handler(sig, frame):
    global running
    print("\nShutting down...")
    running = False

def init_dht22():
    try:
        return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        logging.error(f"Failed to initialize DHT22: {e}")
        return None

def init_oled():
    try:
        i2c = board.I2C()
        display = SSD1306_I2C(OLED_WIDTH, OLED_HEIGHT, i2c, addr=OLED_I2C_ADDR)
        display.fill(0)
        display.text("Elder Care Monitor", 0, 0, 1)
        display.text("---", 0, 16, 1)
        return display
    except Exception as e:
        logging.error(f"Failed to initialize OLED: {e}")
        return None

def init_buzzer():
    try:
        return Buzzer(BUZZER_PIN)
    except Exception as e:
