import os
import time
import signal
import sys
import threading
from typing import List, Optional

from PIL import Image, ImageOps
from luma.core.interface.serial import spi
from luma.core.render import canvas
from luma.lcd.device import st7789

DISPLAY_WIDTH = 240
DISPLAY_HEIGHT = 240
DEFAULT_GIF_DURATION = 100  # milliseconds


class GifPlayer:
    """
    Plays GIFs on an SPI-connected ST7789 display using luma.lcd.
    """

    def __init__(self, folder_path: str):
        if not os.path.isdir(folder_path):
            raise FileNotFoundError(f"Folder not found: {folder_path}")
        self.folder_path = folder_path
        self.gif_files: List[str] = []
        self.display: Optional[st7789] = None
        self.running = False
        self._lock = threading.Lock()

    def add_gif_files(self, subfolder: str = ""):
        """Adds .gif files from a subfolder to the player's list."""
        try:
            if subfolder:
                subfolder += "/"
            gif_files = [
                f for f in os.listdir(subfolder)
                if f.lower().endswith(".gif")
            ]
            if not gif_files:
                print(f"No GIF files found in {subfolder}")
            self.gif_files.extend(gif_files)
        except FileNotFoundError:
            print(f"Folder not found: {subfolder}")
        except PermissionError:
            print(f"Permission denied accessing: {subfolder}")
        except OSError as e:
            print(f"OS error accessing {subfolder}: {e}")

    def initialize_display(self) -> None:
        """Initializes the SPI display."""
        try:
            serial = spi(port=0, device=0, bus_speed_hz=4000000,
                        gpio_DC=17, gpio_RST=12,
                        gpio_CS=24, gpio_LE=25)
            self.display = st7789(
                serial,
                width=DISPLAY_WIDTH,
                height=DISPLAY_HEIGHT,
                bgr=False,
            )
            print("Display initialized successfully.")
        except Exception as e:
            print(f"Error initializing display: {e}")
            self.display = None

    def play_gif(self, gif_file: str) -> None:
        """Plays a single GIF file."""
        if not self.display:
            print("Display not initialized.")
            return

        try:
            with Image.open(gif_file) as img:
                frames = img.convert("RGB").loop(max_frames=0)
                duration = DEFAULT_GIF_DURATION

            for frame in frames:
                with ImageOps.pad(frame, (DISPLAY_WIDTH, DISPLAY_HEIGHT), color="black") as padded_frame:
                    self.display.display(padded_frame)
                    time.sleep(duration / 1000.0)
        except FileNotFoundError:
            print(f"GIF file not found: {gif_file}")
        except Exception as e:
            print(f"Error playing GIF {gif_file}: {e}")

    def run(self) -> None:
        """Runs the GIF player indefinitely."""
        if not self.gif_files:
            print("No GIF files found in the folder.")
            return

        self.initialize_display()
        self.running = True
        print(f"Found {len(self.gif_files)} GIF files. Starting playback...")

        try:
            while self.running:
                for gif_file in self.gif_files:
                    if not self.running:
                        break
                    self.play_gif(gif_file)
        except KeyboardInterrupt:
            print("\nInterrupted by user.")
        finally:
            self.cleanup()

    def cleanup(self) -> None:
        """Releases display resources."""
        self.running = False
        if self.display:
            try:
                self.display.cleanup()
                print("Display resources released.")
            except Exception as e:
                print(f"Error during display cleanup: {e}")
            finally:
                self.display = None

    def stop(self) -> None:
        """Signals the main loop to stop."""
        self.running = False


def main() -> None:
    player = GifPlayer(".")
    signal.signal(signal.SIGINT, player.stop)
    signal.signal(signal.SIGTERM, player.stop)
    player.run()


if __name__ == "__main__":
    main()

