from PIL import Image, ImageDraw, ImageFont
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

I2C_ADDR = 0x3C
WIDTH = 128
HEIGHT = 64
GIF_FOLDER = '.'

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logger.info("Shutdown signal received. Cleaning up...")

def load_gif(gif_path):
    try:
        with Image.open(gif_path) as img:
            frames = img.convert('RGB').split()
            if not frames:
                raise ValueError("GIF has no frames")
            loop = frames[0].info.get('loop', 0)
            if loop < 0:
                raise ValueError("GIF loop count must be non-negative")
            return frames, loop
    except Exception as e:
        logger.error(f"Error loading GIF {gif_path}: {e}")
        return None, None

def resize_frame(frame, width=WIDTH, height=HEIGHT):
    try:
        img = Image.fromarray(frame)
        img = img.resize((width, height), Image.LANCZOS)
        return img.convert('RGB')
    except Exception as e:
        logger.error(f"Error resizing frame: {e}")
        return None

def get_duration(gif_path):
    try:
        with Image.open(gif_path) as img:
            info = img.info
            if 'duration' in info:
                return info['duration']
            elif 'loop' in info:
                return info['loop']
            else:
                logger.warning(f"GIF {gif_path} has no duration metadata")
                return None
    except Exception as e:
        logger.error(f"Error reading duration from GIF {gif_path}: {e}")
        return None

def display_frame(device, frame, duration):
    try:
        with canvas(device) as draw:
            draw.rectangle((0, 0, WIDTH - 1, HEIGHT - 1), outline=0, fill=0)
            draw.text((0, 0), frame.filename, fill=(255, 255, 255))
            draw.text((0, 16), f"{duration} ms", fill=(255, 255, 255))
    except Exception as e:
        logger.error(f"Error displaying frame: {e}")

def play_gif(device, gif_path, duration):
    frames, loop = load_gif(gif_path)
    if frames is None or loop is None:
        return
    try:
        for frame in frames:
            resized = resize_frame(frame, WIDTH, HEIGHT)
            if resized is None:
                continue
            duration_ms = get_duration(gif_path)
            if duration_ms is None:
                continue
            if duration_ms <= 0:
                logger.info(f"Skipping non-positive duration {duration_ms}ms for {gif_path}")
                continue
            logger.info(f"Playing {gif_path} ({duration_ms}ms)")
            display_frame(device, resized, duration_ms)
            time.sleep(duration_ms / 1000.0)
    except Exception as e:
        logger.error(f"Error playing GIF {gif_path}: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

