            logger.warning(f"No GIF files found in {GIF_FOLDER}. Nothing to play.")
            return
        gif_files = [f for f in os.listdir(GIF_FOLDER) if f.lower().endswith('.gif')]
        if not gif_files:
            logger.warning(f"No GIF files found in {GIF_FOLDER}. Nothing to play.")
            return
        gif_files.sort()
        logger.info(f"Found {len(gif_files)} GIF files")
    except Exception as e:
        logger.error(f"Error listing directory {GIF_FOLDER}: {e}")
        device.cleanup()
        sys.exit(1)

    try:
        while running:
            for gif_file in gif_files:
                if not running:
                    break
                play_gif(device, os.path.join(GIF_FOLDER, gif_file), 0)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        logger.info("Cleaning up...")
        try:
            device.cleanup()
        except Exception:
            pass
        logger.info("Program terminated.")

if __name__ == "__main__":
    main()

