import serial
import time
import signal
import sys

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
TIMEOUT = 1  # seconds

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    """Initialize and return a serial connection, or None on failure."""
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout
        )
        if not ser.is_open:
            print(f"Error: serial port {port} did not open.")
            return None
        print(f"Serial port {port} opened at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        return None

def read_temperature(serial_connection):
    """Read one line from the serial port and parse the first float temperature."""
    try:
        raw = serial_connection.readline()
        if not raw:
            return None  # timeout, no data
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        try:
            return float(line)
        except ValueError:
            print(f"Error: could not parse data as float: '{line}'")
            return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading from serial port: {e}")
        return None

def display_temperature(temperature):
    """Print the temperature to the console, or None if parsing failed."""
    if temperature is not None:
        print(f"Temperature: {temperature:.1f} C")

def main():
    """Main loop: open serial port, read and display temperature every 0.5 s."""
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        sys.exit(1)

    try:
        while _running:
            temperature = read_temperature(serial_connection)
            display_temperature(temperature)
            time.sleep(0.5)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")
        print("Program terminated.")

if __name__ == "__main__":
    main()

