import time
import logging
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 temperature and humidity sensor over I2C."""

    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    STATUS_REGISTER = 0x71
    COMMAND_REGISTER = 0xAC
    COMMAND_MEASURE = [0x33, 0x00]

    def __init__(self, bus_number=I2C_BUS, address=I2C_ADDRESS):
        self.address = address
        self.bus = None
        self._open_bus()

    def _open_bus(self):
        try:
            self.bus = smbus2.SMBus(self.I2C_BUS)
        except FileNotFoundError:
            logger.error("I2C bus %d not found. Enable I2C with 'sudo raspi-config'.", self.I2C_BUS)
            return False
        except PermissionError:
            logger.error("Permission denied opening I2C bus %d. Run as root or add user to 'i2c' group.", self.I2C_BUS)
            return False
        except Exception as e:
            logger.error("Failed to open I2C bus %d: %s", self.I2C_BUS, e)
            return False

        time.sleep(0.5)  # Allow sensor to stabilize after power-on
        status = self._read_register(self.STATUS_REGISTER)
        if (status & 0x18) != 0x18:
            logger.error("DHT20 status check failed. Expected bits 3 and 4 to be set (0x18). Got 0x%02X", status)
            self.close()
            return False
        logger.info("I2C bus %d opened and DHT20 status verified.", self.I2C_BUS)
        return True

    def _read_register(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as e:
            logger.error("I2C read error at register 0x%02X: %s", register, e)
            return None
        except Exception as e:
            logger.error("Unexpected error reading register 0x%02X: %s", register, e)
            return None

    def get_temperature_and_humidity(self):
        """Trigger a measurement and return (temperature, humidity, crc_error_flag)."""
        for attempt in range(1, 6):
            try:
                logger.info("Attempt %d/6: triggering measurement...", attempt)
                self._write_command(self.COMMAND_REGISTER, self.COMMAND_MEASURE)

                start_time = time.time()
                while True:
                    status = self._read_register(self.STATUS_REGISTER)
                    if (status & 0x80) == 0:
                        break
                    if time.time() - start_time > 0.1:
                        logger.warning("Timeout waiting for measurement completion (status bit 7 cleared).")
                        return None, None, True
                    time.sleep(0.005)

                data = self._read_register(self.STATUS_REGISTER)
                if data is None:
                    logger.error("Failed to read measurement data.")
                    return None, None, True

                raw_temp = ((data & 0x0F) << 16) | ((data & 0xF0) << 8) | (data >> 4)
                raw_hum = (((data >> 4) & 0x0F) << 16) | ((data >> 8) & 0xF0) | (data & 0x0F)

                temperature = raw_temp / 5242.88 - 50
                humidity = raw_hum / 1048576.0 * 100.0

                crc_error_flag = self._verify_crc(data[1:7])
                return temperature, humidity, crc_error_flag

            except OSError as e:
                logger.error("I2C bus error during measurement: %s", e)
                return None, None, True
            except Exception as e:
                logger.error("Unexpected error during measurement: %s", e)
                return None, None, True

        logger.error("All 6 measurement attempts failed.")
        return None, None, True

    def _write_command(self, register, command_bytes):
        try:
            self.bus.write_i2c_block_data(self.address, register, command_bytes)
        except OSError as e:
            logger.error("I2C write error at register 0x%02X: %s", register, e)
            return
        except Exception as e:
            logger.error("Unexpected error writing to register 0x%02X: %s", register, e)
            return

    def _verify_crc(self, data):
        if len(data) < 6:
            return True
        crc = 0xFF
        for byte in data[1:6]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc == 0

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None

    def __del__(self):
        self.close()


if __name__ == '__main__':
    sensor = DHT20()
    if sensor is not None:
        temp, hum, err = sensor.get_temperature_and_humidity()
        if err:
            logger.error("Measurement failed: %s", err)
        else:
            logger.info("Temperature: %.2f C, Humidity: %.2f %%", temp, hum)
    else:
        logger.error("Failed to initialize DHT20 sensor.")

