#!/usr/bin/env python3
"""Greenhouse vent controller using libgpiod.

Reads temperature from config.txt, computes vent position, logs to SQLite,
and simulates motor control.
"""

import logging
import random
import sqlite3
import sys
import time
from datetime import datetime

import gpiod

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
MOTOR_FORWARD_PIN = 17
MOTOR_BACKWARD_PIN = 18
MOTOR_ENABLE_PIN = 27

CONFIG_FILE = "config.txt"
LOG_FILE = "greenhouse_vent.log"

TEMP_MIN = 25.0
TEMP_MAX = 30.0

SAMPLE_INTERVAL = 60  # seconds

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.DEBUG,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# ---------------------------------------------------------------------------
# Global state
# ---------------------------------------------------------------------------
_gpio_chip = None
_gpio_line = None
_running = True


def _cleanup():
    """Release GPIO resources."""
    global _gpio_chip, _gpio_line
    if _gpio_line is not None:
        try:
            _gpio_line.set_value(0)
        except Exception:
            pass
        try:
            _gpio_line.close()
        except Exception:
            pass
        _gpio_line = None
    if _gpio_chip is not None:
        try:
            _gpio_chip.close()
        except Exception:
            pass
        _gpio_chip = None


def read_config():
    """Read TEMP_MIN and TEMP_MAX from config.txt.

    Returns (TEMP_MIN, TEMP_MAX) floats.
    """
    try:
        with open(CONFIG_FILE, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    continue
                key, _, value = line.partition("=")
                key = key.strip()
                value = value.strip()
                if key == "TEMP_MIN":
                    try:
                        TEMP_MIN = float(value)
                    except ValueError:
                        logging.warning("TEMP_MIN=%s (invalid), using default %s", value, TEMP_MIN)
                elif key == "TEMP_MAX":
                    try:
                        TEMP_MAX = float(value)
                    except ValueError:
                        logging.warning("TEMP_MAX=%s (invalid), using default %s", value, TEMP_MAX)
    except FileNotFoundError:
        logging.warning("config.txt not found, using defaults: TEMP_MIN=%s, TEMP_MAX=%s", TEMP_MIN, TEMP_MAX)
    except OSError as e:
        logging.error("Error reading config.txt: %s", e)


def simulate_temperature():
    """Simulate a temperature reading between 20.0 and 35.0 °C."""
    return random.uniform(20.0, 35.0)


def compute_vent_position(temperature):
    """Compute vent position (0-100%) from temperature."""
    if temperature <= TEMP_MIN:
        return 0.0
    if temperature >= TEMP_MAX:
        return 100.0
    return ((temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * 100.0


def log_data(timestamp, temperature, vent_position):
    """Insert a row into the greenhouse_data SQLite table."""
    try:
        conn = sqlite3.connect("greenhouse_data.db", timeout=5)
        cursor = conn.cursor()
        cursor.execute(
            "CREATE TABLE IF NOT EXISTS data ("
            "timestamp TEXT, temperature REAL, vent_position REAL)"
        )
        cursor.execute(
            "INSERT INTO data VALUES (?, ?, ?)",
            (timestamp, temperature, vent_position),
        )
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        logging.error("SQLite error: %s", e)
    except OSError as e:
        logging.error("Database connection error: %s", e)


def control_motor(forward, backward, enable, position):
    """Drive the motor control lines.

    forward, backward, enable are booleans. 0 = off, 1 = on.
    """
    if enable:
        try:
            _gpio_line.set_value(0)
        except Exception as e:
            logging.error("Failed to disable enable: %s", e)
    if forward:
        _gpio_line.set_value(1)
    else:
        _gpio_line.set_value(0)
    if backward:
        _gpio_line.set_value(1)
    else:
        _gpio_line.set_value(0)


def main():
    global _gpio_chip, _gpio_line

    read_config()

    # Open GPIO chip 0
    try:
        _gpio_chip = gpiod.Chip("gpio0")
    except Exception as e:
        logging.error("Failed to open GPIO chip 0: %s", e)
        sys.exit(1)

    # Line configuration
    try:
        _gpio_line = _gpio_chip.get_line(MOTOR_FORWARD_PIN)
        _gpio_line.request(consumer="greenhouse_vent", type=gpiod.LINE_REQ_DIR_OUT)
        _gpio_line.set_value(0)
    except Exception as e:
        logging.error("Failed to request GPIO line %d: %s", MOTOR_FORWARD_PIN, e)
        _cleanup()
        sys.exit(1)

    # Enable pin
    try:
        _gpio_line.set_value(0)
    except Exception as e:
        logging.error("Failed to set enable pin: %s", e)
        _cleanup()
        sys.exit(1)

    logging.info("Greenhouse vent controller started.")

    try:
        while _running:
            temperature = simulate_temperature()
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            vent_position = compute_vent_position(temperature)

            if vent_position > 100.0:
                action = "open"
                position = 100.0
            elif vent_position < 0.0:
                action = "close"
                position = 0.0
            else:
                action = "hold"
                position = round(vent_position, 1)

            logging.info(
                "Temperature: %.2f°C, Vent Position: %.1f%%, Action: %s",
                temperature,
                vent_position,
                action,
            )

            control_motor(
                forward=position > TEMP_MIN,
                backward=position < TEMP_MAX,
                enable=True,
                position=position,
            )
            log_data(timestamp, temperature, vent_position)

            # Sleep in small increments so KeyboardInterrupt is responsive
            slept = 0
            while _running and slept < SAMPLE_INTERVAL:
                time.sleep(1)
                slept += 1

    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received, shutting down.")
    except Exception as e:
        logging.error("Unexpected error: %s", e)
    finally:
        _cleanup()
        logging.info("Greenhouse vent controller stopped.")


if __name__ == "__main__":
    main()

