import serial
import signal
import sys
import time
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def parse_reading(line):
    parts = line.split(',')
    if len(parts) != 3:
        return None
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
        pressure = float(parts[2])
    except ValueError:
        return None
    if not (-40.0 <= temperature <= 85.0):
        return None
    if not (0.0 <= humidity <= 100.0):
        return None
    if not (800.0 <= pressure <= 1200.0):
        return None
    return temperature, humidity, pressure

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud.")
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break
            if not raw:
                continue
            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue
            result = parse_reading(line)
            if result is None:
                print(f"Warning: malformed reading '{line}'")
            else:
                timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                temp, hum, pres = result
                print(f"[{timestamp}] Temperature: {temp:.1f} C, Humidity: {hum:.1f} %, Pressure: {pres:.1f} hPa")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

