#!/usr/bin/env python3
"""
CPU temperature monitor for Raspberry Pi 4 Model B.

Reads the CPU temperature every 5 seconds using gpiozero.CPUTemperature.
Instantiate the sensor lazily inside the read function so a missing
/sys/class/thermal/thermal_zone0/temp file is caught as a per-read
error instead of crashing the program at startup.
"""

import sys
import time

try:
    from gpiozero import CPUTemperature
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)


TEMP_INTERVAL = 5  # seconds between readings


def read_cpu_temp() -> float | None:
    """Return the CPU temperature in °C, or None on error."""
    try:
        return float(CPUTemperature().temperature)
    except FileNotFoundError:
        print("Error: thermal sensor file not found (e.g., on a fresh Pi).", file=sys.stderr)
        return None
    except PermissionError:
        print("Error: permission denied reading thermal sensor.", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"Error reading CPU temperature: {exc}", file=sys.stderr)
        return None


def main() -> None:
    """Continuously print the CPU temperature every TEMP_INTERVAL seconds."""
    try:
        while True:
            temp = read_cpu_temp()
            if temp is not None:
                print(f"CPU Temperature: {temp:.2f} °C")
            else:
                print("Failed to read CPU temperature.")
            time.sleep(TEMP_INTERVAL)
    except KeyboardInterrupt:
        print("Program terminated")
    except Exception as exc:
        print(f"An unexpected error occurred: {exc}", file=sys.stderr)
        sys.exit(0)


if __name__ == "__main__":
    main()

