import time
import logging
import signal
import sys
from collections import deque

import smbus2
from smbus2 import i2c_msg

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

BMP280_I2C_ADDR = 0x76
BMP280_CHIP_ID = 0x58
BMP280_RESET_CMD = 0xB6
BMP280_CHIP_ID_REG = 0xD0
BMP280_PRESS_MSB = 0xF4
BMP280_TEMP_MSB = 0xF5
BMP280_CONFIG_REG = 0xF4
BMP280_PRESS_MSB_LSB = 0xF7
BMP280_TEMP_MSB_LSB = 0xFA

running = True

def signal_handler(signum, frame):
    global running
    running = False

class CalibrationError(Exception):
    pass

class BMP280:
    def __init__(self, i2c_bus=1, address=BMP280_I2C_ADDR):
        self.i2c_bus = i2c_bus
        self.address = address
        self.pressure_baseline = 0.0
        self.temperature_baseline = 0.0
        self.i2c = None
        self._initialize_sensor()

    def _initialize_sensor(self):
        try:
            self.i2c = smbus2.SMBus(self.i2c_bus)
        except OSError as e:
            raise CalibrationError(f"Failed to open I2C bus {self.i2c_bus}: {e}") from e

        try:
            chip_id = self.i2c.read_byte_data(self.address, BMP280_CHIP_ID_REG)
            if chip_id != BMP280_CHIP_ID:
                self.i2c.close()
                raise CalibrationError(
                    f"BMP280 not found at 0x{self.address:02X} (chip ID 0x{chip_id:02X}). "
