import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Initialize I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    raise SystemExit(1)

# Initialize TCA9548A multiplexer at default address 0x70
try:
    multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
except Exception as e:
    print(f"Error initializing TCA9548A multiplexer: {e}")
    i2c_bus.deinit()
    raise SystemExit(1)

# Initialize BME280 sensor on multiplexer channel 0 (default address 0x76 or 0x77)
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0], address=0x76)
except Exception as e:
    print(f"Error initializing BME280 sensor: {e}")
    multiplexer.deinit()
    i2c_bus.deinit()
    raise SystemExit(1)

# Initialize TSL2591 sensor on multiplexer channel 1 (default address 0x29)
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(multiplexer[1])
except Exception as e:
    print(f"Error initializing TSL2591 sensor: {e}")
    tsl2591_sensor = None

# Main loop to read sensor data
try:
    while True:
        try:
            # Read temperature and humidity from BME280
            temperature = bme280_sensor.temperature
            humidity = bme280_sensor.humidity

            # Read light intensity in lux from TSL2591
            light_intensity = tsl2591_sensor.lux if tsl2591_sensor else 0.0

            # Print sensor data
            print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light Intensity: {light_intensity:.2f} lux")

        except Exception as e:
            # Handle runtime errors during sensor readings
            print(f"Error reading sensor data: {e}")

        # Wait for 2 seconds before the next reading
        time.sleep(2)

except KeyboardInterrupt:
    # Exit gracefully on Ctrl+C
    print("\nExiting program...")

finally:
    # Clean up resources
    try:
        bme280_sensor.exit()
    except:
        pass
    try:
        tsl2591_sensor.exit()
    except:
        pass
    try:
        multiplexer.deinit()
    except:
        pass
    try:
        i2c_bus.deinit()
    except:
        pass

