import time
import datetime
import json
import logging
import signal
import sys
import urllib.request
import urllib.error
import board
import adafruit_dht

CONFIG_FILE = "config.json"
LOG_FILE = "greenhouse.log"

DEFAULT_CONFIG = {
    "dht_pin": 4,
    "temperature_threshold": 30,
    "humidity_threshold": 80,
    "webhook_url": "https://example.com/webhook",
    "sensor_reading_interval": 60,
    "moving_average_window": 5,
    "sensor_failure_threshold": 3,
    "sensor_failure_cooldown": 300,
    "log_level": "INFO",
    "log_file": LOG_FILE,
    "webhook_retry_delay": 1,
    "webhook_retry_delay_max": 9,
    "webhook_max_retries": 3,
    "temperature_min": -40,
    "temperature_max": 80,
    "humidity_min": 0,
    "humidity_max": 100,
    "vent_fan_threshold": 30,
    "water_pump_threshold": 60,
    "heater_threshold": 15,
}

running = True
config = DEFAULT_CONFIG.copy()
dht_device = None

logging.basicConfig(
    filename=config.get("log_file", LOG_FILE),
    level=getattr(logging, config.get("log_level", "INFO").upper(), logging.INFO),
    format="%(asctime)s - %(levelname)s - %(message)s",
)

def load_config():
    global config
    try:
        with open(CONFIG_FILE, "r") as f:
            user_config = json.load(f)
        config = {**DEFAULT_CONFIG, **user_config}
        logging.info("Configuration loaded from %s", CONFIG_FILE)
    except FileNotFoundError:
        logging.warning("config.json not found; using defaults.")
    except json.JSONDecodeError as e:
        logging.error("Invalid JSON in %s: %s; using defaults.", CONFIG_FILE, e)
    except Exception as e:
        logging.error("Unexpected error loading config: %s; using defaults.", e)

def signal_handler(signum, frame):
    global running
    logging.info("Received signal %d, shutting down...", signum)
    running = False

def read_dht22(pin):
    global dht_device
    try:
        if dht_device is None:
            dht_device = adafruit_dht.DHT22(getattr(board, f"D{pin}"))
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        logging.info("DHT22 reading: temp=%.2f°C, humidity=%.2f%%", temperature, humidity)
        return temperature, humidity
    except RuntimeError as e:
        logging.warning("DHT22 read error (sensor may be absent): %s", e)
        return None, None
    except Exception as e:
        logging.error("Unexpected DHT22 error: %s", e)
        return None, None

def simulate_sensor_data():
    temperature = round(20 + (time.time() % 20), 1)
    humidity = round(60 + (time.time() % 20), 1)
    logging.info("Simulated sensor data: temp=%.1f°C, humidity=%.1f%%", temperature, humidity)
    return temperature, humidity

def validate_sensor_data(temperature, humidity):
    if not (-40 <= temperature <= 80):
        logging.warning("Temperature out of range: %.1f°C", temperature)
        return False
    if not (0 <= humidity <= 100):
        logging.warning("Humidity out of range: %.1f%%", humidity)
        return False
    return True

def moving_average(data, window_size):
    if len(data) < window_size:
        return sum(data) / len(data) if data else 0.0
    return sum(data[-window_size:]) / window_size

def send_webhook(url, payload, retries=3):
    for attempt in range(retries):
        try:
            req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status == 200:
                    logging.info("Webhook sent successfully (HTTP %d).", resp.status)
                    return True
                else:
                    logging.error("Webhook returned HTTP %d: %s", resp.status, resp.reason)
        except urllib.error.URLError as e:
            logging.error("Webhook URL error (attempt %d/%d): %s", attempt + 1, retries, e)
        except Exception as e:
            logging.error("Webhook error (attempt %d/%d): %s", attempt + 1, retries, e)
        if attempt < retries - 1:
            time.sleep(config.get("webhook_retry_delay", 1) * (2 ** attempt))
    logging.error("Webhook failed after %d retries.", retries)
    return False

def control_actuators(temperature, humidity):
    if temperature > config.get("vent_fan_threshold", 30):
        logging.info("Vent fan activated (temp %.1f°C > %.1f°C).", temperature, config.get("vent_fan_threshold", 30))
        return "vent_fan"
    if humidity < config.get("water_pump_threshold", 60):
        logging.info("Water pump activated (humidity %.1f%% < %.1f%%).", humidity, config.get("water_pump_threshold", 60))
        return "water_pump"
    if temperature < config.get("heater_threshold", 15):
        logging.info("Heater activated (temp %.1f°C < %.1f°C).", temperature, config.get("heater_threshold", 15))
        return "heater"
    logging.info("Actuators deactivated (conditions clear).")

def main():
    global running
    load_config()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    logging.info("Greenhouse monitoring system started.")
    last_sensor_read_time = time.time()
    sensor_failure_count = 0
    sensor_failure_cooldown = config.get("sensor_failure_cooldown", 300)
    moving_average_window = config.get("moving_average_window", 5)
    moving_average_samples = []
    last_webhook_time = 0.0
    last_actuator_update_time = 0.0

    try:
        while running:
            now = time.time()
            if now - last_sensor_read_time >= config.get("sensor_reading_interval", 60):
                temperature, humidity = read_dht22(config.get("dht_pin", 4))
                if temperature is None or humidity is None:
                    logging.warning("Sensor read failed; using simulated data.")
                    temperature, humidity = simulate_sensor_data()
                else:
                    sensor_failure_count = 0
                if validate_sensor_data(temperature, humidity):
                    moving_average_window.append(temperature)
                    if len(moving_average_window) > moving_average_samples:
                        moving_average_window.pop(0)
                    moving_average_value = moving_average(moving_average_window, moving_average_samples)
                    logging.info("Moving average: %.1f°C", moving_average_value)
                    if moving_average_value > config.get("temperature_threshold", 30):
                        webhook_payload = {"temperature": moving_average_value, "timestamp": datetime.datetime.now().isoformat()}
                        if send_webhook(config.get("webhook_url", "https://example.com/webhook"), json.dumps(webhook_payload), config.get("webhook_retry_delay", 1)):
                            actuator = control_actuators(moving_average_value, moving_average_value)
                            last_actuator_update_time = now
                        else:
                            logging.error("Webhook failed; actuators not updated.")
                    elif moving_average_value < config.get("humidity_threshold", 80):
                        webhook_payload = {"humidity": moving_average_value, "timestamp": datetime.datetime.now().isoformat()}
                        if send_webhook(config.get("webhook_url", "https://example.com/webhook"), json.dumps(webhook_payload), config.get("webhook_retry_delay", 1)):
                            actuator = control_actuators(moving_average_value, moving_average_value)
                            last_actuator_update_time = now
                        else:
                            logging.error("Webhook failed; actuators not updated.")
                    else:
                        last_webhook_time = now
                else:
                    logging.warning("Sensor data validation failed; skipping webhook and actuator control.")
            else:
                time_since_last_read = now - last_sensor_read_time
                if time_since_last_read >= config.get("sensor_failure_cooldown", 300):
                    sensor_failure_count += 1
                    logging.warning("Sensor read failed %d times in a row; pausing for %d seconds.", sensor_failure_count, config.get("sensor_failure_cooldown", 300))
                    last_sensor_read_time = now + config.get("sensor_failure_cooldown", 300)
                else:
                    sensor_failure_count = 0
            time.sleep(config.get("sensor_reading_interval", 60))
    except Exception as e:
        logging.error("Unexpected error in main loop: %s", e)
    finally:
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass
        logging.info("Greenhouse monitoring system stopped.")

if __name__ == "__main__":
    main()

