import time
import signal
import sys
import logging
import paho.mqtt.client as mqtt
from paho.mqtt.client import CallbackAPIVersion

import board
import adafruit_dht

import config

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger(__name__)

DEGREE_CELSIUS = "\u00B0C"

# Global state for clean shutdown
_running = True
_client = None
_dht_device = None


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False


def _publish(client, topic, payload, retain=None, qos=None):
    if client is None or not client.is_connected():
        log.warning("MQTT client not connected; cannot publish to %s", topic)
        return False
    info = client.publish(topic, str(payload), retain=retain, qos=qos)
    if info.rc != mqtt.MQTT_ERR_SUCCESS:
        log.error("Publish to %s failed with rc=%s", topic, info.rc)
    return True


def _homie_publish(client, node, subtopic, payload, retain=None, qos=None):
    topic = f"homie/{config.homieclientid}/{node}/{subtopic}"
    _publish(client, topic, payload, retain, qos)


def _mqtt_connect(client):
    if client.is_connected():
        log.info("MQTT already connected.")
        return
    info = client.connect(config.mqttbroker, config.mqttport, keepalive=30)
    if info.rc != mqtt.MQTT_ERR_SUCCESS:
        log.error("MQTT connect to %s:%d failed: %s", config.mqttbroker, config.mqttport, info.rc)
    else:
        log.info("MQTT connected to %s:%d", config.mqttbroker, config.mqttport)
        _homie_publish(client, "$state", "$state", retain=True, qos=1)
        _homie_publish(client, "$homie", "4.0", retain=True, qos=1)
        _homie_publish(client, "$name", config.homieclientname, retain=True, qos=1)
        _homie_publish(client, "$nodes", config.homienodes, retain=True, qos=1)
        _homie_publish(client, f"{config.homienodes}/$name", "DHT22 Sensor", retain=True, qos=1)
        _homie_publish(client, f"{config.homienodes}/$properties", "temperature,humidity,humidityalarm", retain=True, qos=1)
        _homie_publish(client, f"{config.homienodes}/temperature/$name", "Temperature", retain=True, qos=1)
        _homie_publish(client, f"{config.homienodes}/temperature/$unit", DEGREE_CELSIUS, retain=True, qos=1)
        _homie_publish(client, f"{config.homienodes}/humidity/$name", "Humidity", retain=True, qos=1)
        _homie_publish(client, f"{config.homienodes}/humidity/$unit", "%", retain=True, qos=1)
        _homie_publish(client, f"{config.homienodes}/humidityalarm/$name", "Humidity Alarm", retain=True, qos=1)
        _homie_publish(client, f"{config.homienodes}/humidityalarm/$datatype", "boolean", retain=True, qos=1)
        _homie_publish(client, f"{config.homienodes}/humidityalarm/$settable", "false", retain=True, qos=1)

def _mqtt_publish(client, topic, payload, retain=None, qos=None):
    _homie_publish(client, "", topic, payload, retain, qos)


def _mqtt_loop(client):
    while _running:
        if client.is_connected():
            for topic, payload in (
                ("homie/homie/status", "1"),
                ("homie/homie/devicenodes", config.homienodes),
            ):
                _mqtt_publish(client, topic, payload)
            time.sleep(1)
        else:
            log.warning("MQTT disconnected; attempting reconnect...")
            client.reconnect()
            time.sleep(2)


def _mqtt_connect_reconnect(client):
    while _running:
        if not client.is_connected():
            log.warning("MQTT disconnected; attempting reconnect...")
            client.reconnect()
            time.sleep(2)
        else:
            time.sleep(0.5)


def _mqtt_publish_reconnect(client, topic, payload, retain=None, qos=None):
    while _running:
        if client.is_connected():
            _mqtt_publish(client, topic, payload)
            time.sleep(1)
        else:
            log.warning("MQTT disconnected; attempting reconnect...")
            client.reconnect()
            time.sleep(2)


def _read_dht22():
    """Return (temperature, humidity) or (None, None) after 3 retries."""
    for attempt in range(1, 4):
        try:
            temperature = _dht_device.temperature
            humidity = _dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            log.warning("DHT22 returned None (attempt %d/3)", attempt)
        except RuntimeError as e:
            log.warning("DHT22 read error (attempt %d/3): %s", attempt, e)
        except Exception as e:
            log.error("Unexpected DHT22 error (attempt %d/3): %s", attempt, e)
        if attempt < 3:
            time.sleep(2)
    return None, None


def _init_dht22():
    global _dht_device
    try:
        pin = getattr(board, f"D{config.dhtgpiopin}")
        _dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
        log.info("DHT22 initialized on GPIO%d", config.dhtgpiopin)
        time.sleep(2)  # warm-up
    except Exception as e:
        log.error("DHT22 init failed: %s", e)
        _dht_device = None


def _cleanup():
    global _client, _dht_device
    log.info("Cleaning up resources...")
    if _client is not None:
        try:
            _mqtt_disconnect(_client)
        except Exception:
            pass
    if _dht_device is not None:
        try:
            _dht_device.exit()
        except Exception:
            pass
    _dht_device = None


def main():
    global _client, _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _init_dht22()

    try:
        _client = mqtt.Client(
            callback_api_version=CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            clean_session=True,
        )
        _client.username_pw_set(config.mqttusername, config.mqttpassword)
        _client.on_connect = _mqtt_connect_reconnect
        _client.on_disconnect = _mqtt_connect_reconnect
        _client.on_publish = _mqtt_connect_reconnect

        _client.connect(config.mqttbroker, config.mqttport, keepalive=30)
        _client.loop_start()

        _mqtt_connect(_client)

        while _running:
            temperature, humidity = _read_dht22()
            if temperature is not None and humidity is not None:
                _mqtt_publish_reconnect(_client, f"{config.homienodes}/temperature", f"{temperature:.1f}")
                _mqtt_publish_reconnect(_client, f"{config.homienodes}/humidity", f"{humidity:.1f}")
            else:
                log.warning("Skipping publish due to DHT22 read failure")

            for _ in range(config.publishtime):
                if not _running:
                    break
                time.sleep(1)

    except Exception as e:
        log.error("Fatal error: %s", e)
    finally:
        _cleanup()
        log.info("Shutdown complete.")


if __name__ == "__main__":
    main()

