        self.serial_port = None
        self.data_queue = queue.Queue(maxsize=FRAME_QUEUE_MAXSIZE)
        self.running = False
        self.frame = None
        self.event = threading.Event()

    def start_serial_reader(self):
        try:
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Serial reader started on {self.port} at {self.baudrate} baud.")
        except serial.SerialException as e:
            logging.error(f"Error opening serial port {self.port}: {e}")
            return False
        except Exception as e:
            logging.error(f"Unexpected error opening serial port: {e}")
            return False

        self.running = True
        return True

    def read_serial_data(self):
        while self.running:
            try:
                if self.serial_port.in_waiting > 0:
                    raw_line = self.serial_port.readline()
                    if not raw_line:
                        continue
                    line = raw_line.decode('ascii', errors='replace').strip()
                    if not line:
                        continue
                    logging.debug(f"Received: {line}")
                    self.process_serial_data(line)
            except serial.SerialException as e:
                logging.error(f"Serial read error: {e}")
                self.running = False
                break
            except Exception as e:
                logging.error(f"Unexpected error reading serial data: {e}")
                self.running = False
                break

        self.stop_serial_reader()

    def stop_serial_reader(self):
        self.running = False
        if self.serial_port and self.serial_port.is_open:
            try:
                self.serial_port.close()
                logging.info("Serial port closed.")
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")
        self.serial_port = None

    def process_serial_data(self, data):
        try:
            if not data:
                return
            data_list = [int(x) for x in data.split(',')]
            if len(data_list) != 768:
                logging.warning(f"Invalid data length: {len(data_list)}. Expected 768.")
                return
            data_array = np.array(data_list, dtype=np.int16).reshape(24, 32)
            self.data_queue.put(data_array)
        except ValueError as e:
            logging.error(f"Invalid data format: {e}")
        except Exception as e:
            logging.error(f"Error processing data: {e}")

    def get_frame(self):
        while True:
            if self.data_queue.empty():
                time.sleep(0.01)
                continue
            try:
                frame = self.data_queue.get(timeout=1.0)
                self.frame = frame
                return True
            except queue.Empty:
                continue
            except Exception as e:
                logging.error(f"Error getting frame: {e}")
                return False

    def update_image(self, fig, ax, data):
        if data is None:
            return
        if data.shape != self.frame.shape:
            logging.warning("Frame shape mismatch. Recreating heatmap.")
            data = self.frame
        im = ax.imshow(data, cmap='inferno', interpolation='nearest')
        fig.colorbar(im, ax=ax, label='Temperature')
        return im,

    def run(self):
        if not self.start_serial_reader():
            return
        try:
            fig, ax = plt.subplots()
            im = None
            while self.running:
                if not self.get_frame():
                    continue
                im, = self.update_image(fig, ax, self.frame)
                fig.canvas.draw_idle()
                fig.canvas.flush_events()
                time.sleep(UPDATE_INTERVAL)
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received.")
        finally:
            self.stop_serial_reader()
            plt.close(fig)

if __name__ == '__main__':
    reader = SerialThermalReader(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if reader.start_serial_reader():
        reader.run()

