import json
import signal
import sys
import time
import random
from datetime import datetime, timezone

try:
    from gpiozero import PWMLED, Device
    from gpiozero.pins.native import NativeFactory
    Device.pin_factory = NativeFactory()
except Exception as e:
    print(f"Failed to import gpiozero: {e}", file=sys.stderr)
    sys.exit(1)

try:
    import adafruit_dht
    from board import D4
except Exception as e:
    print(f"Failed to import adafruit_dht: {e}", file=sys.stderr)
    adafruit_dht = None
    D4 = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LED_PIN = 17
DHT_PIN = 4
PWM_FREQ = 100          # Hz
DUTY_MAX = 90           # percent
DUTY_MIN = 0
DUTY_STEP = 5           # percent per transition step
SUNRISE_DURATION = 600  # seconds
DAYTIME_DURATION = 10   # seconds
SUNSET_DURATION = 600   # seconds
OVERRIDE_RETRY_DELAY = 1  # seconds

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
led = None
dht_sensor = None
running = True


def log_entry(timestamp, brightness, temperature, humidity):
    """Print a timestamped log entry as JSON-like text."""
    print(json.dumps({
        "timestamp": timestamp,
        "brightness": brightness,
        "temperature": temperature,
        "humidity": humidity,
    }))


def read_dht22():
    """Return (temperature, humidity) from the DHT22, or (None, None)."""
    if dht_sensor is None:
        return None, None
    for attempt in range(3):
        try:
            temp = dht_sensor.temperature
            hum = dht_sensor.humidity
            if temp is not None and hum is not None:
                return temp, hum
        except RuntimeError as e:
            # DHT22 often throws transient read errors; retry.
            if attempt < 2:
                time.sleep(0.5)
        except Exception as e:
            # Unexpected error – log and stop retrying.
            print(f"DHT22 read error: {e}", file=sys.stderr)
            return None, None
    return None, None


def cleanup(signum=None, frame=None):
    """Release all resources and exit cleanly."""
    global running, led, dht_sensor
    running = False
    print("\nShutting down...")
    if led is not None:
        try:
            led.value = 0
            led.close()
        except Exception:
            pass
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception:
            pass
    sys.exit(0)


def main():
    global led, dht_sensor, running

    # Register signal handlers for graceful shutdown.
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # --- Initialise LED (hardware PWM on GPIO17) ---
    try:
        led = PWMLED(LED_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Failed to initialise LED on GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    # --- Initialise DHT22 (optional) ---
    if adafruit_dht is not None and D4 is not None:
        try:
            dht_sensor = adafruit_dht.DHT22(D4, use_pulseio=False)
        except Exception as e:
            print(f"Failed to initialise DHT22 on GPIO{DHT_PIN}: {e}", file=sys.stderr)
            dht_sensor = None
    else:
        print("adafruit-circuitpython-dht or board not available; DHT22 disabled.", file=sys.stderr)
        dht_sensor = None

    # --- Sunrise / sunset simulation loop ---
    while running:
        # --- Sunrise phase (0 -> DUTY_MAX) ---
        brightness = 0
        for step in range(DUTY_MIN, DUTY_MAX + 1, DUTY_STEP):
            if not running:
                break
            led.value = step / 100.0
            time.sleep(1)
            brightness = step
            log_entry(
                datetime.now(timezone.utc).isoformat(),
                brightness,
                None,
                None
            )
            if step == DUTY_MAX:
                break
            if step == DUTY_MAX - 1:
                temp, hum = read_dht22()
                if temp is not None and hum is not None:
                    print(f"Sunrise: {temp:.1f}°C, {hum:.1f}%")
                else:
                    print("Sunrise: DHT22 read failed")
            else:
                temp, hum = read_dht22()
                if temp is not None and hum is not None:
                    print(f"Sunrise: {temp:.1f}°C, {hum:.1f}%")
                else:
                    print("Sunrise: DHT22 read failed")

        # --- Hold at daytime brightness (DUTY_MAX) for DAYTIME_DURATION ---
        if not running:
            break
        led.value = 1.0
        time.sleep(DAYTIME_DURATION)
        brightness = DUTY_MAX
        log_entry(
            datetime.now(timezone.utc).isoformat(),
            brightness,
            None,
            None
        )

        # --- Sunset phase (DUTY_MAX -> 0) ---
        for step in range(DUTY_MAX, DUTY_MIN - 1, -DUTY_STEP):
            if not running:
                break
            led.value = step / 100.0
            time.sleep(1)
            brightness = step
            log_entry(
                datetime.now(timezone.utc).isoformat(),
                brightness,
                None,
                None
            )
            if step == DUTY_MIN:
                break
            if step == DUTY_MIN - 1:
                temp, hum = read_dht22()
                if temp is not None and hum is not None:
                    print(f"Sunset: {temp:.1f}°C, {hum:.1f}%")
                else:
                    print("Sunset: DHT22 read failed")
            else:
                temp, hum = read_dht22()
                if temp is not None and hum is not None:
                    print(f"Sunset: {temp:.1f}°C, {hum:.1f}%")
                else:
                    print("Sunset: DHT22 read failed")

        # --- Hold at nighttime brightness (0) for SUNSET_DURATION ---
        if not running:
            break
        led.value = 0
        time.sleep(SUNSET_DURATION)
        brightness = 0
        log_entry(
            datetime.now(timezone.utc).isoformat(),
            brightness,
            None,
            None
        )

        # --- Manual override ---
        try:
            raw = input("Enter brightness (0-90) or 'auto' to resume schedule, 'exit' to quit: ").strip()
        except EOFError:
            print("\nEOF received; exiting.")
            break

        if raw.lower() == "auto":
            brightness = DUTY_MAX
        elif raw.lower() == "exit":
            break
        elif raw.isdigit():
            brightness = int(raw)
            if 0 <= brightness <= DUTY_MAX:
                brightness = max(DUTY_MIN, min(DUTY_MAX, brightness))
                led.value = brightness / 100.0
                print(f"Manual override: brightness set to {brightness}%")
            else:
                print("Invalid brightness value. Must be between 0 and 90.")
        else:
            print("Invalid input. Please enter a number or 'auto', 'exit', or 'auto'.")

    # --- Cleanup on exit ---
    cleanup()


if __name__ == "__main__":
    main()

