import time
import signal
import sys
import logging
from datetime import datetime

try:
    import board
    import adafruit_dht
except Exception:
    board = None
    adafruit_dht = None

try:
    from gpiozero import OutputDevice
except Exception:
    OutputDevice = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DHT_PIN = board.D17 if board else None
FAN_PIN = 18
LOG_FILE = "urban_data_log.txt"
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
READ_COUNT = 5
READ_INTERVAL = 2.0

# ---------------------------------------------------------------------------
# Logging setup
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    datefmt="%Y-%m-%dT%H:%M:%S",
)
log = logging.getLogger("urban_monitor")

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_fan = None
_sensor = None
_running = True


def _cleanup():
    """Release GPIO resources safely."""
    global _fan, _sensor
    if _fan is not None:
        try:
            _fan.close()
        except Exception:
            pass
        _fan = None
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def _init_sensor():
    """Initialize the DHT11 sensor; return None on failure."""
    if adafruit_dht is None:
        log.warning("adafruit-circuitpython-dht not installed – sensor disabled.")
        return None
    try:
        return adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        log.warning("DHT11 init failed (%s) – sensor disabled.", exc)
        return None


def _init_fan():
    """Initialize the fan GPIO; return None on failure."""
    if OutputDevice is None:
        log.warning("gpiozero not installed – fan disabled.")
        return None
    try:
        return OutputDevice(FAN_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        log.warning("Fan GPIO init failed (%s) – fan disabled.", exc)
        return None


def read_sensor(sensor):
    """Return (temperature, humidity) or (None, None) on failure."""
    if sensor is None:
        return None, None
    try:
        temp = sensor.temperature
        hum = sensor.humidity
        if temp is None or hum is None:
            return None, None
        return float(temp), float(hum)
    except RuntimeError as exc:
        # DHT11 checksum / timing glitches are common; log and keep previous state.
        log.warning("Sensor read error: %s – keeping previous fan state.", exc)
        return None, None
    except Exception as exc:
        log.error("Unexpected sensor error: %s", exc)
        return None, None


def log_reading(temp, hum, fan_state):
    """Append a timestamped reading to the log file."""
    ts = datetime.now().isoformat(timespec="seconds")
    line = f"{ts} - Temp: {temp:.1f}°C, Humidity: {hum:.1f}%, Fan: {fan_state}"
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as fh:
            fh.write(line + "\n")
    except OSError as exc:
        log.error("Failed to write log: %s", exc)
    else:
        log.info(line)


def main():
    global _fan, _sensor

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _fan = _init_fan()
    _sensor = _init_sensor()

    fan_state = False

    try:
        for i in range(1, READ_COUNT + 1):
            if not _running:
                break

            temp, hum = read_sensor(_sensor)

            if temp is not None and hum is not None:
                if temp > TEMP_THRESHOLD or hum > HUMIDITY_THRESHOLD:
                    if not fan_state:
                        _fan.on()
                    fan_state = True
                    log.info("Fan ON  (temp=%.1f°C, humidity=%.1f%%)", temp, hum)
                else:
                    if fan_state:
                        _fan.off()
                    fan_state = False
                    log.info("Fan OFF  (temp=%.1f°C, humidity=%.1f%%)", temp, hum)

                log_reading(temp, hum, fan_state)
            else:
                log.warning("Sensor read failed – keeping previous fan state.")
                log_reading(None, None, fan_state)

            if i < READ_COUNT:
                time.sleep(READ_INTERVAL)

    except Exception as exc:
        log.exception("Fatal error: %s", exc)
    finally:
        _cleanup()
        log.info("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

