SEA_LEVEL_HPA = 1013.25

def main():
    # Initialize I2C bus 1 (GPIO2/SDA, GPIO3/SCL)
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return

    # Initialize BMP280 at explicit address 0x76 (SDO -> GND)
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=I2C_ADDR)
    except ValueError as e:
        print(f"Error: BMP280 not found at 0x{I2C_ADDR:02X}: {e}")
        return
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return

    # Configure sea-level pressure for meaningful altitude
    try:
        sensor.sea_level_pressure = SEA_LEVEL_HPA
    except Exception as e:
        print(f"Error setting sea level pressure: {e}")
        return

    print("BMP280 initialized. Logging to 'altitude_log.txt'. Press Ctrl+C to stop.")

    try:
        while True:
            try:
                pressure_hpa = sensor.pressure
                altitude_m = sensor.altitude

                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_entry = f"{timestamp} - Pressure: {pressure_hpa:.2f} hPa, Altitude: {altitude_m:.2f} meters\n"

                with open(LOG_FILE, 'a') as f:
