                print(f"Pressure: {pressure_hpa:.2f} hPa, Altitude: {altitude_m:.2f} meters")

            except OSError as e:
                print(f"I2C communication error: {e}")
            except Exception as e:
                print(f"Unexpected error during read/write: {e}")

            time.sleep(1)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")

if __name__ == '__main__':
    main()

