import time
import signal
import sys
import requests
import adafruit_dht
from board import D4

# Configuration
DHT_PIN = D4
SERVER_URL = 'http://127.0.0.1:5000/data'
READ_INTERVAL = 5  # seconds

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_sensor(sensor):
    """Read temperature and humidity from the DHT11 sensor.
    Returns (temperature, humidity) or (None, None) on failure."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is not None and humidity is not None:
            return temperature, humidity
        return None, None
    except RuntimeError as e:
        # DHT11 often throws transient read errors; log and retry
        print(f"Sensor read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected sensor error: {e}")
        return None, None

def send_data(temperature, humidity):
    """Send sensor data to the server as JSON via HTTP POST."""
    payload = {'temperature': temperature, 'humidity': humidity}
    try:
        response = requests.post(SERVER_URL, json=payload, timeout=10)
        print(f"Server response: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Error sending data: {e}")

def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize DHT11 sensor on GPIO4 (board.D4)
    try:
        sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 sensor: {e}")
        sys.exit(1)

    print("DHT11 sensor initialized. Starting readings every 5 seconds...")

    try:
        while _running:
            temperature, humidity = read_sensor(sensor)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                send_data(temperature, humidity)
            else:
                print("Skipping transmission: invalid sensor data.")

            # Sleep in small increments to allow prompt signal handling
            for _ in range(READ_INTERVAL):
                if not _running:
                    break
                time.sleep(1)

    finally:
        # Clean resource release on every exit path
        try:
            sensor.exit()
        except Exception:
            pass
        print("Sensor resources released. Exiting.")

if __name__ == "__main__":
    main()

