    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def get_cpu_temp():
    """Return CPU temperature in °C, or None on error."""
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
        )
        if result.returncode != 0:
            log.error("vcgencmd failed (rc=%d): %s", result.returncode, result.stderr.strip())
            return None
        out = result.stdout.strip()
        if not out.startswith("temp="):
            log.error("Unexpected vcgencmd output: %r", out)
            return None
        return float(out.split("=")[1].split("'")[0])
    except FileNotFoundError:
        log.error("vcgencmd not found on PATH")
        return None
    except (subprocess.TimeoutExpired, IndexError, ValueError) as exc:
        log.error("Failed to parse temperature: %s", exc)
        return None


def duty_for_temp(temp):
