        return 100.0
    if temp > 70:
        return 100.0
    if temp > 60:
        return 85.0
    if temp > 50:
        return 70.0
    if temp > 40:
        return 50.0
    if temp > 32:
        return 25.0
    if temp > 25:
        return 15.0
    return 0.0


