import time
import signal
import sys
import logging

import paho.mqtt.client as mqtt
import adafruit_dht
from board import Pin

import config

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger(__name__)

DEGREE_CELSIUS = "\u00B0C"

running = True

def signal_handler(signum, frame):
    global running
    log.info("Signal %s received, shutting down...", signum)
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to MQTT broker")
    else:
        log.error("MQTT connection failed with reason code %s", reason_code)

def on_disconnect(client, userdata, flags, reason_code, properties):
    log.warning("Disconnected from MQTT broker (reason code %s)", reason_code)

def on_publish(client, userdata, mid, reason_code, properties):
    log.debug("Publish acknowledged (mid=%s)", mid)

def read_dht22(sensor):
    """Read temperature and humidity from the DHT22 with a 2-second minimum interval."""
    deadline = time.monotonic() + 2.0
    while time.monotonic() < deadline:
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            log.warning("DHT22 read error (retrying): %s", e)
        except Exception as e:
            log.error("Unexpected DHT22 error: %s", e)
        time.sleep(0.5)
    return None, None

def publish_data(client, node_id, temperature, humidity):
    """Publish temperature and humidity to the MQTT broker."""
    if temperature is None or humidity is None:
        log.warning("Skipping publish: invalid sensor data")
        return
    topic = f"homie/{config.homieclientid}/{node_id}/temperature"
    client.publish(topic, f"{temperature:.1f}", qos=1)
    topic = f"homie/{config.homieclientid}/{node_id}/humidity"
    client.publish(topic, f"{humidity:.1f}", qos=1)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    sensor = None
    client = None
    try:
        sensor = adafruit_dht.DHT22(Pin(config.dhtgpiopin), use_pulseio=False)
        log.info("DHT22 initialized on GPIO %s", config.dhtgpiopin)

        client = mqtt.Client(
            mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            clean_session=True,
        )
        client.on_connect = on_connect
        client.on_disconnect = on_disconnect
        client.on_publish = on_publish

        client.connect(config.mqttbroker, port=config.mqttport, keepalive=30)
        client.loop_start()

        while running:
            temperature, humidity = read_dht22(sensor)
            if temperature is not None and humidity is not None:
                log.info("Temperature: %.1f%s, Humidity: %.1f%%", temperature, DEGREE_CELSIUS, humidity)
                publish_data(client, config.homienodes, temperature, humidity)
            else:
                log.warning("Skipping publish due to sensor read failure")
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        log.error("Fatal error: %s", e)
    finally:
        if client is not None:
            try:
                client.loop_stop()
                client.disconnect()
            except Exception:
                pass
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        log.info("Cleanup complete")

if __name__ == "__main__":
    main()

