import smbus2
import time
import signal
import sys

# Constants
I2C_BUS = 1
I2C_ADDR = 0x38
MEASURE_TRIGGER = [0xAC, 0x33, 0x00]
RESET_CMD = 0xBA
INIT_CMD = [0xBE, 0x08, 0x00]
READ_DELAY = 0.02  # 20 ms
INIT_DELAY = 0.01  # 10 ms
CRC_POLY = 0x31
CRC_INIT = 0xFF

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    global _running
    _running = False

def crc8(data):
    crc = CRC_INIT
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ CRC_POLY) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def init_sensor(bus):
    try:
        bus.write_byte(I2C_ADDR, RESET_CMD[0])
        time.sleep(READ_DELAY)
        status = bus.read_byte(I2C_ADDR)
        if not (status & 0x80):
            print("Sensor not initialised (calibration bit not set).")
            return False
        return True
    except IOError as e:
        print(f"Error communicating with sensor during init: {e}")
        return False

def init_sensor_if_needed(bus):
    if not init_sensor(bus):
        return False
    return True

def read_sensor(bus):
    try:
        bus.write_i2c_block_data(I2C_ADDR, MEASURE_TRIGGER[0], MEASURE_TRIGGER)
        time.sleep(0.08)
        data = bus.read_i2c_block_data(I2C_ADDR, 7, 7)
        if data[0] & 0x80:
            print("Sensor busy during read.")
            return None
        return data
    except IOError as e:
        print(f"Error reading sensor data: {e}")
        return None

def process_data(data):
    if data is None:
        return None, None
    status = data[0]
    if not (status & 0x7F):
        print("CRC error in sensor data.")
        return None, None
    humid = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4))
    temp = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
    humid = (humid / 0x100000) * 100.0
    temp_f = temp * 9.0 / 5.0 + 32.0
    return temp, temp_f

def main():
    signal.signal(signal.SIGINT, signal_handler)
    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS)
        if not init_sensor_if_needed(bus):
            print("Failed to initialise sensor. Exiting.")
            return
        while _running:
            data = read_sensor(bus)
            if data is not None:
                temp, temp_f = process_data(data)
                if temp is not None:
                    print(f"Timestamp: {time.strftime('%Y-%m-%d %H:%M:%S')}")
                    print(f"Temperature: {temp:.2f} C / {temp_f:.2f} F")
                    print(f"Humidity: {temp:.2f} %")
            time.sleep(5)
    except IOError as e:
        print(f"I2C bus error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print("Exiting program.")

if __name__ == "__main__":
    main()

