        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
    except serial.SerialException as e:
        log_message(f"Serial port initialization failed: {e}")
        GPIO.cleanup()
        sys.exit(1)

    log_message("System started")

    try:
        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                log_message(f"Serial read error: {e}")
                time.sleep(1)
                continue

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            parts = line.split(',')
            if len(parts) != 2:
                log_message(f"Malformed line (expected 2 fields, got {len(parts)}): {line}")
                continue

            try:
                temperature = float(parts[0])
                humidity = float(parts[1])
            except ValueError:
                log_message(f"Invalid numeric data: {line}")
                continue

            if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
                log_message(f"ALERT: Temperature {temperature:.1f}°C, Humidity {humidity:.1f}%")
                try:
                    GPIO.output(ALERT_PIN, GPIO.HIGH)
                    time.sleep(5)
                    GPIO.output(ALERT_PIN, GPIO.LOW)
                except Exception as e:
                    log_message(f"GPIO output error: {e}")

            log_message(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")

    finally:
        try:
            GPIO.output(ALERT_PIN, GPIO.LOW)
        except Exception:
            pass
        GPIO.cleanup()
        try:
            ser.close()
        except Exception:
            pass
        log_message("System stopped")

if __name__ == '__main__':
    main()

