# Initialize the DHT11 sensor on GPIO4 (physical pin 7)
dht_device = adafruit_dht.DHT11(board.D4)

try:
    while True:
        try:
            # Read temperature in Celsius
            temperature_c = dht_device.temperature
            if temperature_c is not None:
                print(f"Temperature: {temperature_c:.1f} °C")
            else:
                print("Error: sensor returned None for temperature.")
        except RuntimeError as e:
            # DHT11 sensors occasionally miss pulses or fail checksum validation
            print(f"RuntimeError reading DHT11: {e}")
        except Exception as e:
            # Catch-all for unexpected errors so the script never crashes silently
            print(f"Unexpected error: {e}")

        # Wait 5 seconds before the next reading
        time.sleep(5)

except KeyboardInterrupt:
    # Graceful exit on Ctrl+C
    print("\nExiting program.")

finally:
    # Release the GPIO resources held by the DHT11 device
    try:
        dht_device.exit()
    except Exception:
        pass

