import signal
import sys
import time

from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 100
ON_TEMP = 40.0
OFF_TEMP = 20.0
ON_DUTY = 1.0
OFF_DUTY = 0.2
DELAY = 5

fan = None
running = True


def cleanup(signum=None, frame=None):
    global running
    running = False
    if fan is not None:
        try:
            fan.value = 0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global fan
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    while running:
        try:
            temp = get_cpu_temp()
            if temp is None:
                time.sleep(DELAY)
                continue
            if temp > ON_TEMP:
                fan.value = ON_DUTY
            else:
                fan.value = OFF_DUTY
        except Exception as e:
            print(f"Error reading temperature: {e}", file=sys.stderr)
            time.sleep(DELAY)
        time.sleep(DELAY)

    cleanup()


def get_cpu_temp():
    import psutil
    try:
        return psutil.sensors_temperatures()['cpu_thermal'][0].current
    except Exception:
        return None


if __name__ == "__main__":
    main()

