import time
import signal
import sys
from gpiozero import InputDevice
from gpiozero.exc import GPIOZeroError

# BCM GPIO22 is wired to the reed switch (normally-closed to GND).
# pull_up=True enables the internal pull-up resistor; active_state=None
# tells gpiozero to auto-detect the active level (active_low by default).
SENSOR_PIN = 22
POLL_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    # Install signal handlers for clean shutdown on SIGTERM (e.g. systemd)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        # gpiozero InputDevice auto-detects the pull-up and active level.
        # active_state=None means the default active_low behaviour is used.
        sensor = InputDevice(SENSOR_PIN, pull_up=True)
        print(f"Monitoring door sensor on BCM GPIO{SENSOR_PIN} (normally-closed to GND).")

        while _running:
            try:
                if sensor.is_active:
                    print("Door Closed")
                else:
                    print("Door Open")
            except GPIOZeroError as e:
                print(f"GPIO read error: {e}", file=sys.stderr)
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if sensor is not None:
            try:
                sensor.close()
                print("GPIO resource released.")
            except Exception as e:
                print(f"Error during cleanup: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

