import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# BCM pin numbers for the three sensors
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0  # seconds

# Global list so the signal handler can release every pin
_sensors = []


def cleanup(signum=None, frame=None):
    """Release all GPIO resources and exit cleanly."""
    for sensor in _sensors:
        try:
            sensor.close()
        except Exception:
            pass
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
        sys.exit(0)


def main():
    global _sensors

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize each sensor with an active-high pull-up (idle HIGH)
    try:
        for pin in SENSOR_PINS:
            sensor = DigitalInputDevice(pin, pull_up=True)
            _sensors.append(sensor)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize GPIO pins: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO setup: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print(f"Monitoring sensors on GPIO pins {SENSOR_PINS} "
          f"every {POLL_INTERVAL} s. Press Ctrl+C to stop.")

    try:
        while True:
            for idx, sensor in enumerate(_sensors):
                try:
                    if sensor.is_active:
                        print(f"Response for sensor {idx + 1}")
                except GPIODeviceError as exc:
                    print(f"Error reading pin {SENSOR_PINS[idx]}: {exc}",
                          file=sys.stderr)
                except Exception as exc:
                    print(f"Unexpected error reading pin {SENSOR_PINS[idx]}: {exc}",
                          file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    main()

