import RPi.GPIO as DOG
import time
import threading
import sys

# Constants
LOG_FILE = "LOG.txt"
POLL_INTERVAL = 0.1

# Global state
server_running = False
receive_thread = None
log_file_path = LOG_FILE

# GPIO setup
try:
    DOG.setmode(DOG.BCM)
    DOG.setup(DOG.IN, DOG.IN)
except Exception as e:
    print(f"Error initializing GPIO: {e}")
    sys.exit(1)

def cleanup_gpio(signum=None, frame=None):
    """Clean up GPIO resources and exit."""
    global server_running, receive_thread
    server_running = False
    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=1.0)
    DOG.cleanup()
    if signum is not None:
        sys.exit(0)

def start_server(filename):
    """Starts the server and begins logging."""
    global server_running, receive_thread, log_file_path
    try:
        with open(filename, "a") as f:
            pass
        log_file_path = filename
        server_running = True
        receive_thread = threading.Thread(target=receive_data, daemon=True)
        receive_thread.start()
    except Exception as e:
        print(f"Error starting server: {e}")
        server_running = False

def receive_data():
    """Continuously receives data and writes it to the log file."""
    global server_running
    while server_running:
        try:
            data = DOG.receive()
            if data:
                with open(log_file_path, "a") as f:
                    f.write(data + "\n")
        except Exception as e:
            print(f"Error receiving data: {e}")
        time.sleep(POLL_INTERVAL)

def send_data(data_string):
    """Sends data using DOG.send()."""
    try:
        DOG.send(data_string)
    except Exception as e:
        print(f"Error sending data: {e}")

def write_data(data_string):
    """Writes data directly to the log file."""
    try:
        with open(log_file_path, "a") as f:
            f.write(data_string + "\n")
    except Exception as e:
        print(f"Error writing data: {e}")

def display_log():
    """Displays the contents of the log file."""
    try:
        with open(log_file_path, "r") as f:
            print(f.read())
    except FileNotFoundError:
        print("Log file not found.")
    except Exception as e:
        print(f"Error displaying log: {e}")

def help_command(command):
    """Provides help information for commands."""
    help_commands = {
        "start": "Starts the server and begins logging.",
        "stop": "Stops the server and the receive thread.",
        "help": "Displays help information.",
        "display": "Displays the contents of the log file.",
        "send": "Sends data using DOG.send().",
        "write": "Writes data directly to the log file.",
        "exit": "Exits the server and cleans up GPIO."
    }
    if command in help_commands:
        print(help_commands[command])
    else:
        print("Invalid command. Available commands: start, stop, help, display, send, write, exit")

def main():
    """Main function to handle user input and server operations."""
    global server_running, receive_thread

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup_gpio)
    signal.signal(signal.SIGTERM, cleanup_gpio)

    while True:
        try:
            command = input("JAYES@ROVER53:\t").lower()

            if command.startswith("start"):
                filename = input("Filename: ").strip()
                if filename:
                    start_server(filename)
                else:
                    print("Please enter a filename.")

            elif command.startswith("stop"):
                if server_running:
                    cleanup_gpio()
                else:
                    print("Server is not running.")

            elif command.startswith("help"):
                help_command(command.split()[1])

            elif command == "display":
                display_log()

            elif command.startswith("send"):
                data_string = input("Data: ").strip()
                if data_string:
                    send_data(data_string)
                else:
                    print("Please enter data to send.")

            elif command.startswith("write"):
                data_string = input("Data: ").strip()
                if data_string:
                    write_data(data_string)
                else:
                    print("Please enter data to write.")

            elif command == "exit":
                if server_running:
                    cleanup_gpio()
                else:
                    print("Server is not running.")
                break

            else:
                print("Invalid command. Available commands: start, stop, help, display, send, write, exit")

        except EOFError:
            print("\nEOF received. Exiting.")
            cleanup_gpio()
            break
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

