#!/usr/bin/env python3
"""
Ambient-light-to-LED-brightness controller for Raspberry Pi.

Reads lux from a TSL2561 sensor over I2C (bus 1, address 0x39) and drives
PWM on GPIO 18 (BCM) to match the lux reading to a 0-100% brightness.

Wiring:
  TSL2561 SDA -> GPIO2 (I2C bus 1 SDA)
  TSL2561 SCL -> GPIO3 (I2C bus 1 SCL)
  TSL2561 VDD -> 3.3 V
  TSL2561 GND -> GND
  LED anode -> GPIO 18 (via ~330 ohm resistor)
  LED cathode -> GND

Dependencies:
  pip install adafruit-circuitpython-tsl2561 RPi.GPIO
"""

import signal
import sys
import time

import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LED_PIN = 18
PWM_FREQ = 1000          # Hz
LUX_MIN = 0.0            # lux -> 0 %
LUX_MAX = 1000.0         # lux -> 100 %
LOOP_INTERVAL = 1.0      # seconds
TSL2561_ADDR = 0x39      # default TSL2561 I2C address

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_i2c = None
_pwm = None
_running = True


def _cleanup() -> None:
    """Release all hardware resources."""
    global _pwm, _i2c
    if _pwm is not None:
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_i2c() -> busio.I2C:
    """Initialize the I2C bus; raise on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize I2C bus: {exc}") from exc


def _init_sensor(i2c: busio.I2C) -> adafruit_tsl2561.TSL2561:
    """Initialize the TSL2561; raise on failure."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c, address=TSL2561_ADDR)
        sensor.gain = adafruit_tsl2561.Gain.AUTO
        sensor.integration_time = adafruit_tsl2561.IntegrationTime.INTEGRATION_TIME_402MS
        return sensor
    except ValueError as exc:
        raise RuntimeError(
            f"TSL2561 not found at 0x{TSL2561_ADDR:02X} on I2C bus: {exc}"
        ) from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize TSL2561: {exc}") from exc


def _init_pwm(pin: int) -> GPIO.PWM:
    """Initialize PWM on the given GPIO pin; raise on failure."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT)
        pwm = GPIO.PWM(pin, PWM_FREQ)
        pwm.start(0)
        return pwm
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize PWM on GPIO {pin}: {exc}") from exc


def _read_lux(sensor: adafruit_tsl2561.TSL2561) -> float:
    """Read lux from the sensor; raise on I2C error."""
    try:
        return sensor.lux
    except (OSError, ValueError) as exc:
        raise RuntimeError(f"Failed to read lux from TSL2561: {exc}") from exc


def _brightness_for_lux(lux: float) -> float:
    """Map lux to a 0-100 % brightness value."""
    if lux <= LUX_MIN:
        return 0.0
    if lux >= LUX_MAX:
        return 100.0
    return (lux / LUX_MAX) * 100.0


def main() -> int:
    global _i2c, _pwm

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _i2c = _init_i2c()
    except RuntimeError as exc:
        print(f"Fatal: {exc}", file=sys.stderr)
        return 1

    try:
        _pwm = _init_pwm(LED_PIN)
    except RuntimeError as exc:
        print(f"Fatal: {exc}", file=sys.stderr)
        _cleanup()
        return 1

    try:
        sensor = _init_sensor(_i2c)
    except RuntimeError as exc:
        print(f"Fatal: {exc}", file=sys.stderr)
        _cleanup()
        return 1

    print("TSL2561 light-to-LED controller started. Press Ctrl+C to exit.")

    try:
        while _running:
            try:
                lux = _read_lux(sensor)
            except RuntimeError as exc:
                print(f"Warning: {exc}", file=sys.stderr)
                time.sleep(LOOP_INTERVAL)
                continue

            try:
                brightness = _brightness_for_lux(lux)
            except RuntimeError as exc:
                print(f"Warning: {exc}", file=sys.stderr)
                time.sleep(LOOP_INTERVAL)
                continue

            try:
                _pwm.ChangeDutyCycle(brightness)
            except Exception as exc:
                print(f"Warning: failed to update PWM duty cycle: {exc}", file=sys.stderr)

            print(f"Lux: {lux:.2f}  Brightness: {brightness:.1f}%")

            time.sleep(LOOP_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        _cleanup()

    return 0


if __name__ == "__main__":
    sys.exit(main())

