#!/usr/bin/env python3
"""Flask web server controlling an LED on GPIO 17 (BCM) via gpiozero."""

import signal
import sys
from flask import Flask, render_template_string

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

app = Flask(__name__)

# Module-level LED instance so it persists across requests
led = None

HTML_PAGE = """
<!DOCTYPE html>
<html>
<head><title>LED Control</title></head>
<body>
<h1>LED Control</h1>
<p>Turn the LED on: <a href="/light_on">ON</a></p>
<p>Turn the LED off: <a href="/light_off">OFF</a></p>
</body>
</html>
"""

ON_MSG = "ON"
OFF_MSG = "OFF"


def init_led():
    """Initialize the LED on GPIO 17. Returns the LED object or None on failure."""
    try:
        return LED(17)
    except (BadPinFactory, GPIOZeroError) as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected GPIO init error: {e}", file=sys.stderr)
        return None


@app.route("/")
def index():
    """Index page with ON/OFF links."""
    return render_template_string(HTML_PAGE)


@app.route("/light_on")
def light_on():
    """Turn the LED on."""
    if led is None:
        return render_template_string(HTML_PAGE), 500
    try:
        led.on()
    except Exception as e:
        return render_template_string(
            f"""<h1>Error: Could not turn LED on</h1>
<p>{e}</p>
<a href=\"{index()}\">Back</a>
""".strip(), 500)
    return f"<h1>LED is ON</h1><a href=\"{index()}\">Back</a>"


@app.route("/light_off")
def light_off():
    """Turn the LED off."""
    if led is None:
        return render_template_string(HTML_PAGE), 500
    try:
        led.off()
    except Exception as e:
        return render_template_string(
            f"""<h1>Error: Could not turn LED off</h1>
<p>{e}</p>
<a href=\"{index()}\">Back</a>
""".strip(), 500)
    return f"<h1>LED is OFF</h1><a href=\"{index()}\">Back</a>"


def cleanup(signum=None, frame=None):
    """Release GPIO resources and exit."""
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    led = init_led()
    try:
        app.run(host="0.0.0.0", port=8080, debug=False)
    finally:
        cleanup()

