            raise ValueError("Pin must be a non-negative integer (BCM numbering)")
        if len(value_list) != 2:
            raise ValueError("value_list must contain exactly two values")
        if initial_value not in value_list:
            raise ValueError("initial_value must be one of the values in value_list")

        self.pin = pin
        self.value_list = value_list
        self.current_value = initial_value
        self.pi = None

        try:
            self.pi = pigpio.pi()
            if not self.pi.connected:
                raise RuntimeError("Failed to connect to pigpio daemon. Is pigpiod running?")

            self.pi.set_mode(self.pin, pigpio.OUTPUT)
            self.pi.write(self.pin, self.current_value)
            print(f"OutputPin initialized on GPIO {self.pin} with initial value {self.current_value}")
        except Exception as e:
            self.cleanup()
            raise RuntimeError(f"Error initializing OutputPin: {e}") from e

    def set_value(self, value):
        if value not in self.value_list:
            raise ValueError(f"Invalid value {value}. Must be one of {self.value_list}")
        try:
            self.pi.write(self.pin, value)
            self.current_value = value
            print(f"GPIO {self.pin} set to {value}")
        except Exception as e:
            raise RuntimeError(f"Error setting value on GPIO {self.pin}: {e}") from e

    def shutdown(self):
        if self.pi is not None and self.pi.connected:
            try:
                self.pi.write(self.pin, 0)  # Ensure pin is low (input mode)
                self.pi.set_mode(self.pin, pigpio.INPUT)
                print(f"GPIO {self.pin} shutdown: set to input mode")
            except Exception as e:
                print(f"Warning: Error during GPIO shutdown: {e}")
            finally:
                self.pi = None

    def cleanup(self):
        self.shutdown()


class TriggerPin(OutputPin):
    """
    Represents a GPIO pin capable of generating a short pulse.
    Uses pigpio hardware PWM for precise timing control.
    """

    def __init__(self, pin, pulse_duration=100, pulse_high=True, value_list=(0, 1), initial_value=0):
        if not isinstance(pin, int) or pin < 0:
            raise ValueError("Pin must be a non-negative integer (BCM numbering)")
        if not isinstance(pulse_duration, (int, float)) or pulse_duration <= 0:
            raise ValueError("pulse_duration must be a positive number")
        if not isinstance(pulse_high, bool):
            raise ValueError("pulse_high must be a boolean")
        if len(value_list) != 2:
            raise ValueError("value_list must contain exactly two values")
        if initial_value not in value_list:
            raise ValueError("initial_value must be one of the values in value_list")

        super().__init__(pin, value_list, initial_value)
        self.pulse_duration = pulse_duration
        self.pulse_high = pulse_high
        self.last_pulse_time = 0.0
        self.lock = threading.Lock()
        self.active_state = 1 if self.pulse_high else 0

    def trigger(self):
        with self.lock:
            current_time = time.time()
            if current_time - self.last_pulse_time >= self.pulse_duration:
                self.last_pulse_time = current_time
                self.pi.hardware_PWM(self.pin, 1000000, self.active_state)
                print(f"GPIO {self.pin} triggered for {self.pulse_duration} us")
            else:
                print(f"GPIO {self.pin} not triggered (still in pulse window)")

    def shutdown(self):
        with self.lock:
            super().shutdown()


def signal_handler(sig, frame):
    print("\nInterrupt received, shutting down...")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)

