        except GPIOZeroError as e:
            self.logger.error(f"GPIO initialization failed: {e}")
            raise
        except Exception as e:
            self.logger.error(f"Unexpected GPIO error: {e}")
            raise

    def _subscribe_to_messages(self):
        """Subscribe to incoming ZMQ messages."""
        self.zmq_sub_sock.setsockopt_string(zmq.SUBSCRIBE, self.config['subscriptions'])
        self.zmq_sub_sock.start_pull()
        self.logger.info("Subscribed to ZMQ topics: %s", self.config['subscriptions'])

    def handle_message(self):
        """Handle incoming ZMQ messages in a non-blocking manner."""
        try:
            message = self.zmq_sub_sock.recv_string(flags=zmq.NOBLOCK)
            if message:
                self.logger.debug(f"Received message: {message}")
                self.process_subscription(message)
        except zmq.Again:
            pass
        except zmq.ZMQError as e:
            self.logger.error(f"ZMQ error handling message: {e}")
        except Exception as e:
            self.logger.error(f"Unexpected error handling message: {e}")

    def update_error_output(self):
        """Update the error output based on the global error state."""
        if self.error_output is None:
            return
        try:
            if self.global_err_state:
                if self.pwm:
                    self.error_output.frequency = 1000
                    self.error_output.value = 1.0
                else:
