import sys
import signal

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

# Constants
FAN_PIN = 12          # BCM GPIO12 (physical pin 32)
PWM_FREQUENCY = 25000  # 25 kHz standard for 4-wire PWM fans

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _create_pwm():
    """Create a PWMOutputDevice, falling back to software PWM if hardware is unavailable."""
    try:
        # gpiozero prefers hardware PWM on GPIO12, but we allow software fallback.
        # If hardware PWM is unavailable (e.g., mocked/emulated environment),
        # gpiozero will raise an exception; we catch it here and return a
        # software-compatible PWMOutputDevice.
        return PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0.0)
    except Exception as e:
        # If hardware PWM is not available, return a software PWM device.
        # This allows the program to run in environments where GPIO is mocked.
        print(f"Warning: Hardware PWM unavailable on GPIO{FAN_PIN}: {e}. "
              f"Falling back to software PWM.")
        return PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0.0)


def main():
    """Main function to control the fan speed."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    fan = None
    try:
        fan = _create_pwm()
        fan.value = 0.0  # Start with 0% duty cycle (fan off)

        while _running:
            try:
                user_input = input("Enter fan speed (0-100): ")
                fan_speed = float(user_input)

                # Clamp the speed to the valid range
                if 0 <= fan_speed <= 100:
                    fan.value = fan_speed / 100.0
                    print(f"Fan speed set to {fan_speed:.1f}%")
                else:
                    print("Invalid input. Please enter a number between 0 and 100.")

            except ValueError:
                print("Invalid input. Please enter a number.")
            except EOFError:
                # Handle Ctrl+D (end of input)
                print("\nEOF received. Exiting...")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
                break

    except GPIOZeroError as e:
        print(f"GPIO error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean resource release on all exit paths
        if fan is not None:
            try:
                fan.value = 0.0  # Ensure fan is off
                fan.close()       # Release the GPIO pin
            except DeviceClosed:
                pass  # Device was already closed
            except Exception as e:
                print(f"Error during cleanup: {e}")
        print("GPIO cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

