import signal
import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 library not installed. Install with: pip install smbus2")
    sys.exit(1)

I2C_BUS = 1
I2C_ADDR = 0x23
POWER_ON = 0x01
CONTINUOUS_HIGH_RES = 0x10
READ_DELAY = 1.0

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def init_sensor(bus):
    try:
        bus.write_byte(I2C_ADDR, POWER_ON)
        bus.write_byte(I2C_ADDR, CONTINUOUS_HIGH_RES)
        time.sleep(0.1)
        return True
    except OSError as e:
        print(f"Error initializing BH1750 at 0x{I2C_ADDR:02X}: {e}")
        return False

def read_lux(bus):
    try:
        data = bus.read_i2c_block_data(I2C_ADDR, CONTINUOUS_HIGH_RES, 2)
        raw = (data[0] << 8) | data[1]
        return raw / 1.2
    except OSError as e:
        print(f"I2C read error (sensor may be absent or bus faulty): {e}")
        return None

def main():
    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error opening I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    if not init_sensor(bus):
        bus.close()
        sys.exit(1)

    print("BH1750 light sensor initialized. Reading lux every 1 second. Press Ctrl+C to stop.")

    try:
        while _running:
            lux = read_lux(bus)
            if lux is not None:
                print(f"Ambient Lux: {lux:.2f}")
            time.sleep(READ_DELAY)
    finally:
        bus.close()
        print("\nI2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

