import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
BH1750_ADDR = 0x23
BH1750_ONE_TIME_HI_RES_1 = 0x20
CONVERSION_TIME_S = 0.12
READ_INTERVAL_S = 3.0

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def _write_cmd(bus, cmd):
    bus.write_byte(BH1750_ADDR, cmd)


def _read_raw(bus):
    msg = i2c_msg.read(BH1750_ADDR, 2)
    bus.i2c_rdwr(msg)
    return list(msg)


def _to_lux(raw):
    return round(raw / 1.2, 2)


def read_bh1750(bus):
    try:
        _write_cmd(bus, BH1750_ONE_TIME_HI_RES_1)
        time.sleep(CONVERSION_TIME_S)
        raw = _read_raw(bus)
        return _to_lux(raw[0] << 8 | raw[1])
    except OSError as exc:
        raise RuntimeError(f"I2C communication error: {exc}") from exc


def main():
    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                lux = read_bh1750(bus)
                print(f"Ambient Illuminance: {lux} lux")
            except RuntimeError as exc:
                print(f"Error: {exc}", file=sys.stderr)
            except OSError as exc:
                print(f"Error: I2C bus error: {exc}", file=sys.stderr)

            for _ in range(int(READ_INTERVAL_S * 10)):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        bus.close()
        print("\nI2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

