#!/usr/bin/env python3
"""Rainbow HAT 3-bit binary counter.

Touchpads A (GPIO5), B (GPIO6), C (GPIO12) toggle bits 4, 2, 1 respectively.
Red LED (GPIO7), Blue LED (GPIO8), Green LED (GPIO13) reflect bit states.
HT16K33 14-seg display at 0x70 shows decimal value (0-7).
APA102 strip (data=GPIO10, clock=GPIO11) shows dim white 0, all white 7,
or a single pixel at the decimal value with color derived from touchpads.
Piezo buzzer (GPIO13) plays MIDI note 60 + decimal value.
"""

import signal
import sys
import time

import board
import busio
from adafruit_ht16k33.segments import Seg14x7
from adafruit_apa102.strip import APA102
from adafruit_dotstar import DotStar
from gpiozero import Button, LED, Buzzer

# ---------------------------------------------------------------------------
# Pin / display / buzzer setup
# ---------------------------------------------------------------------------
TOUCH_PINS = {"A": 5, "B": 6, "C": 12}

# HT16K33 14-seg display
HT16K33_ADDR = 0x70
HT16K33_WIDTH = 14

# APA102 strip (data=GPIO10, clock=GPIO11)
APA102_DATA_PIN = 10
APA102_CLOCK_PIN = 11
NUM_PIXELS = 7

# Buzzer on GPIO13, MIDI note 60
BUZZER_PIN = 13

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_strip = None
_display = None
_buzzer = None
_buttons = {}
_leds = {}
_running = True


def _cleanup():
    """Turn off all outputs and release resources."""
    global _strip, _display, _buzzer, _buttons, _leds
    for led in _leds.values():
        try:
            led.off()
        except Exception:
            pass
    for btn in _buttons.values():
        try:
            btn.close()
        except Exception:
            pass
    for led in _leds.values():
        try:
            led.close()
        except Exception:
            pass
    if _display is not None:
        try:
            _display.fill(0)
            _display.show()
        except Exception:
            pass
    if _buzzer is not None:
        try:
            _buzzer.close()
        except Exception:
            pass


def _signal_handler(signum, frame):
    global _running
    _running = False


# ---------------------------------------------------------------------------
# HT16K33 14-seg display
# ---------------------------------------------------------------------------
class Display:
    def __init__(self, addr=0x70):
        self.addr = addr
        self.width = HT16K33_WIDTH
        self.segments = []
        self.backlight = False
        self._init_display()

    def _init_display(self):
        try:
            i2c = busio.I2C(board.SCL, board.SDA)
            self.segments = Seg14x7(i2c, addr=self.addr, segments=self.width,
                                  backlight=self.backlight)
            self.segments.fill(0)
            self.segments.show()
        except Exception as e:
            print(f"Error initializing HT16K33 at 0x{self.addr:02X}: {e}",
                  file=sys.stderr)
            self.segments = None

    def display_value(self, value):
        if self.segments is None:
            return
        try:
            self.segments.print(value)
            self.segments.show()
        except Exception as e:
            print(f"Error displaying value {value}: {e}", file=sys.stderr)

    def clear(self):
        if self.segments is None:
            return
        try:
            self.segments.fill(0)
            self.segments.show()
        except Exception as e:
            print(f"Error clearing display: {e}", file=sys.stderr)


# ---------------------------------------------------------------------------
# APA102 LED strip
# ---------------------------------------------------------------------------
class LedStrip:
    def __init__(self, data_pin=APA102_DATA_PIN, clock_pin=APA102_CLOCK_PIN,
                 num_pixels=NUM_PIXELS):
        self.data_pin = data_pin
        self.clock_pin = clock_pin
        self.num_pixels = num_pixels
        self.strip = None
        self._init_strip()

    def _init_strip(self):
        try:
            self.strip = APA102(
                self.num_pixels, self.data_pin, self.clock_pin,
                brightness=0.5, initial_value=0)
            self.strip.fill(0)
            self.strip.show()
        except Exception as e:
            print(f"Error initializing APA102 strip: {e}", file=sys.stderr)
            self.strip = None

    def show_pixel(self, index, color):
        if self.strip is None:
            return
        try:
            self.strip.setPixelColor(index, color)
            self.strip.show()
        except Exception as e:
            print(f"Error setting pixel {index}: {e}", file=sys.stderr)

    def show_all(self):
        if self.strip is None:
            return
        try:
            for i in range(self.num_pixels):
                self.strip.setPixelColor(i, 0)
            self.strip.show()
        except Exception as e:
            print(f"Error showing all pixels: {e}", file=sys.stderr)

    def clear(self):
        if self.strip is None:
            return
        try:
            self.strip.fill(0)
            self.strip.show()
        except Exception as e:
            print(f"Error clearing APA102 strip: {e}", file=sys.stderr)


# ---------------------------------------------------------------------------
# Buzzer
# ---------------------------------------------------------------------------
class Buzzer:
    def __init__(self, pin=BUZZER_PIN):
        self.pin = pin
        self.buzzer = None
        self._init_buzzer()

    def _init_buzzer(self):
        try:
            self.buzzer = Buzzer(self.pin)
            self.buzzer.volume = 0.5
        except Exception as e:
            print(f"Error initializing buzzer on GPIO{self.pin}: {e}",
                  file=sys.stderr)
            self.buzzer = None

    def play_tone(self, frequency, duration=0.5):
        if self.buzzer is None:
            return
        try:
            self.buzzer.play(frequency)
            time.sleep(duration)
            self.buzzer.stop()
        except Exception as e:
            print(f"Error playing tone at {frequency} Hz: {e}", file=sys.stderr)


# ---------------------------------------------------------------------------
# Touch buttons
# ---------------------------------------------------------------------------
class TouchButtons:
    def __init__(self):
        self.buttons = {}
        for name, pin in TOUCH_PINS.items():
            try:
                btn = Button(pin, pull_up=False)
                btn.when_pressed = self._on_touch
                self.buttons[name] = btn
            except Exception as e:
                print(f"Error initializing touchpad {name} on GPIO{pin}: {e}",
                      file=sys.stderr)
                self.buttons[name] = None

    def _on_touch(self):
        for name, btn in self.buttons.items():
            if btn is not None:
                btn.close()
                self.buttons[name] = None
        self._update_bit_states()

    def _update_bit_states(self):
        states = [False] * 8
        for name, btn in self.buttons.items():
            if btn is not None:
                states[TOUCH_PINS[name]] = not states[TOUCH_PINS[name]]
                btn.close()
                self.buttons[name] = None
        self.bit_states = states


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    global _strip, _display, _buzzer, _buttons, _leds

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _display = Display(HT16K33_ADDR)
        _strip = LedStrip()
        _buzzer = Buzzer()
        _buttons = TouchButtons()
        _leds = {
            "red": LED(7),
            "green": LED(8),
            "blue": LED(13),
        }
    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    value = 0
    try:
        while _running:
            if all(btn is not None for btn in _buttons.values()):
                value = sum(2 * (btn.is_pressed if btn.is_pressed else 0)
                           for btn in _buttons.values())
            if _strip is not None:
                _strip.clear()
                if value == 0:
                    _strip.show_pixel(0, 0)
                elif value == 7:
                    _strip.show_all()
                else:
                    _strip.show_pixel(value, _strip.get_color(value, _leds))
            if _display is not None:
                _display.display_value(value)
            if _buzzer is not None:
                _buzzer.play_tone(60 + value)
            time.sleep(0.05)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

