        except Exception as e:
            print(f"Error showing all pixels: {e}", file=sys.stderr)

    def clear(self):
        if self.strip is None:
            return
        try:
            self.strip.fill(0)
            self.strip.show()
        except Exception as e:
            print(f"Error clearing APA102 strip: {e}", file=sys.stderr)


# ---------------------------------------------------------------------------
# Buzzer
# ---------------------------------------------------------------------------
class Buzzer:
    def __init__(self, pin=BUZZER_PIN):
        self.pin = pin
        self.buzzer = None
        self._init_buzzer()

    def _init_buzzer(self):
        try:
            self.buzzer = Buzzer(self.pin)
            self.buzzer.volume = 0.5
        except Exception as e:
            print(f"Error initializing buzzer on GPIO{self.pin}: {e}",
                  file=sys.stderr)
            self.buzzer = None

    def play_tone(self, frequency, duration=0.5):
        if self.buzzer is None:
            return
        try:
            self.buzzer.play(frequency)
            time.sleep(duration)
            self.buzzer.stop()
        except Exception as e:
            print(f"Error playing tone at {frequency} Hz: {e}", file=sys.stderr)


# ---------------------------------------------------------------------------
# Touch buttons
# ---------------------------------------------------------------------------
class TouchButtons:
    def __init__(self):
        self.buttons = {}
        for name, pin in TOUCH_PINS.items():
            try:
                btn = Button(pin, pull_up=False)
                btn.when_pressed = self._on_touch
                self.buttons[name] = btn
            except Exception as e:
                print(f"Error initializing touchpad {name} on GPIO{pin}: {e}",
                      file=sys.stderr)
                self.buttons[name] = None

    def _on_touch(self):
        for name, btn in self.buttons.items():
            if btn is not None:
                btn.close()
                self.buttons[name] = None
        self._update_bit_states()

    def _update_bit_states(self):
        states = [False] * 8
        for name, btn in self.buttons.items():
            if btn is not None:
                states[TOUCH_PINS[name]] = not states[TOUCH_PINS[name]]
                btn.close()
                self.buttons[name] = None
        self.bit_states = states


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    global _strip, _display, _buzzer, _buttons, _leds

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _display = Display(HT16K33_ADDR)
        _strip = LedStrip()
        _buzzer = Buzzer()
        _buttons = TouchButtons()
        _leds = {
            "red": LED(7),
            "green": LED(8),
            "blue": LED(13),
        }
    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    value = 0
    try:
        while _running:
            if all(btn is not None for btn in _buttons.values()):
                value = sum(2 * (btn.is_pressed if btn.is_pressed else 0)
                           for btn in _buttons.values())
            if _strip is not None:
                _strip.clear()
                if value == 0:
                    _strip.show_pixel(0, 0)
                elif value == 7:
                    _strip.show_all()
                else:
                    _strip.show_pixel(value, _strip.get_color(value, _leds))
            if _display is not None:
                _display.display_value(value)
            if _buzzer is not None:
                _buzzer.play_tone(60 + value)
            time.sleep(0.05)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

