import json
import random
import sys

# Simulated audio energy levels (0-9)
SIMULATED_ENERGY_LEVELS = [random.randint(0, 9) for _ in range(6)]

# Keyword mapping: energy modulo 3 -> command keyword
KEYWORD_MAP = {
    0: "water",
    1: "stop",
    2: "status",
}

# Action mapping: keyword -> farm action
ACTION_MAP = {
    "water": "open_valve",
    "stop": "close_valve",
    "status": "report",
}

def transcribe_frame(energy_level: int) -> str:
    """Map a simulated audio energy level to a voice recognition keyword."""
    return KEYWORD_MAP.get(energy_level % 3, "unknown")

def execute_action(keyword: str) -> str:
    """Map a keyword to a farm action."""
    return ACTION_MAP.get(keyword, "no_action")

def save_actions(actions_list: list) -> None:
    """Save the list of chosen farm actions to a JSON file."""
    try:
        with open("voice_actions.json", "w") as f:
            json.dump(actions_list, f, indent=4)
    except IOError as e:
        print(f"Error saving actions to file: {e}", file=sys.stderr)

def main() -> None:
    """Run the voice recognition simulation and save the chosen actions."""
    chosen_actions = []
    try:
        for i, energy in enumerate(SIMULATED_ENERGY_LEVELS):
            keyword = transcribe_frame(energy)
            action = execute_action(keyword)
            chosen_actions.append(action)
            print(f"Frame {i}: Energy={energy} -> Keyword={keyword} -> Action={action}")

        save_actions(chosen_actions)
        print("Voice recognition simulation complete.")

    except Exception as e:
        print(f"An error occurred during the simulation: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

