#!/usr/bin/env python3
"""
Simple predictive maintenance demo for urban monitoring.
Uses an SW-420 digital vibration sensor (active-low) on GPIO17.
Reads every 0.3 s for 6 samples, simulates amplitude, and tracks running average.
"""

import time
import random
import sys

try:
    from gpiozero import DigitalInputDevice, Device
    from gpiozero.pins.mock import MockFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

# Configuration
SENSOR_PIN = 17          # BCM GPIO17 (physical pin 11)
READ_INTERVAL = 0.3      # seconds between readings
NUM_SAMPLES = 6
THRESHOLD = 7.5          # running average threshold

# Global state
sensor = None
amplitudes = []

def read_sensor():
    """Read the digital vibration sensor.
    Returns True when vibration is detected (LOW), False when idle (HIGH).
    """
    try:
        # gpiozero DigitalInputDevice with pull_up=True enables internal pull-up
        # and reads the active-low signal.
        return sensor.value == 0
    except Exception as e:
        print(f"Sensor read error: {e}")
        return False

def simulate_amplitude():
    """Simulate vibration amplitude based on sensor state."""
    if read_sensor():
        return random.uniform(6.0, 9.0)
    else:
        return random.uniform(3.0, 5.0)

def main():
    global sensor, amplitudes

    # Initialize sensor with pull-up and error handling
    try:
        sensor = DigitalInputDevice(SENSOR_PIN, pull_up=True, bounce_time=0.05)
        print(f"Sensor initialized on GPIO{SENSOR_PIN} (pull-up enabled)")
    except Exception as e:
        print(f"Failed to initialize sensor: {e}")
        sys.exit(1)

    # Main loop
    try:
        for i in range(NUM_SAMPLES):
            amplitude = simulate_amplitude()
            amplitudes.append(amplitude)
            print(f"Sample {i+1}: amplitude = {amplitude:.2f}")

            if len(amplitudes) > 1:
                avg_amp = sum(amplitudes) / len(amplitudes)
                print(f"Running average: {avg_amp:.2f}")

            if avg_amp > THRESHOLD:
                print("Maintenance recommended: wear trend is high")
            else:
                print("Component healthy: no action needed")

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nInterrupted by user")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Clean up resources
        if sensor is not None:
            sensor.close()
            print("GPIO resources released")

if __name__ == "__main__":
    main()

