import signal
import sys
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

LED_PIN_1 = 18
LED_PIN_2 = 23

led1 = None
led2 = None
running = True

def cleanup():
    """Turn off and close the LED resources."""
    global led1, led2
    if led1 is not None:
        try:
            led1.off()
            led1.close()
        except Exception:
            pass
    if led2 is not None:
        try:
            led2.off()
            led2.close()
        except Exception:
            pass

def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    running = False

def turn_on_both_leds():
    """Turn on both LEDs."""
    global led1, led2
    if led1 is None or led2 is None:
        raise RuntimeError("LEDs not initialized")
    led1.on()
    led2.on()

def turn_off_both_leds():
    """Turn off both LEDs."""
    global led1, led2
    if led1 is None or led2 is None:
        raise RuntimeError("LEDs not initialized")
    led1.off()
    led2.off()

def toggle_leds(cycle_count=5):
    """Toggle both LEDs on and off for a specified number of cycles."""
    global led1, led2
    if led1 is None or led2 is None:
        raise RuntimeError("LEDs not initialized")

    for i in range(cycle_count):
        if not running:
            break
        turn_on_both_leds()
        time.sleep(1)
        if not running:
            break
        turn_off_both_leds()
        time.sleep(1)

def main():
    """Main function to demonstrate LED control."""
    global led1, led2

    try:
        led1 = LED(LED_PIN_1)
        led2 = LED(LED_PIN_2)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO init: {e}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, signal_handler)

    try:
        toggle_leds(cycle_count=5)
    except Exception as e:
        print(f"Error during LED toggle: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

