try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

PUMP_PIN = 17
DRY_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_soil_moisture():
    return random.randint(0, 100)

def control_pump(pump, moisture_level):
    if moisture_level < DRY_THRESHOLD:
        pump.on()
        print(f"Soil moisture {moisture_level}% below threshold {DRY_THRESHOLD} -> pump ON")
    else:
        pump.off()
        print(f"Soil moisture {moisture_level}% adequate -> pump OFF")

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pump = None
    try:
        pump = OutputDevice(PUMP_PIN)
        print(f"GPIO {PUMP_PIN} configured as output for water pump control.")
        for i in range(ITERATIONS):
            if not _running:
                break
            moisture = read_soil_moisture()
            print(f"Iteration {i + 1}/{ITERATIONS}: Soil moisture = {moisture}%")
            control_pump(pump, moisture)
            if i < ITERATIONS - 1 and _running:
                time.sleep(DELAY_SECONDS)
    except GPIOZeroError as e:
        print(f"GPIO error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if pump is not None:
            try:
                pump.off()
                pump.close()
                print("Pump turned off and GPIO released.")
            except DeviceClosed:
                pass
            except Exception as e:
                print(f"Error during cleanup: {e}")
        print("Program finished.")

if __name__ == "__main__":
    main()

