import signal
import sys
import time
import sqlite3
import random
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# Configuration
PUMP_RELAY_PIN = 17
LIGHT_RELAY_PIN = 18
PUMP_DURATION = 10.0
SENSOR_INTERVAL = 60.0

# Global resources for cleanup
pump_relay = None
light_relay = None
db_conn = None
running = True

def signal_handler(signum, frame):
    global running
    print(f"\nReceived signal {signum}, shutting down...")
    running = False

def init_database():
    global db_conn
    try:
        db_conn = sqlite3.connect('hydroponics.db')
        cursor = db_conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                temperature REAL,
                humidity REAL,
                light_level REAL
            )
        ''')
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS system_events (
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                event_type TEXT,
                description TEXT
            )
        ''')
        db_conn.commit()
        print("Database initialized successfully.")
    except sqlite3.Error as e:
        print(f"Database initialization error: {e}")
        sys.exit(1)

def log_sensor_data(temperature, humidity, light_level):
    try:
        cursor = db_conn.cursor()
        cursor.execute(
            "INSERT INTO sensor_data (temperature, humidity, light_level) VALUES (?, ?, ?)",
            (temperature, humidity, light_level)
        )
        db_conn.commit()
    except sqlite3.Error as e:
        print(f"Error logging sensor data: {e}")

def log_system_event(event_type, description):
    try:
        cursor = db_conn.cursor()
        cursor.execute(
            "INSERT INTO system_events (event_type, description) VALUES (?, ?)",
            (event_type, description)
        )
        db_conn.commit()
    except sqlite3.Error as e:
        print(f"Error logging system event: {e}")

def read_simulated_sensor_data():
    temperature = random.uniform(15.0, 30.0)
    humidity = random.uniform(40.0, 80.0)
    light_level = random.uniform(0.0, 1000.0)
    return temperature, humidity, light_level

def control_pump(duration):
    global running
    if not running:
        return
    try:
        print("Activating pump for:", duration, "seconds...")
        pump_relay.on()
        time.sleep(duration)
        pump_relay.off()
        print("Pump deactivated.")
    except GPIOZeroError as e:
        print(f"GPIO error controlling pump: {e}")
    except Exception as e:
        print(f"Unexpected error controlling pump: {e}")

def control_light(on):
    global running
    if not running:
        return
    try:
        if on:
            light_relay.on()
            print("Turning light ON")
            log_system_event("light_on", "Light turned ON")
        else:
            light_relay.off()
            print("Turning light OFF")
            log_system_event("light_off", "Light turned OFF")
    except GPIOZeroError as e:
        print(f"GPIO error controlling light: {e}")
    except Exception as e:
        print(f"Unexpected error controlling light: {e}")

def cleanup():
    global pump_relay, light_relay, db_conn
    print("Cleaning up resources...")
    if pump_relay is not None:
        try:
            pump_relay.off()
            pump_relay.close()
        except Exception as e:
            print(f"Error closing pump relay: {e}")
    if light_relay is not None:
        try:
            light_relay.off()
            light_relay.close()
        except Exception as e:
            print(f"Error closing light relay: {e}")
    if db_conn is not None:
        try:
            db_conn.close()
        except Exception as e:
            print(f"Error closing database connection: {e}")
    print("Cleanup complete.")

def main():
    global pump_relay, light_relay, running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        pump_relay = OutputDevice(PUMP_RELAY_PIN, initial_value=False)
        light_relay = OutputDevice(LIGHT_RELAY_PIN, initial_value=False)
        print("GPIO initialized successfully.")
    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}")
        sys.exit(1)

    init_database()

    try:
        while running:
            temperature, humidity, light_level = read_simulated_sensor_data()
            log_sensor_data(temperature, humidity, light_level)
            print(f"Temperature: {temperature:.2f}C, Humidity: {humidity:.2f}%, Light: {light_level:.2f}")

            if temperature > 30.0:
                print("Temperature too high!")
                control_pump(PUMP_DURATION)
            elif humidity < 30.0:
                print("Humidity too low!")
                control_pump(PUMP_DURATION)
            elif light_level < 200.0:
                print("Light level too low!")
                control_light(True)
            elif light_level > 800.0:
                print("Light level too high!")
                control_light(False)
            else:
                print("System operating normally.")

            for _ in range(SENSOR_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

