import time
import datetime
import sys

# Configuration
PIR_PIN = 4
FEEDING_START_HOUR = 7
FEEDING_END_HOUR = 8
FEEDING_COOLDOWN_SECONDS = 60
POLL_INTERVAL_SECONDS = 1

def setup_gpio():
    """Initialize GPIO with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def is_feeding_time(now):
    """Return True if current time is within feeding hours (24-hour format)."""
    return FEEDING_START_HOUR <= now.hour < FEEDING_END_HOUR

def log_motion(message):
    """Log a motion event with timestamp."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"Motion detected at {timestamp}")
    print(message)

def main():
    setup_gpio()
    last_feeding_time = None
    try:
        while True:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"Error reading GPIO pin: {e}", file=sys.stderr)
                time.sleep(POLL_INTERVAL_SECONDS)
                continue

            if motion_detected:
                now = datetime.datetime.now()
                if is_feeding_time(now):
                    if last_feeding_time is None or (now - last_feeding_time).total_seconds() >= FEEDING_COOLDOWN_SECONDS:
                        log_motion("Feeding initiated at " + now.strftime("%H:%M:%S"))
                        last_feeding_time = now
                        time.sleep(60)  # Debounce cooldown
                    else:
                        log_motion("Not feeding time or recently fed.")
                else:
                    log_motion("Not feeding time or recently fed.")

            time.sleep(POLL_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

