import RPi.GPIO as GPIO
import time
import sys

# GPIO pin assignments (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
LEFT_MOTOR_PIN = 16
RIGHT_MOTOR_PIN = 26

def setup_gpio():
    """Initialize GPIO pins with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(LEFT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(RIGHT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def read_sensors():
    """Read both reflectance sensors. Returns (left_state, right_state)."""
    try:
        left_state = GPIO.input(LEFT_SENSOR_PIN)
        right_state = GPIO.input(RIGHT_SENSOR_PIN)
        return left_state, right_state
    except Exception as e:
        print(f"Sensor read error: {e}", file=sys.stderr)
        return None, None

def control_motors(left_state, right_state):
    """Control motors based on sensor states. Returns motor_state tuple."""
    try:
        if left_state is None or right_state is None:
            return GPIO.LOW, GPIO.LOW
        if left_state == GPIO.HIGH:
            if right_state == GPIO.LOW:
                GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH)
                GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
                return GPIO.HIGH, GPIO.LOW
            else:
                GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
                GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
                return GPIO.LOW, GPIO.LOW
        elif right_state == GPIO.HIGH:
            if left_state == GPIO.LOW:
                GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
                GPIO.output(RIGHT_MOTOR_PIN, GPIO.HIGH)
                return GPIO.LOW, GPIO.HIGH
            else:
                GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH)
                GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
                return GPIO.HIGH, GPIO.LOW
        else:
            GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
            GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
            return GPIO.LOW, GPIO.LOW
    except Exception as e:
        print(f"Motor control error: {e}", file=sys.stderr)
        return GPIO.LOW, GPIO.LOW

def main():
    setup_gpio()
    try:
        for iteration in range(20):
            left_state, right_state = read_sensors()
            if left_state is not None and right_state is not None:
                motor_state = control_motors(left_state, right_state)
                print(f"Iteration {iteration+1}: left={left_state}, right={right_state}, motors={motor_state}")
            else:
                print(f"Iteration {iteration+1}: sensor error, stopping motors")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nLine following stopped by user")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up")

if __name__ == "__main__":
    main()

