import signal
import sys
from gpiozero import PWMOutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17
PWM_FREQUENCY = 50  # Hz
HOLD_TIME = 1.0  # seconds

servo_pwm = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def move_servo(angle):
    global servo_pwm
    if servo_pwm is None:
        print("Error: Servo PWM not initialized.")
        return
    if not isinstance(angle, (int, float)):
        print("Error: Angle must be a number.")
        return
    if not 0 <= angle <= 180:
        print("Error: Angle must be between 0 and 180.")
        return
    duty_cycle = angle / 18.0 + 2.0
    try:
        servo_pwm.value = duty_cycle / 100.0
        time.sleep(HOLD_TIME)
        servo_pwm.value = 0.0
        print(f"Servo moved to {angle} degrees.")
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
    except Exception as e:
        print(f"Unexpected error during servo move: {e}")

def main():
    global servo_pwm
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        servo_pwm = PWMOutputDevice(SERVO_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        print(f"Failed to initialize servo PWM on GPIO {SERVO_PIN}: {e}")
        sys.exit(1)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
        if servo_pwm:
            servo_pwm.close()
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue
                try:
                    angle = int(line)
                except ValueError:
                    print(f"Invalid angle received: {line}")
                    continue
                move_servo(angle)
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
            except Exception as e:
                print(f"Unexpected error in main loop: {e}")
    finally:
        if servo_pwm:
            servo_pwm.close()
        if ser.is_open:
            ser.close()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

