import signal
import sys
import time
import logging

try:
    import serial
    from minimalmodbus.client import ModbusSerialClient as ModbusClient
except ImportError:
    logging.error("Required libraries not installed. Install with: pip install pyserial minimalmodbus")
    sys.exit(0)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class ServoMotor:
    """
    Controls a servo motor via Modbus RTU on a Raspberry Pi.
    """

    # Register addresses for the servo motor
    REG_OP_MODE = 0x3500
    REG_POS_CMD = 0x4000
    REG_VEL_CMD = 0x6F00
    REG_POS_FEEDBACK = 0x3700
    REG_VEL_FEEDBACK = 0x3B00
    REG_START = 0x3100
    REG_STOP = 0x3100
    REG_STATUS = 0x3000

    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1, timeout=1.0):
        self.slave_address = slave_address
        self.client = None
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.connected = False

        try:
            self.client = ModbusSerialClient(
                port=port,
                baudrate=baudrate,
                bytesize=8,
                parity='N',
                stopbits=1,
                timeout=self.timeout
            )
            if not self.client.connect():
                raise IOError(f"Failed to connect to Modbus device on {port}")
            self.connected = True
            logger.info(f"Connected to Modbus device on {port} at {baudrate} baud.")
        except Exception as e:
            logger.error(f"Error initializing Modbus client: {e}")
            self.connected = False
            self.client = None

    def _write_register(self, register_address, value):
        if not self.connected or self.client is None:
            raise IOError("Modbus client not connected. Call connect() first.")
        try:
            self.client.write_register(self.slave_address, register_address, value)
            logger.debug(f"Wrote {value:#04x} to register 0x{register_address:04X}")
        except Exception as e:
            logger.error(f"Error writing to register 0x{register_address:04X}: {e}")
            raise

    def _read_register(self, register_address):
        if not self.connected or self.client is None:
            raise IOError("Modbus client not connected. Call connect() first.")
        try:
            result = self.client.read_register(self.slave_address, register_address)
            logger.debug(f"Read {result} from register 0x{register_address:04X}")
            return result
        except Exception as e:
            logger.error(f"Error reading from register 0x{register_address:04X}: {e}")
            raise

    def set_operation_mode(self, mode):
        if not isinstance(mode, int):
            raise ValueError("Operation mode must be an integer.")
        self._write_register(self.REG_OP_MODE, mode)

    def write_position_command(self, position):
        if not isinstance(position, (int, float)):
            raise ValueError("Position must be numeric.")
        self._write_register(self.REG_POS_CMD, int(position))

    def write_velocity_command(self, velocity):
        if not isinstance(velocity, (int, float)):
            raise ValueError("Velocity must be numeric.")
        self._write_register(self.REG_VEL_CMD, int(velocity))

    def read_position_feedback(self):
        return self._read_register(self.REG_POS_FEEDBACK)

    def read_velocity_feedback(self):
        return self._read_register(self.REG_VEL_FEEDBACK)

    def start(self):
        if not self.connected:
            raise IOError("Modbus client not connected. Call connect() first.")
        self._write_register(self.REG_START, 0x000F)

    def stop(self):
        if not self.connected:
            raise IOError("Modbus client not connected. Call connect() first.")
        self._write_register(self.REG_STOP, 0x0006)

    def read_status(self):
        return self._read_register(self.REG_STATUS)

    def close(self):
        if self.client:
            try:
                self.client.close()
                logger.info("Modbus client closed.")
            except Exception as e:
                logger.error(f"Error closing Modbus client: {e}")
            finally:
                self.client = None
                self.connected = False

    def __del__(self):
        self.close()


def main():
    motor = None
    shutdown_requested = False

    def signal_handler(signum, frame):
        nonlocal shutdown_requested
        logger.info(f"Signal {signum} received. Shutting down...")
        shutdown_requested = True

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        motor = ServoMotor(port='/dev/serial0', baudrate=115200, slave_address=1, timeout=1.0)
        if not motor.connected:
            logger.error("Failed to connect to Modbus device on /dev/serial0. Check wiring and permissions.")
            sys.exit(0)

        motor.start()
        logger.info("Servo started.")

        if shutdown_requested:
            return

        motor.write_position_command(128)
        time.sleep(2)
        feedback = motor.read_position_feedback()
        logger.info(f"Position feedback: {feedback}")

        motor.write_velocity_command(50)
        time.sleep(2)
        feedback = motor.read_velocity_feedback()
        logger.info(f"Velocity feedback: {feedback}")

        motor.stop()
        logger.info("Servo stopped.")

    except Exception as e:
        logger.error(f"An error occurred: {e}")
    finally:
        if motor:
            motor.close()
        logger.info("Program finished.")


if __name__ == "__main__":
    main()

