import sys
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Constants
I2C_ADDRESS = 0x36
DRY_SOIL_THRESHOLD = 500
PUMP_GPIO_PIN = 17
READ_INTERVAL_SECONDS = 10

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_soil_sensor(i2c_bus):
    """Initialize the Seesaw soil moisture sensor."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
    except ValueError:
        print(f"Error: No sensor found at I2C address 0x{I2C_ADDRESS:02X}.")
        return None
    except Exception as e:
        print(f"Error initializing soil sensor: {e}")
        return None


def read_soil_moisture(sensor):
    """Read the soil moisture level from the sensor."""
    try:
        return sensor.moisture_read()
    except OSError as e:
        print(f"I2C bus error reading soil moisture: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading soil moisture: {e}")
        return None


def control_water_pump(pump_pin, moisture_level, dry_threshold):
    """Control the water pump based on soil moisture level."""
    if moisture_level is None:
        print("Skipping pump control due to invalid sensor reading.")
        return "UNKNOWN"

    if moisture_level < dry_threshold:
        GPIO.output(pump_pin, GPIO.HIGH)
        return "ON"
    else:
        GPIO.output(pump_pin, GPIO.LOW)
        return "OFF"


def cleanup(i2c_bus=None):
    """Clean up GPIO and I2C resources."""
    try:
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass


def main():
    """Main function to monitor soil moisture and control the water pump."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize GPIO
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PUMP_GPIO_PIN, GPIO.OUT, initial=GPIO.LOW)

    # Initialize I2C and soil sensor
    i2c_bus = initialize_i2c()
    soil_sensor = initialize_soil_sensor(i2c_bus)
    if soil_sensor is None:
        print("Failed to initialize soil sensor. Exiting.")
        cleanup(i2c_bus)
        sys.exit(1)

    print("Soil moisture monitoring started. Press Ctrl+C to exit.")

    try:
        while _running:
            moisture_level = read_soil_moisture(soil_sensor)
            pump_status = control_water_pump(PUMP_GPIO_PIN, moisture_level, DRY_SOIL_THRESHOLD)

            print(f"Soil Moisture: {moisture_level}, Pump: {pump_status}")

            # Sleep in small increments to allow signal handler to interrupt promptly
            for _ in range(READ_INTERVAL_SECONDS):
                if not _running:
                    break
                time.sleep(1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup(i2c_bus)
        print("Program terminated.")


if __name__ == "__main__":
    main()

