import signal
import sys
import json
from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

app = Flask(__name__)

RELAY_PIN = 23
relay = None

def init_relay():
    global relay
    try:
        relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO{RELAY_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        try:
            relay.close()
        except DeviceClosed:
            pass
        except Exception as e:
            print(f"Error during GPIO cleanup: {e}", file=sys.stderr)
    if signum is not None:
        sys.exit(0)

@app.route('/relay', methods=['POST'])
def handle_relay_request():
    try:
        request_data = request.get_json(silent=True)
        if not request_data or 'state' not in request_data:
            return jsonify({'error': 'Invalid request: missing or malformed JSON'}), 400

        relay_state = request_data['state']
        if relay_state == 'on':
            relay.on()
        elif relay_state == 'off':
            relay.off()
        else:
            return jsonify({'error': 'Invalid request: state must be "on" or "off"'}), 400

        return jsonify({'status': 'Relay state changed'}), 200

    except (GPIOZeroError, DeviceClosed) as e:
        print(f"GPIO error: {e}", file=sys.stderr)
        return jsonify({'error': 'GPIO error'}), 500
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        return jsonify({'error': 'Internal server error'}), 500

if __name__ == '__main__':
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    init_relay()
    try:
        app.run(host='0.0.0.0', port=5000)
    finally:
        cleanup()

