import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit_servokit library not found. Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants
SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
STEP_DELAY = 0.04
STEP_SIZE = 5
I2C_BUS = 1
I2C_ADDRESS = 0x40

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_servokit(bus=I2C_BUS, address=I2C_ADDRESS):
    """Initialize the ServoKit on the specified I2C bus and address.

    Returns a ServoKit object or None on failure.
    """
    try:
        return ServoKit(channels=16, i2c=None, address=address)
    except (OSError, ValueError) as e:
        print(f"Error initializing ServoKit on bus {bus} at 0x{address:02X}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        return None


def grab_object(kit, servo_num=SERVO_CHANNEL):
    """Moves the specified servo to grab an object (90 degrees)."""
    if kit is None:
        print("ServoKit not initialized. Cannot grab object.")
        return
    if not 0 <= servo_num <= 15:
        print(f"Invalid servo number: {servo_num}. Must be 0-15.")
        return
    try:
        kit.servo[servo_num].angle = GRAB_ANGLE
        print(f"Servo {servo_num} moved to {GRAB_ANGLE} degrees (grab).")
    except (OSError, ValueError) as e:
        print(f"Error moving servo {servo_num}: {e}")
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")


def release_object(kit, servo_num=SERVO_CHANNEL):
    """Releases the object by moving the servo to 150 degrees."""
    if kit is None:
        print("ServoKit not initialized. Cannot release object.")
        return
    if not 0 <= servo_num <= 15:
        print(f"Invalid servo number: {servo_num}. Must be 0-15.")
        return
    try:
        kit.servo[servo_num].angle = RELEASE_ANGLE
        print(f"Servo {servo_num} moved to {RELEASE_ANGLE} degrees (release).")
    except (OSError, ValueError) as e:
        print(f"Error moving servo {servo_num}: {e}")
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")


def move_servo(kit, servo_num, target_angle):
    """Moves the servo smoothly to the target angle in 5-degree steps."""
    if kit is None:
        print("ServoKit not initialized. Cannot move servo.")
        return
    if not 0 <= servo_num <= 15:
        print(f"Invalid servo number: {servo_num}. Must be 0-15.")
        return
    if not 0 <= target_angle <= 180:
        print(f"Invalid target angle: {target_angle}. Must be 0-180.")
        return
    try:
        current_angle = kit.servo[servo_num].angle
        if current_angle is None:
            current_angle = 0

        step = STEP_SIZE if target_angle > current_angle else -STEP_SIZE
        angle = current_angle
        while _running and angle < target_angle:
            angle += step
            if not _running:
                break
            kit.servo[servo_num].angle = angle
            time.sleep(STEP_DELAY)

        if not _running:
            return

        kit.servo[servo_num].angle = target_angle
        print(f"Servo {servo_num} moved to {target_angle} degrees.")

    except (OSError, ValueError) as e:
        print(f"Error moving servo {servo_num}: {e}")
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")


def main():
    """Main function to demonstrate servo control."""
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        print("Starting servo control sequence...")
        grab_object(kit, SERVO_CHANNEL)
        move_servo(kit, SERVO_CHANNEL, RELEASE_ANGLE)
        release_object(kit, SERVO_CHANNEL)
        print("Servo control sequence completed.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean resource release on all exit paths
        try:
            if kit is not None:
                for servo_num in range(16):
                    kit.servo[servo_num].angle = None
        except Exception:
            pass
        print("ServoKit resources released. Exiting.")


if __name__ == "__main__":
    main()

