        kit.servo[servo_num].angle = target_angle
        print(f"Servo {servo_num} moved to {target_angle} degrees.")

    except (OSError, ValueError) as e:
        print(f"Error moving servo {servo_num}: {e}")
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")


def main():
    """Main function to demonstrate servo control."""
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        print("Starting servo control sequence...")
        grab_object(kit, SERVO_CHANNEL)
        move_servo(kit, SERVO_CHANNEL, RELEASE_ANGLE)
        release_object(kit, SERVO_CHANNEL)
        print("Servo control sequence completed.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean resource release on all exit paths
        try:
            if kit is not None:
                for servo_num in range(16):
                    kit.servo[servo_num].angle = None
        except Exception:
            pass
        print("ServoKit resources released. Exiting.")


if __name__ == "__main__":
    main()

