import time
import logging
import signal
import sys
from smbus2 import SMBus
from ina219 import INA219, DeviceRangeError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

SUPPLY_INA219_ADDRESS = 0x40
BATTERY_INA219_ADDRESS = 0x45
SUPPLY_INA219_SHUNT_RESISTOR = 0.00725
BATTERY_INA219_SHUNT_RESISTOR = 0.005
SUPPLY_INA219_CALIBRATION = 4096
BATTERY_INA219_CALIBRATION = 4096

DEVICE_ID_UPS_PLUS = 0x17

running = True

def signal_handler(sig, frame):
    global running
    running = False

def read_register(bus, address, register):
    try:
        return bus.read_byte_data(address, register)
    except OSError as e:
        logging.error(f"Error reading register {register} from device {hex(address)}: {e}")
        return None

def read_word_data(bus, address, register):
    try:
        return bus.read_word_data(address, register)
    except OSError as e:
        logging.error(f"Error reading word data from register {register} from device {hex(address)}: {e}")
        return None

def read_float_data(bus, address, register):
    try:
        return bus.read_word_data(address, register) / 10.0
    except OSError as e:
        logging.error(f"Error reading float data from register {register} from device {hex(address)}: {e}")
        return None

def wake_ina219(ina219):
    ina219.status = 0
    ina219.set_calibration(BATTERY_INA219_CALIBRATION)
    ina219.set_shunt_voltage(BATTERY_INA219_SHUNT_RESISTOR)
    ina219.wake_up()

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        logging.error(f"Failed to open I2C bus 1: {e}")
        return

    try:
        supply_ina219 = INA219(address=SUPPLY_INA219_ADDRESS, shunt_resistor=SUPPLY_INA219_SHUNT_RESISTOR, busnum=1)
        supply_ina219.wake_up()
        supply_ina219.set_calibration(SUPPLY_INA219_CALIBRATION)
        ina219.status = 0
        ina219.set_calibration(SUPPLY_INA219_CALIBRATION)
        ina219.set_shunt_voltage(SUPPLY_INA219_SHUNT_RESISTOR)
        ina219.wake_up()
        wake_ina219(ina219)

        battery_ina219 = INA219(address=BATTERY_INA219_ADDRESS, shunt_resistor=BATTERY_INA219_SHUNT_RESISTOR, busnum=1)
        battery_ina219.wake_up()
        battery_ina219.set_calibration(BATTERY_INA219_CALIBRATION)
        ina219.set_shunt_voltage(BATTERY_INA219_SHUNT_RESISTOR)
        ina219.wake_up()
        wake_ina219(ina219)

        while running:
            try:
                processor_voltage = read_float_data(bus, DEVICE_ID_UPS_PLUS, 1)
                battery_remaining_capacity = read_float_data(bus, DEVICE_ID_UPS_PLUS, 19)
                power_state = read_word_data(bus, DEVICE_ID_UPS_PLUS, 23)

                if processor_voltage is not None:
                    logging.info(f"Processor Voltage: {processor_voltage:.2f} mV")
                else:
                    logging.warning("Could not read processor voltage.")

                if battery_remaining_capacity is not None:
                    logging.info(f"Battery Remaining Capacity: {battery_remaining_capacity:.2f} %")
                else:
                    logging.warning("Could not read battery remaining capacity.")

                if power_state is not None:
                    logging.info(f"Power State: {power_state}")
                else:
                    logging.warning("Could not read power state.")

                time.sleep(5)
            except DeviceRangeError:
                logging.warning("Device range error encountered. Retrying...")
                time.sleep(5)
            except OSError as e:
                logging.error(f"I2C communication error: {e}. Retrying...")
                time.sleep(5)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        logging.info("Program terminated gracefully.")

if __name__ == "__main__":
    main()

