            raise ValueError(f"Month {dt.month} out of range 1-12.")
        if not 1 <= dt.day <= 31:
            raise ValueError(f"Day {dt.day} out of range 1-31.")

    def _validate_datetime_24h(self, dt: datetime) -> None:
        if not 0 <= dt.hour < 24:
