import signal
import sys
import time

import serial
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
FLOW_THRESHOLD = 10.0
GPIO_PIN = 17
POLL_INTERVAL = 1.0
SERIAL_TIMEOUT = 1.0

_running = True
_serial_port = None
_flow_sensor = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _serial_port, _flow_sensor
    if _flow_sensor is not None:
        _flow_sensor.close()
        _flow_sensor = None
    if _serial_port is not None and _serial_port.is_open:
        try:
            _serial_port.close()
        except Exception:
            pass
        _serial_port = None


def _open_serial():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error opening {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None


def _parse_flow_rate(raw_line):
    if not raw_line:
        return None
    try:
        return float(raw_line)
    except ValueError:
        return None


def _control_water_pump(flow_rate):
    if flow_rate is None:
        return
    if flow_rate > FLOW_THRESHOLD:
        _flow_sensor.on()
    else:
        _flow_sensor.off()


def main():
    global _serial_port, _flow_sensor

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _serial_port = _open_serial()
    if _serial_port is None:
        print("Failed to open serial port. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        _flow_sensor = OutputDevice(GPIO_PIN)
    except Exception as exc:
        print(f"Failed to initialize GPIO {GPIO_PIN}: {exc}", file=sys.stderr)
        _serial_port.close()
        sys.exit(1)

    try:
        while _running:
            try:
                raw_data = _serial_port.readline()
            except serial.SerialException as exc:
                print(f"Serial read error: {exc}", file=sys.stderr)
                break
            except OSError as exc:
                print(f"OS read error: {exc}", file=sys.stderr)
                break

            if not raw_data:
                continue

            try:
                line = raw_data.decode('ascii', errors='replace').strip()
            except Exception:
                continue

            if not line:
                continue

            flow_rate = _parse_flow_rate(line)
            if flow_rate is None:
                print(f"Invalid data received: {line!r}", file=sys.stderr)
                continue

            _control_water_pump(flow_rate)
            print(f"Flow Rate: {flow_rate:.2f} L/min")

            time.sleep(POLL_INTERVAL)

    finally:
        _cleanup()


if __name__ == '__main__':
    main()

