import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_co2_reading(log_file, timestamp, reading):
    line = f"{timestamp} - CO2 Concentration: {reading} ppm\n"
    try:
        log_file.write(line)
        log_file.flush()
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    log_file = None
    try:
        log_file = open(LOG_FILE, 'a', encoding='utf-8')
        print(f"Logging CO2 readings to {LOG_FILE} on {SERIAL_PORT}...")

        while _running:
            try:
                raw_data = serial_port.readline()
                if not raw_data:
                    continue

                data = raw_data.decode('ascii', errors='replace').strip()
                if not data:
                    continue

                try:
                    co2_level = int(data)
                except ValueError:
                    print(f"Warning: Invalid data received (not an integer): {data!r}", file=sys.stderr)
                    continue

                timestamp = datetime.now().isoformat(timespec='seconds')
                log_co2_reading(log_file, timestamp, co2_level)
                print(f"CO2 Concentration: {co2_level} ppm")

            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                break

            except OSError as e:
                print(f"File I/O error: {e}", file=sys.stderr)
                break

            time.sleep(SAMPLE_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if log_file and not log_file.closed:
            try:
                log_file.close()
            except IOError as e:
                print(f"Error closing log file: {e}", file=sys.stderr)
        try:
            if serial_port.is_open:
                serial_port.close()
        except Exception as e:
            print(f"Error closing serial port: {e}", file=sys.stderr)
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

