def parse_data(data):
    try:
        parts = data.split(',')
        if len(parts) != 2:
            raise ValueError(f'Expected 2 fields, got {len(parts)}')
        heart_rate = int(parts[0].strip())
        spo2 = int(parts[1].strip())
        return heart_rate, spo2
    except ValueError as e:
        print(f'Error parsing data: {e} - Raw: {data!r}', file=sys.stderr)
        return None, None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud')
            while running:
                try:
                    raw_line = ser.readline()
                    if not raw_line:
                        continue

                    line = raw_line.decode('ascii', errors='replace').strip()
                    if not line:
                        continue

                    heart_rate, spo2 = parse_data(line)
                    if heart_rate is not None and spo2 is not None:
                        print(f'Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')
                        log_data(heart_rate, spo2)
                    else:
                        print('Failed to parse data, raw: ' + line, file=sys.stderr)

                    time.sleep(5)

                except serial.SerialException as e:
                    print(f'Serial I/O error: {e}', file=sys.stderr)
                    time.sleep(5)
                except Exception as e:
                    print(f'Unexpected error: {e}', file=sys.stderr)
                    time.sleep(5)
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
    except Exception as e:
        print(f'Fatal error: {e}', file=sys.stderr)
    finally:
        print('Exiting program')

if __name__ == '__main__':
    main()

