import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


@dataclass
class GPS_readings:
    """Represents GPS readings parsed from a GPGGA sentence."""
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None


class GPSReader:
    """Robust GPS reader for /dev/serial0 at 9600 baud on Raspberry Pi."""

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._closed = False

    def connect(self) -> None:
        """Open the serial port; raise on failure."""
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logger.info("Connected to GPS on %s at %d baud.", self.port, self.baudrate)
        except serial.SerialException as exc:
            logger.error("Failed to open serial port %s: %s", self.port, exc)
            raise

    def disconnect(self) -> None:
        """Idempotent close; never raises."""
        if self._closed:
            return
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    logger.info("Closed serial port %s.", self.port)
            except serial.SerialException as exc:
                logger.warning("Error while closing serial port: %s", exc)
            finally:
                self.serial_port = None
                self._closed = True

    def read_line(self) -> Optional[str]:
        """Read one line from the serial port. Returns None on timeout."""
        if self.serial_port is None or not self.serial_port.is_open:
            return None
        try:
            raw = self.serial_port.readline()
        except serial.SerialException as exc:
            logger.warning("Serial read error: %s", exc)
            return None
        if not raw:
            return None
        return raw.decode("ascii", errors="replace").strip()

    def parse_gpgga(self, line: str) -> GPS_readings:
        """Parse a GPGGA sentence; return a dataclass with None fields on failure."""
        if not line.startswith(b"GPGGA"):
            return GPS_readings()
        parts = line.split(",")
        if len(parts) < 15:
            logger.warning("GPGGA sentence too short: %r", line)
            return GPS_readings()
        talker = parts[1]
        if not talker:
            logger.warning("GPGGA: talker field is empty")
            return GPS_readings()
        try:
            fix_quality = int(parts[6])
        except ValueError:
            logger.warning("GPGGA: field 6 is not numeric")
            return GPS_readings()
        if fix_quality == 0:
            logger.info("GPGGA: no fix (quality=%d)", fix_quality)
            return GPS_readings()
        try:
            lat = self._to_decimal(parts[2], parts[3])
            lon = self._to_decimal(parts[4], parts[5])
        except (IndexError, ValueError) as exc:
            logger.warning("GPGGA: invalid lat/lon fields: %s", exc)
            return GPS_readings()
        return GPS_readings(
            latitude=lat,
            longitude=lon,
            altitude=float(parts[7]) if len(parts) > 7 else None,
            satellite_count=int(parts[8]) if len(parts) > 8 else None,
        )

    @staticmethod
    def _to_decimal(n: str, dec: str) -> float:
        """Convert NMEA ddmm.mmmm to decimal degrees."""
        if not n or not dec:
            raise ValueError("Empty coordinate field")
        try:
            deg_len = len(n) - 2
            if deg_len < 1:
                raise ValueError("Coordinate too short")
            deg = int(n[:deg_len])
            minutes = float(n[deg_len:])
            decimal = deg + minutes / 60.0
            if decimal >= 72.0:
                decimal -= 360.0
            return decimal
        except (ValueError, IndexError) as exc:
            raise ValueError(f"Invalid coordinate {n!r}: {exc}") from exc

    def run(self) -> None:
        """Continuously read and parse GPGGA sentences until interrupted."""
        while not self._closed:
            line = self.read_line()
            if line is None:
                continue
            readings = self.parse_gpgga(line)
            if readings.latitude is not None:
                logger.info(
                    "Lat=%.6f Lon=%.6f alt=%.1f m sats=%d",
                    readings.latitude,
                    readings.longitude,
                    readings.altitude,
                    readings.satellite_count,
                )


def _signal_handler(signum, frame):
    logger.info("Signal %d received, shutting down.", signum)
    sys.exit(0)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    reader = GPSReader(port="/dev/serial0", baudrate=9600, timeout=1.0)
    try:
        reader.connect()
        reader.run()
    except serial.SerialException as exc:
        logger.error("Serial error: %s", exc)
    except Exception as exc:
        logger.error("Unexpected error: %s", exc)
    finally:
        reader.disconnect()


if __name__ == "__main__":
    main()

