        """Power on the GPS module (GNSS)."""
        if not self._running:
            return False
        try:
            self.serial_port.write(b'AT+CGNSPWR=1\r\n')
            self.serial_port.flush()
            time.sleep(1)
            return True
        except serial.SerialException as e:
            print(f"Error powering on GPS: {e}")
            return False

