        """Power off the GPS module (GNSS)."""
        if not self._running:
            return False
        try:
            self.serial_port.write(b'AT+CGNSPWR=0\r\n')
            self.serial_port.flush()
            return True
        except serial.SerialException as e:
            print(f"Error powering off GPS: {e}")
            return False

