                if not line.startswith('$GPRMC'):
                    return None
                parts = line.split(',')
                if len(parts) < 10:
                    return None
                if parts[2] == 'A':
                    return parts
                return None
            return None
        except serial.SerialException as e:
            print(f"Error reading GPS data: {e}")
            return None

