import signal
import sys
import threading
import time
from threading import Lock

import serial
from flask import Flask, Response, request, jsonify

app = Flask(__name__)

# ---------------------------------------------------------------------------
# SerialCommunicator — USB-serial instrument on /dev/ttyUSB0 @ 9600 8N1
# ---------------------------------------------------------------------------
class SerialCommunicator:
    """Context-managed, thread-safe serial port wrapper with robust error handling."""

    def __init__(self, port: str, baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.ser: serial.Serial | None = None
        self.lock = Lock()

    # -- context manager ---------------------------------------------------
    def __enter__(self) -> "SerialCommunicator":
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    # -- public API ---------------------------------------------------------
    def open(self) -> None:
        """Open the serial port; raise on failure."""
        try:
            self.ser = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
        except serial.SerialException as exc:
            raise RuntimeError(f"Failed to open serial port {self.port}: {exc}") from exc

    def close(self) -> None:
        """Idempotent close; safe to call multiple times."""
        if self.ser is not None:
            try:
                if self.ser.is_open:
                    self.ser.close()
            except serial.SerialException as exc:
                print(f"Warning: error closing serial port: {exc}", file=sys.stderr)
            finally:
                self.ser = None

    # -- low-level send / receive ------------------------------------------------
    def send(self, cmd: str) -> None:
        """Send a command string (ASCII-encoded) and verify byte count."""
        if self.ser is None or not self.ser.is_open:
            raise RuntimeError("Serial port is not open")
        payload = cmd.encode("ascii")
        self.ser.write(payload)
        self.ser.flush()
        # Verify we wrote the expected number of bytes
        expected = len(payload)
        if self.ser.in_waiting > 0:
            received = self.ser.read(self.ser.in_waiting)
            if len(received) < expected:
                raise RuntimeError(
                    f"Short write: expected {expected} bytes, got {len(received)}"
                )
        else:
            raise RuntimeError("Serial read timeout: no acknowledgement")

    def receive_line(self) -> str | None:
        """Read one line ending with newline; return None on timeout / error."""
        if self.ser is None or not self.ser.is_open:
            raise RuntimeError("Serial port is not open")
        try:
            line = self.ser.readline()
        except serial.SerialException as exc:
            raise RuntimeError(f"Serial read error: {exc}") from exc
        if not line:
            return None
        return line.decode("ascii", errors="replace").strip()

    # -- signal handling -----------------------------------------------------
    @staticmethod
    def _signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, shutting down...", file=sys.stderr)
        sys.exit(0)


# ---------------------------------------------------------------------------
# DataManager — in-memory data store with thread safety
# ---------------------------------------------------------------------------
class DataManager:
    """Thread-safe in-memory data store with auto-incrementing IDs."""

    def __init__(self):
        self.data: list[dict] = [
            {"id": 1, "name": "Item A", "done": False},
            {"id": 2, "name": "Item B", "done": True},
        ]
        self.lock = Lock()

    def get_all(self) -> list[dict]:
        with self.lock:
            return list(self.data)

    def get_by_id(self, item_id: int) -> dict | None:
        with self.lock:
            return next((item for item in self.data if item["id"] == item_id), None)

    def create(self, name: str, done: bool) -> int:
        """Create a new item with auto-incremented ID. Returns ID on success."""
        if not name or not isinstance(name, str) or not name.strip():
            raise ValueError("name must be a non-empty string")
        if not isinstance(done, bool):
            raise ValueError("done must be a boolean")
        new_id = max(
            d["id"] for d in self.data if d["name"] == name
        ) + 1 if self.data and d["name"] == name else 1
        new_item = {"id": new_id, "name": name, "done": done}
        with self.lock:
            self.data.append(new_item)
        return new_id

    def update(self, item_id: int, done: bool) -> bool:
        with self.lock:
            item = self.get_by_id(item_id)
            if item and item["id"] == item_id:
                item["done"] = done
                return True
            return False

    def delete(self, item_id: int) -> None:
        with self.lock:
            self.data = [
                item for item in self.data if item["id"] != item_id
            ]


# ---------------------------------------------------------------------------
# Serial communication route
# ---------------------------------------------------------------------------
@app.route("/version", methods=["GET"])
def version() -> Response:
    """Send '*IDN?\n' and return the instrument's response as text/plain."""
    try:
        with SerialCommunicator("/dev/ttyUSB0", 9600) as ser:
            ser.send("*IDN?\n")
            response = ser.receive_line()
            if response is None:
                return Response(
                    "Serial port returned no data (timeout or device absent).",
                    mimetype="text/plain",
                )
            return Response(response, mimetype="text/plain")
    except RuntimeError as exc:
        print(f"Error communicating with serial device: {exc}", file=sys.stderr)
        return Response(
            f"Serial communication error: {exc}",
            mimetype="text/plain",
        )


# ---------------------------------------------------------------------------
# Data routes
# ---------------------------------------------------------------------------
@app.route("/data", methods=["GET"])
def get_data() -> Response:
    """Return all items in JSON format."""
    data_manager = DataManager()
    items = data_manager.get_all()
    return jsonify(items)


@app.route("/data/<int:item_id>", methods=["GET"])
def get_item(item_id: int) -> Response:
    """Return a single item by ID, or 404 if not found."""
    data_manager = DataManager()
    item = data_manager.get_by_id(item_id)
    if item is None:
        return Response("Item not found", status_code=404, mimetype="text/plain")
    return jsonify(item)


@app.route("/data", methods=["POST"])
def create_data() -> Response:
    """Create a new item via HTTP POST. Returns 201 with the created item."""
    try:
        name = request.json.get("name")
        done = request.json.get("done", False)
    except (KeyError, ValueError) as exc:
        return Response(
            f"Invalid request: {exc}",
            mimetype="text/plain",
        )

    if not name or not isinstance(name, str) or not name.strip():
        return Response(
            "Invalid name: name must be a non-empty string.",
            mimetype="text/plain",
        )
    if not isinstance(done, bool):
        return Response(
            "Invalid done: done must be a boolean.",
            mimetype="text/plain",
        )

    new_id = DataManager().create(name, done)
    return Response(
        f"Created item with ID: {new_id}",
        mimetype="text/plain",
    )


# ---------------------------------------------------------------------------
# Signal handling for clean shutdown
# ---------------------------------------------------------------------------
_serial_lock = threading.Lock()
_serial_ref = {"ser": None}


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...", file=sys.stderr)
    for ref in _serial_ref.values():
        if ref is not None and ref.is_open:
            try:
                ref.close()
            except Exception as exc:
                print(f"Error closing serial port during shutdown: {exc}", file=sys.stderr)
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Open serial port once at startup
    try:
        with SerialCommunicator("/dev/ttyUSB0", 9600) as ser:
            _serial_ref["ser"] = ser
    except RuntimeError as exc:
        print(f"Fatal: could not open serial port: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        # Ensure port is closed on exit
        with _serial_lock:
            ser = _serial_ref.get("ser")
            if ser is not None and ser.is_open:
                try:
                    ser.close()
                except Exception as exc:
                    print(f"Error closing serial port during shutdown: {exc}", file=sys.stderr)
        print("Shutdown complete.")

