import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
READ_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def parse_pulse_data(data):
    """Parse a pulse oximeter line '<heart_rate>,<spo2>'."""
    if not data:
        return None, None
    parts = data.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}: '{data}'")
    heart_rate, spo2 = parts[0].strip(), parts[1].strip()
    return heart_rate, spo2

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            try:
                line = raw.decode('ascii', errors='replace').strip()
            except Exception as e:
                print(f"Decode error: {e}", file=sys.stderr)
                continue

            try:
                heart_rate, spo2 = parse_pulse_data(line)
            except ValueError as e:
                print(f"Invalid data format: {e} ({line})")
                continue

            if heart_rate is not None and spo2 is not None:
                print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

            time.sleep(READ_INTERVAL)

    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

