import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'power_consumption.log'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_power_consumption(power_value):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Power: {power_value} W\n'
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry)
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')
            while _running:
                try:
                    raw_line = ser.readline()
                    if not raw_line:
                        continue
                    line = raw_line.decode('ascii', errors='replace').strip()
                    if not line:
                        continue
                    try:
                        power_value = float(line)
                        log_power_consumption(power_value)
                    except ValueError:
                        print(f'Warning: non-numeric data received: {line!r}', file=sys.stderr)
                except serial.SerialException as e:
                    print(f'Serial communication error: {e}', file=sys.stderr)
                    break
    except serial.SerialException as e:
        print(f'Error opening serial port {SERIAL_PORT}: {e}', file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f'Error accessing serial port {SERIAL_PORT}: {e}', file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

