import serial
import time
import sys

BLUETOOTH_PORT = '/dev/rfcomm4'
BAUD_RATE = 38400
COMMAND_PREFIX = 'X'
COMMAND_TERMINATOR = '\n'
DELAY_SECONDS = 0.1


def send_command(serial_connection, command):
    """Sends a command to the Bluetooth device with error handling."""
    try:
        payload = f'{COMMAND_PREFIX}{command}{COMMAND_TERMINATOR}'.encode('utf-8')
        bytes_written = serial_connection.write(payload)
        serial_connection.flush()
        if bytes_written != len(payload):
            print(f"Warning: incomplete write ({bytes_written}/{len(payload)} bytes).", file=sys.stderr)
        print(f"Sent: {command}")
    except serial.SerialException as e:
        raise RuntimeError(f"Serial communication error: {e}")
    except OSError as e:
        raise RuntimeError(f"OS-level I/O error: {e}")


def main():
    try:
        serial_connection = serial.Serial(
            port=BLUETOOTH_PORT,
            baudrate=BAUD_RATE,
            timeout=1
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {BLUETOOTH_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error opening {BLUETOOTH_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                user_command = input('Enter command (or "exit" to quit): ')
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.strip().lower() == 'exit':
                break

            try:
                send_command(serial_connection, user_command)
            except RuntimeError as e:
                print(f"Command failed: {e}", file=sys.stderr)
                break

            time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if serial_connection.is_open:
            serial_connection.close()
            print("Serial connection closed.")


if __name__ == "__main__":
    main()

